// Psarema: the best natural baits for each fish in each fishing area (ids of data/areas.js), best first, researched per area
// (2026-10-27, one researcher per stretch of coast; sources below). js/ui.js spotBaits() uses these for a spot inside an area and
// falls back to the fish's Cyprus-wide baits (data/gear-*.js) elsewhere. gear: bait ids of data/gear-catalog.js; src: keys of PSAREMA_AREA_BAIT_SOURCES.
// Loaded with the gear files (js/core.js loadGear). Checked by scripts/check-area-gear.js.
window.PSAREMA_AREA_BAITS = {
  pomos: {
    sargos: [{"gear":"worm","best":true,"note":{"en":"Pharaoh worm (φαραώ), whole or salted to firm it, in the foam off the rocky points and shelter breakwaters, from 2 h before dusk into the night, Oct–Apr.","el":"Φαραώ ολόκληρο ή παστωμένο για να σφίξει, στον αφρό στα βραχώδη ακρωτήρια και στους μόλους των καταφυγίων, από δύο ώρες πριν το σούρουπο ως τη νύχτα, Οκτ–Απρ."},"src":["pomos_cytech","pomos_bf_sargos"]},{"gear":"shrimp","note":{"en":"Live small shrimp (γαριδούλα) under a bolognese float in the white water a moderate northerly throws on the points; fresh peeled shrimp if no live.","el":"Ζωντανή γαριδούλα σε φελλό (bolognese) στον αφρό που σηκώνει ένας μέτριος βοριάς στα ακρωτήρια· φρέσκια καθαρισμένη γαρίδα αν δεν βρεις ζωντανή."},"src":["pomos_bf_sargos","pomos_cytilt"]},{"gear":"sardine","note":{"en":"Firm sardine-and-rusk dough over a μαλάγρα of sardine scraps and sand at the deeper rocky spots; make it firmer than for mullet. Cypriot apiko method.","el":"Σφικτό ζυμάρι σαρδέλας με φρυγανιά πάνω από μαλάγρα με απομεινάρια σαρδέλας και άμμο, στα πιο βαθιά βράχια· πιο σκληρό απ’ ό,τι για κέφαλο. Κυπριακό απίκο."},"src":["pomos_cyapiko"]},{"gear":"mussel","note":{"en":"Limpet (πεταλίδα) prised off the same rocks, or mussel bound with elastic thread: tough, free bait that Cypriot anglers rate highly for big sargos.","el":"Πεταλίδα από τα ίδια βράχια ή μύδι δεμένο με λαστιχένια κλωστή: σκληρό, δωρεάν δόλωμα που οι Κύπριοι ψαράδες εκτιμούν πολύ για μεγάλους σαργούς."},"src":["pomos_cytech","pomos_bf_sargos"]}],
    tsipoura: [{"gear":"crab","best":true,"note":{"en":"Whole small crab or a big crab claw on the surf rig at night in the pebble-and-Posidonia coves (Pachyammos, Pomos beach), Nov–Feb; small fish can't strip it.","el":"Ολόκληρο καβουράκι ή μεγάλη δαγκάνα σε σύνθεση surf τη νύχτα στους κολπίσκους με βότσαλο και ποσειδωνία (Πάχυαμμος, παραλία Πωμού), Νοέ–Φεβ· τα μικρά δεν το κλέβουν."},"src":["pomos_bf_tsip"]},{"gear":"worm","note":{"en":"Whole pharaoh (φαραώ) or a long American/acrobat worm threaded on with a needle, at dusk and first light where sand meets Posidonia in 2–8 m.","el":"Ολόκληρο φαραώ ή μακρύς αμερικάνος/ακροβάτης περασμένος με βελόνα, σούρουπο και χαράματα εκεί που η άμμος συναντά την ποσειδωνία στα 2–8 μ."},"src":["pomos_cytech","pomos_bf_tsip"]},{"gear":"mussel","note":{"en":"Winter shellfish: cracked purple dye-murex (πορφύρα) flesh, or 2–3 mussels bound with elastic thread; big gilthead go for πορφύρα in the cold months.","el":"Όστρακα τον χειμώνα: σπασμένη πορφύρα με το αγκίστρι να βγαίνει από την άλλη άκρη, ή 2–3 μύδια με λαστιχένια κλωστή· οι μεγάλες τσιπούρες τρελαίνονται για πορφύρα."},"src":["pomos_bf_tsip"]},{"gear":"shrimp","note":{"en":"Live shrimp at night beside the Pomos and Kato Pyrgos shelter breakwaters, over sand and stones; general Cypriot practice, not a local report.","el":"Ζωντανή γαρίδα τη νύχτα δίπλα στους μόλους των καταφυγίων Πωμού και Κάτω Πύργου, σε άμμο και πέτρα· γενική κυπριακή πρακτική, όχι τοπική αναφορά."},"src":["pomos_cytilt"]}],
    melanouri: [{"gear":"sardine","best":true,"note":{"en":"Sardine-and-rusk dough (ζυμάρι σαρδέλας) on a small hook inside a sardine μαλάγρα at the deeper rocky spots: the Cypriot apiko bait for μελάνες and σαργούς.","el":"Ζυμάρι σαρδέλας με φρυγανιά σε μικρό αγκίστρι μέσα σε μαλάγρα σαρδέλας στα πιο βαθιά βράχια: το κυπριακό δόλωμα του απίκου για μελάνες και σαργούς."},"src":["pomos_cyapiko"]},{"gear":"bread","note":{"en":"Bread flake or soft bread dough on a size 12–14 hook under a light float in the same μαλάγρα, mornings and late afternoon, Apr–Oct; general practice.","el":"Ψίχα ή μαλακό ζυμάρι ψωμιού σε αγκίστρι Νο 12–14 με ελαφρύ φελλό στην ίδια μαλάγρα, πρωί και αργά το απόγευμα, Απρ–Οκτ· γενική πρακτική."}},{"gear":"groundbait","note":{"en":"Little-and-often μαλάγρα of fish scraps, sardine, sand, gravel and old frying oil: the sand carries the smell down and holds the shoal by your float.","el":"Λίγη και συχνή μαλάγρα από απομεινάρια ψαριών, σαρδέλα, άμμο, χαλίκι και καμένο λάδι: η άμμος παίρνει τη μυρωδιά στον βυθό και κρατά το κοπάδι στον φελλό."},"src":["pomos_cyapiko"]},{"gear":"shrimp","note":{"en":"Small peeled shrimp pieces on a size 12–14 hook when the shoal ignores bread, drifted mid-water near the drop; general practice.","el":"Μικρά κομματάκια καθαρισμένης γαρίδας σε αγκίστρι Νο 12–14 όταν το κοπάδι αγνοεί το ψωμί, στα μεσόνερα κοντά στο κατέβασμα· γενική πρακτική."}}],
    squid: [{"gear":"sardine","best":true,"note":{"en":"Whole fresh sardine or small mackerel on a καφτερό under a float with a chemical light, off the Pomos or Kato Pyrgos breakwater at nightfall, Nov–Mar.","el":"Ολόκληρη φρέσκια σαρδέλα ή σκουμπράκι στο καφτερό κάτω από φελλό με χημικό φωτάκι, στον μόλο του Πωμού ή του Κάτω Πύργου όταν νυχτώνει, Νοέ–Μαρ."},"src":["pomos_bf_kalam","pomos_cykalam","pomos_latchi"]},{"gear":"live_fish","note":{"en":"A live small bogue (γόππα) or horse mackerel from a sabiki on a squid needle, drifted from a boat over Posidonia at 10–30 m at dusk; general, not local.","el":"Ζωντανή μικρή γόππα ή σαυρίδι από τσαπαρί σε καλαμαριέρα για ζωντανό, σε ντρίφτ από βάρκα πάνω από ποσειδωνία στα 10–30 μ. το σούρουπο· γενικό, όχι τοπικό."}}],
    bluefish: [{"gear":"sardine","best":true,"note":{"en":"Half a sardine on a long-shank or wire-trace hook, float or light ledger at dusk and night by the Pyrgos river mouth and Kato Pyrgos breakwater, Oct–Jan.","el":"Μισή σαρδέλα σε αγκίστρι με μακρύ λαιμό ή συρμάτινο παράμαλλο, με φελλό ή ελαφρύ βαρίδι σούρουπο και νύχτα στις εκβολές του ποταμού Πύργου και στον μόλο, Οκτ–Ιαν."},"src":["pomos_cyfish","pomos_cytech"]},{"gear":"live_fish","note":{"en":"Live sand smelt (αθερίνα) or garfish (ζαργάνα) free-lined off the points at first light; Cypriot boats troll the same baits for γοφάρι in Jul–Aug.","el":"Ζωντανή αθερίνα (θερίνι) ή ζαργάνα ελεύθερη μπροστά στα ακρωτήρια με το πρώτο φως· τα κυπριακά σκάφη σέρνουν τα ίδια δολώματα για γοφάρι Ιούλ–Αύγ."},"src":["pomos_cyfish"]},{"gear":"squid_bait","note":{"en":"Squid strip 8–10 cm when bait thieves keep stripping the sardine; it survives several bites and the bluefish still hits it.","el":"Λωρίδα καλαμαριού 8–10 εκ. όταν τα μικρά σού καθαρίζουν τη σαρδέλα· αντέχει σε πολλά τσιμπήματα και το γοφάρι τη χτυπά κανονικά."},"src":["pomos_cyfish"]}],
    leerfish: [{"gear":"live_fish","best":true,"note":{"en":"Live mullet (κέφαλος) 15–25 cm, nose-hooked under a small float, at dawn and dusk by the Pyrgos and Pomos stream mouths and shelter entrances, Sep–Dec.","el":"Ζωντανός κέφαλος 15–25 εκ. από τη μύτη, με μικρό φελλό, χαράματα και σούρουπο στις εκβολές των ρυακιών Πύργου και Πωμού και στα στόμια των καταφυγίων, Σεπ–Δεκ."},"src":["pomos_hf_litsa","pomos_cyfish"]},{"gear":"sardine","note":{"en":"Fallback when no live mullet: a dead garfish (ζαργάνα) or whole fresh sardine slow-trolled a few metres down along the points at 3–4 knots.","el":"Αν δεν έχεις ζωντανό κέφαλο: νεκρή ζαργάνα ή ολόκληρη φρέσκια σαρδέλα σε αργή συρτή λίγα μέτρα κάτω από την επιφάνεια κατά μήκος των ακρωτηρίων, 3–4 κόμβοι."},"src":["pomos_hf_litsa"]}],
    dentex: [{"gear":"squid_bait","best":true,"note":{"en":"Live medium squid (30–40 cm) jigged at dusk off the shelters, slow-trolled on a lead down the steep 40–80 m edge 1.5–2 km out in winter; mornings best.","el":"Ζωντανό μεσαίο καλαμάρι (30–40 εκ.) από τα καταφύγια το σούρουπο, σε συρτή με μολύβι φύλακα στο απότομο κατέβασμα 40–80 μ., 1,5–2 χλμ. έξω, τον χειμώνα· καλύτερα πρωί."},"src":["pomos_bf_dentex"]},{"gear":"live_fish","note":{"en":"Live bogue (γόππα) 15–20 cm or horse mackerel from a sabiki, near the bottom on the drop-off edge in Apr–Oct when squid are scarce; let it run before striking.","el":"Ζωντανή γόππα 15–20 εκ. ή σαυρίδι από τσαπαρί, κοντά στον βυθό στην άκρη του κατεβάσματος Απρ–Οκτ, όταν δεν υπάρχουν καλαμάρια· άφησέ τη να τρέξει πριν καρφώσεις."},"src":["pomos_bf_dentex","pomos_pyrgos"]}],
    porgy: [{"gear":"squid_bait","best":true,"note":{"en":"Squid strip or tentacle on a 2-hook drop rig, drifting the 40–100 m slope 1.5–2.5 km off Pomos, Jan–Apr; tough enough to outlast small bream.","el":"Λωρίδα ή πλοκάμι καλαμαριού σε καθετή με δύο αγκίστρια, σε ντρίφτ στην κατωφέρεια 40–100 μ., 1,5–2,5 χλμ. έξω από τον Πωμό, Ιαν–Απρ· αντέχει στα μικρά σπαροειδή."}},{"gear":"live_fish","note":{"en":"Live small fish (bogue, picarel) on the deep rough ground off Pomos for the biggest porgy. General, not local.","el":"Ζωντανό ψαράκι (γόππα, μαρίδα) στα βαθιά τραχιά ανοιχτά του Πωμού για τα μεγάλα φαγκριά. Γενική πρακτική, όχι τοπική."}},{"gear":"sardine","note":{"en":"Fresh sardine or a fish fillet on the same drift rig, cut so the scent runs; a good second bait when squid is short.","el":"Φρέσκια σαρδέλα ή φιλέτο ψαριού στην ίδια αρματωσιά, κομμένα ώστε να βγάζουν μυρωδιά· καλό δεύτερο δόλωμα όταν λείπει το καλαμάρι."}}],
    pandora: [{"gear":"shrimp","best":true,"note":{"en":"Whole shrimp on a 2–3 hook καθετή held tight to the bottom at 30–100 m on mixed ground beyond the Posidonia edge, 1–2.5 km out, Apr–Aug.","el":"Ολόκληρη γαρίδα σε καθετή με 2–3 αγκίστρια κολλητά στον βυθό στα 30–100 μ., σε μικτό βυθό πέρα από την άκρη της ποσειδωνίας, 1–2,5 χλμ. έξω, Απρ–Αύγ."},"src":["pomos_bf_lythr"]},{"gear":"squid_bait","note":{"en":"Squid tentacle, the other standard pandora bait: it stays on through the nibbling and tends to pick out the bigger fish.","el":"Πλοκάμι καλαμαριού, το άλλο βασικό δόλωμα για λυθρίνια: κρατάει στα τσιμπήματα και ξεχωρίζει τα μεγαλύτερα ψάρια."},"src":["pomos_bf_lythr"]},{"gear":"worm","note":{"en":"Worm pieces (American or similar) in shallower 20–40 m water in spring and summer; general practice, not local.","el":"Κομμάτια σκουληκιού (αμερικάνος ή παρόμοιο) σε ρηχότερα νερά 20–40 μ. άνοιξη και καλοκαίρι· γενική πρακτική, όχι τοπική."}}],
    grouper: [{"gear":"squid_bait","best":true,"note":{"en":"Small octopus, live or fresh (even frozen), or a cuttlefish, on a 2-hook rig at first dark by the few rocky reef patches at 20–60 m: the first-choice grouper bait.","el":"Μικρό χταπόδι, ζωντανό ή νωπό (πιάνει και κατεψυγμένο), ή σουπιά, σε αρματωσιά με δύο αγκίστρια με το πρώτο σκοτάδι στις λίγες βραχώδεις ξέρες στα 20–60 μ."},"src":["pomos_dr_rofos","pomos_cyfish"]},{"gear":"live_fish","note":{"en":"Live bogue (γόππα) or small horse mackerel 12–18 cm, slow-trolled close past rock at 20–50 m at dawn or dusk.","el":"Ζωντανή γόππα ή μικρό σαυρίδι 12–18 εκ. σε αργή συρτή κοντά στα βράχια στα 20–50 μ., χαράματα ή σούρουπο."},"src":["pomos_dr_rofos"]},{"gear":"sardine","note":{"en":"Whole dead sardine, bogue or horse mackerel: the last choice for grouper; use it big, as bigger baits draw bigger fish.","el":"Ολόκληρη νεκρή σαρδέλα, γόππα ή σαυρίδι: η τελευταία επιλογή για ροφό· βάλ’ το μεγάλο, γιατί μεγάλο δόλωμα φέρνει μεγάλο ψάρι."},"src":["pomos_dr_rofos"]}],
    amberjack: [{"gear":"live_fish","best":true,"note":{"en":"Live bogue, horse mackerel or garfish, slow-trolled under 1 knot on a ~500 g lead along the 40–80 m drop-off 1–2 km out, Jun–Oct; 2–3 hooks 6/0–8/0.","el":"Ζωντανή γόππα, σαυρίδι ή ζαργάνα σε αργή συρτή κάτω από 1 κόμβο με μολύβι ~500 γρ. στο κατέβασμα 40–80 μ., 1–2 χλμ. έξω, Ιούν–Οκτ· 2–3 αγκίστρια 6/0–8/0."},"src":["pomos_dr_magiat","pomos_ytlatchi","pomos_latchi"]},{"gear":"squid_bait","note":{"en":"Live squid from November, caught at dusk off the breakwaters and slow-trolled the same way, hooked through the tail; live cuttlefish in spring.","el":"Ζωντανό καλαμάρι από τον Νοέμβριο, από τους μόλους το σούρουπο, σε αργή συρτή με τον ίδιο τρόπο, αγκιστρωμένο από την ουρά· ζωντανή σουπιά την άνοιξη."},"src":["pomos_dr_magiat"]}],
    littletunny: [{"gear":"live_fish","best":true,"note":{"en":"Live sand smelt (αθερίνα) or small horse mackerel free-lined into a school feeding off the points or over the steep shelf; mornings and dusk, Aug–Nov.","el":"Ζωντανή αθερίνα (θερίνι) ή μικρό σαυρίδι ελεύθερο μέσα στο κοπάδι που τρώει μπροστά στα ακρωτήρια ή πάνω από την απότομη υφαλοκρηπίδα· πρωί και σούρουπο, Αύγ–Νοέ."},"src":["pomos_bf_tuna"]},{"gear":"sardine","note":{"en":"Sardine chunks thrown as chum from a drifting boat, with a hooked chunk sinking freely among them; general practice, not local.","el":"Κομμάτια σαρδέλας για μαλάγρα από βάρκα σε ντρίφτ, με ένα δολωμένο κομμάτι να βυθίζεται ελεύθερα ανάμεσά τους· γενική πρακτική, όχι τοπική."}}],
    dolphinfish: [{"gear":"sardine","best":true,"note":{"en":"Fresh sardine pieces thrown to hold a school found under floating debris, with a hooked piece drifting among them; keep one fish on the line, Sep–Nov.","el":"Κομμάτια φρέσκιας σαρδέλας για να κρατήσεις το κοπάδι που βρήκες κάτω από επιπλέοντα αντικείμενα, με δολωμένο κομμάτι ανάμεσά τους· κράτα ένα ψάρι στο νερό, Σεπ–Νοέ."},"src":["pomos_bf_kyn"]},{"gear":"squid_bait","note":{"en":"Small whole squid (καλαμαράκι) or strips on the same free line; deep blue water starts only ~2 km off Pomos, so the run out is short.","el":"Μικρό ολόκληρο καλαμαράκι ή λωρίδες στην ίδια ελεύθερη πετονιά· τα βαθιά νερά αρχίζουν μόλις ~2 χλμ. έξω από τον Πωμό, άρα η διαδρομή είναι μικρή."},"src":["pomos_bf_kyn"]},{"gear":"live_fish","note":{"en":"A small live fish free-lined beside the floating object; general practice, not local.","el":"Μικρό ζωντανό ψαράκι ελεύθερο δίπλα στο επιπλέον αντικείμενο· γενική πρακτική, όχι τοπική."}}],
    octopus: [{"gear":"crab","best":true,"note":{"en":"A real crab (or imitation) tied on a white χταποδιέρα, dragged slowly over rock and rock–sand edges near the points, mid-autumn to winter, mornings.","el":"Αληθινό καβούρι (ή ομοίωμα) δεμένο σε άσπρη χταποδιέρα, σερνόμενο αργά σε βράχο και στα όρια βράχου–άμμου κοντά στα ακρωτήρια, μέσα φθινοπώρου ως χειμώνα, πρωί."},"src":["pomos_dr_chtap"]},{"gear":"sardine","note":{"en":"Fresh small fish (sardine, bogue) tied to the jig, or chicken feet; good when you can't find crabs.","el":"Νωπά ψαράκια (σαρδέλα, γόππα) δεμένα στη χταποδιέρα ή κοτοπόδαρα· καλά όταν δεν βρίσκεις καβούρια."},"src":["pomos_dr_chtap"]}],
    parrotfish: [{"gear":"shrimp","best":true,"note":{"en":"Small shrimp on a size 8–10 hook, float set just under the surface by the rocky points' Posidonia edge, 6–10 am or dusk, May–Sep.","el":"Μικρή γαρίδα σε αγκίστρι Νο 8–10, φελλός ρυθμισμένος λίγο κάτω από την επιφάνεια, στην άκρη της ποσειδωνίας στα βραχώδη ακρωτήρια, 6–10 το πρωί ή σούρουπο, Μάι–Σεπ."},"src":["pomos_skaros","pomos_cyfish"]},{"gear":"bread","note":{"en":"Dough kneaded with purslane (γλιστρίδα) on the same small hook; strike when the float sinks slightly and stops, not on a dive.","el":"Ζυμάρι με γλιστρίδα στο ίδιο μικρό αγκίστρι· κάρφωσε όταν ο φελλός βουλιάξει λίγο και σταθεί, όχι όταν βουτήξει."},"src":["pomos_skaros"]},{"gear":"crab","note":{"en":"A crab leg with some flesh left on, dropped close to the rocks; it holds up to the parrotfish's beak better than soft baits.","el":"Ποδαράκι καβουριού με λίγη σάρκα, κοντά στα βράχια· αντέχει στο «ράμφος» του σκάρου καλύτερα από τα μαλακά δολώματα."},"src":["pomos_skaros"]}],
    greymullet: [{"gear":"bread","best":true,"note":{"en":"Soft bread or bread-and-cheese dough on a size 10–14 hook under a light float inside the Pomos and Kato Pyrgos shelters; mullet want it soft.","el":"Μαλακό ψωμί ή ζυμάρι ψωμιού με τυρί σε αγκίστρι Νο 10–14 με ελαφρύ φελλό μέσα στα καταφύγια Πωμού και Κάτω Πύργου· ο κέφαλος το θέλει μαλακό."},"src":["pomos_cyapiko"]},{"gear":"sardine","note":{"en":"Soft sardine dough, or thin sardine strips wrapped round the hook, fished close to the bottom on calm, clear days.","el":"Μαλακό ζυμάρι σαρδέλας ή λεπτές λωρίδες σαρδέλας τυλιγμένες στο αγκίστρι, κοντά στον βυθό τις ήρεμες, καθαρές μέρες."},"src":["pomos_cyapiko","pomos_dr_kefalos"]},{"gear":"groundbait","note":{"en":"Μαλάγρα in the same flavour as the hook bait: a few balls to start, then 1–2 when bites slow; also try the Pyrgos river mouth after winter rain.","el":"Μαλάγρα με την ίδια γεύση με το δόλωμα: λίγες μπάλες στην αρχή, μετά 1–2 όταν κόβουν οι τσιμπιές· δοκίμασε και τις εκβολές του ποταμού Πύργου μετά από χειμωνιάτικη βροχή."},"src":["pomos_dr_kefalos"]}],
  },
  polis: {
    tsipoura: [{"gear":"worm","best":true,"note":{"en":"Whole pharaoh (φαραώ) needle-threaded on a no. 2–1/0 hook, cast long off Polis and Argaka beaches over sand–Posidonia, Oct–Jan, midday and dusk. General Cypriot top bait.","el":"Ολόκληρο φαραώ περασμένο με βελόνα σε αγκίστρι Νο 2–1/0, μακριές βολές από τις παραλίες Πόλης και Αργάκας σε άμμο–ποσειδωνία, Οκτ–Ιαν· μεσημέρι και σούρουπο."},"src":["polis_pcy_shore","polis_ypa"]},{"gear":"crab","note":{"en":"Small live crab (καρτσίνα) or hermit crab (σκαρτσίνι) hooked tail to thorax, for big fish off the Latchi outer breakwater; small fish there cannot strip it.","el":"Μικρή ζωντανή καρτσίνα ή σκαρτσίνι περασμένο από την ουρά προς τον θώρακα, για μεγάλες τσιπούρες στον εξωτερικό κυματοθραύστη του Λατσιού· δεν το καθαρίζουν τα μικρά."},"src":["polis_fcy_salpa"]},{"gear":"mussel","note":{"en":"Two or three mussels bound with elastic thread on a no. 2 hook, at night off the Latchi outer breakwater toe; general practice, not a local report.","el":"Δύο–τρία μύδια δεμένα με λαστιχένια κλωστή σε αγκίστρι Νο 2, τη νύχτα στη βάση του εξωτερικού κυματοθραύστη του Λατσιού· γενική πρακτική, όχι τοπική αναφορά."}}],
    sargos: [{"gear":"worm","best":true,"note":{"en":"Pharaoh (φαραώ) piece on a no. 4–2 hook in the surf at Argaka and Polis beaches, Oct–Apr; σορκός are taken there even in midday sessions. Cypriot first choice.","el":"Κομμάτι φαραώ σε αγκίστρι Νο 4–2 στο κύμα στις παραλίες Αργάκας και Πόλης, Οκτ–Απρ· εκεί πιάνονται σορκοί ακόμη και μεσημέρι. Η πρώτη επιλογή των Κυπρίων."},"src":["polis_pcy_shore","polis_argaka"]},{"gear":"sardine","note":{"en":"Firm sardine-and-rusk dough (σαρδέλα με φρυγανιά) under a float off the Latchi outer breakwater, over sardine-scrap groundbait; dawn and dusk.","el":"Σφιχτό ζυμάρι σαρδέλας με φρυγανιά σε φελλό στον εξωτερικό κυματοθραύστη του Λατσιού, πάνω από μάλαγρα από υπολείμματα σαρδέλας· χαράματα και σούρουπο."},"src":["polis_pcy_apiko","polis_dom"]},{"gear":"mussel","note":{"en":"Limpet (πεταλίδα) from the breakwater rocks, shell removed keeping the black eye intact; Cypriot anglers rate it highly for σορκό. Mussel works the same way.","el":"Πεταλίδα από τα βράχια του κυματοθραύστη, βγαλμένη από το όστρακο χωρίς να χαλάσει το μαύρο «μάτι»· οι Κύπριοι τη θεωρούν εκλεκτό δόλωμα για σορκό. Ομοίως και μύδι."},"src":["polis_pcy_shore"]},{"gear":"shrimp","note":{"en":"Live small shrimp (γαριδούλα) scooped with a hand net along the breakwater, under a light float in the foam at dusk.","el":"Ζωντανή γαριδούλα πιασμένη με απόχη κατά μήκος του κυματοθραύστη, σε ελαφρύ φελλό στον αφρό το σούρουπο."},"src":["polis_pcy_shore"]}],
    squid: [{"gear":"sardine","best":true,"note":{"en":"Whole small sardine on a καφτερό under a float with a chemical light, off the Latchi outer breakwater at dusk and first dark, Nov–Mar.","el":"Ολόκληρη μικρή σαρδέλα σε καφτερό κάτω από φελλό με χημικό φωτάκι, στον εξωτερικό κυματοθραύστη του Λατσιού το σούρουπο και με το πρώτο σκοτάδι, Νοέ–Μαρ."},"src":["polis_lws","polis_pcy_squid"]},{"gear":"live_fish","note":{"en":"Live small bogue (γόππα) or horse mackerel (σαυρίδι) on a καφτερό, drifted at dusk over 15–40 m Posidonia off Latchi in winter.","el":"Ζωντανή μικρή γόππα ή σαυρίδι σε καφτερό, σε ντρίφτ το σούρουπο πάνω από ποσειδωνία 15–40 μ. έξω από το Λατσί τον χειμώνα."},"src":["polis_lws"]}],
    melanouri: [{"gear":"bread","best":true,"note":{"en":"Bread flake (ψίχα) on a no. 12–10 hook under a 2–4 g float in a bread groundbait cloud off the Latchi breakwater, Apr–Oct; small bream there take bread.","el":"Ψίχα ψωμιού σε αγκίστρι Νο 12–10 με φελλό 2–4 γρ. μέσα σε σύννεφο μάλαγρας ψωμιού στον κυματοθραύστη του Λατσιού, Απρ–Οκτ· τα μικρά σπαροειδή εκεί τρώνε ψωμί."},"src":["polis_fly","polis_dom"]},{"gear":"sardine","note":{"en":"Soft sardine-and-rusk dough or a thin sardine fillet strip, fished mid-water under the float where the groundbait sinks.","el":"Μαλακό ζυμάρι σαρδέλας με φρυγανιά ή λεπτή λωρίδα φιλέτου σαρδέλας, στα μεσαία νερά κάτω από τον φελλό, εκεί που κατεβαίνει η μάλαγρα."},"src":["polis_pcy_apiko"]},{"gear":"shrimp","note":{"en":"Small peeled shrimp pieces on a no. 12 hook when μελάνες ignore bread; best on bright, calm days.","el":"Μικρά καθαρισμένα κομματάκια γαρίδας σε αγκίστρι Νο 12 όταν οι μελάνες αγνοούν το ψωμί· καλύτερα σε φωτεινές, ήρεμες μέρες."}},{"gear":"groundbait","note":{"en":"Sardine-scrap groundbait (heads, guts, old frying oil, sand) fed little and often down the breakwater keeps μελάνες at float depth.","el":"Μάλαγρα από υπολείμματα σαρδέλας (κεφάλια, εντόσθια, παλιό λάδι, άμμος), λίγη και συχνά στον κυματοθραύστη, κρατά τις μελάνες στο βάθος του φελλού."},"src":["polis_pcy_apiko"]}],
    bluefish: [{"gear":"live_fish","best":true,"note":{"en":"Live sand smelt (αθερίνα) or small garfish (ζαργάνα) on a long-shank hook with short wire, free-lined at the Latchi harbour mouth at dawn and dusk, Oct–Jan.","el":"Ζωντανή αθερίνα ή μικρή ζαργάνα σε αγκίστρι με μακρύ λαιμό και κοντό συρματάκι, ελεύθερη στο στόμιο του λιμανιού του Λατσιού χαράματα και σούρουπο, Οκτ–Ιαν."},"src":["polis_pcy_fish","polis_fbak"]},{"gear":"sardine","note":{"en":"Whole or half sardine on a 2-hook surf rig with wire, cast at night off Polis beach near the river mouth; Cypriot sources say γοφάρια work river mouths.","el":"Ολόκληρη ή μισή σαρδέλα σε σύνθεση surf με δύο αγκίστρια και συρματάκι, τη νύχτα στην παραλία της Πόλης κοντά στις εκβολές του ποταμού· τα γοφάρια ψάχνουν εκβολές."},"src":["polis_pcy_fish","polis_pcy_shore"]},{"gear":"squid_bait","note":{"en":"Squid strip on a long-shank hook: stays on when bluefish chop softer baits; also trolled slowly along the bay.","el":"Λωρίδα καλαμαριού σε αγκίστρι με μακρύ λαιμό: μένει στο αγκίστρι όταν τα γοφάρια κόβουν τα μαλακά δολώματα· και σε αργή συρτή στον κόλπο."},"src":["polis_pcy_fish"]}],
    garfish: [{"gear":"sardine","best":true,"note":{"en":"Thin 3–4 cm sardine strip on a fine no. 8–6 long-shank hook, 30–80 cm under a small float off the Latchi breakwater, calm mornings Dec–Apr. General practice.","el":"Λεπτή λωρίδα σαρδέλας 3–4 εκ. σε λεπτό αγκίστρι Νο 8–6 με μακρύ λαιμό, 30–80 εκ. κάτω από μικρό φελλό στον κυματοθραύστη του Λατσιού, ήρεμα πρωινά Δεκ–Απρ."},"src":["polis_fbak"]},{"gear":"worm","note":{"en":"Thin American or acrobat worm on the same float rig, just under the surface; general, not a local report.","el":"Λεπτό αμερικάνικο σκουλήκι ή ακροβάτης στην ίδια σύνθεση με φελλό, λίγο κάτω από την επιφάνεια· γενική πρακτική, όχι τοπική αναφορά."}},{"gear":"shrimp","note":{"en":"Small shrimp pieces just under the surface over light groundbait; general practice.","el":"Κομματάκια γαρίδας λίγο κάτω από την επιφάνεια πάνω από λίγη μάλαγρα· γενική πρακτική."}}],
    pandora: [{"gear":"shrimp","best":true,"note":{"en":"Whole shrimp, shell on, on no. 4–2 hooks of a 2–3 hook paternoster, drifted at 30–80 m on the sand–rock edges 2–3 km off Latchi, Apr–Aug.","el":"Ολόκληρη γαρίδα με το κέλυφος σε αγκίστρια Νο 4–2, αρματωσιά 2–3 αγκιστριών, ντρίφτ στα 30–80 μ. στις άκρες άμμου–βράχου 2–3 χλμ. έξω από το Λατσί, Απρ–Αύγ."},"src":["polis_fbblog"]},{"gear":"worm","note":{"en":"Pharaoh (φαραώ) pieces cut to hook size, on the shallower 20–30 m sand edges in the bay; Greek boat anglers rate it for λυθρίνι.","el":"Κομμάτια φαραώ στο μέγεθος του αγκιστριού, στις ρηχότερες άκρες άμμου 20–30 μ. στον κόλπο· οι Έλληνες ψαράδες της καθετής το προτιμούν για λυθρίνι."},"src":["polis_crods"]},{"gear":"squid_bait","note":{"en":"Squid strip about 1×5 cm: stays on through the drift and filters out bogue and comber.","el":"Λωρίδα καλαμαριού περίπου 1×5 εκ.: κρατάει σε όλο το ντρίφτ και αποφεύγει γόππες και χάννους."}}],
    porgy: [{"gear":"squid_bait","best":true,"note":{"en":"Squid strip or whole small squid on a 1/0–2/0 hook, drifted on rough ground at 40–100 m, 2–3 km off Latchi, Jan–Apr. General Cyprus practice.","el":"Λωρίδα ή ολόκληρο μικρό καλαμάρι σε αγκίστρι 1/0–2/0, ντρίφτ σε τραχύ βυθό 40–100 μ., 2–3 χλμ. έξω από το Λατσί, Ιαν–Απρ. Γενική πρακτική."}},{"gear":"live_fish","note":{"en":"Live bogue (γόππα) 10–15 cm for the big porgy on rocky ground off Latchi. General Cyprus practice.","el":"Ζωντανή γόππα 10–15 εκ. για τα μεγάλα φαγκριά στα βραχώδη ανοιχτά του Λατσιού. Γενική πρακτική στην Κύπρο."}},{"gear":"sardine","note":{"en":"Fresh sardine or bogue, head and tail cut so it bleeds, on a 2-hook rig.","el":"Φρέσκια σαρδέλα ή γόππα με κομμένο κεφάλι και ουρά για να «ματώνει», σε αρματωσιά με δύο αγκίστρια."}}],
    scorpionfish: [{"gear":"sardine","best":true,"note":{"en":"Sardine or mackerel (κολιός) strip on a 1/0 hook, bounced on rough bottom at 30–80 m off Latchi; all year, best by day in winter. General practice.","el":"Λωρίδα σαρδέλας ή κολιού σε αγκίστρι 1/0, χτυπώντας τον τραχύ βυθό στα 30–80 μ. έξω από το Λατσί· όλο τον χρόνο, καλύτερα μέρα τον χειμώνα. Γενική πρακτική."}},{"gear":"squid_bait","note":{"en":"Squid strip: stays on the hook among rocks and outlasts small-fish pecking.","el":"Λωρίδα καλαμαριού: μένει στο αγκίστρι μέσα στα βράχια και αντέχει στα τσιμπήματα των μικρών."}},{"gear":"shrimp","note":{"en":"Large whole shrimp on the bottom hook of the drift rig.","el":"Μεγάλη ολόκληρη γαρίδα στο κάτω αγκίστρι της αρματωσιάς."}}],
    dentex: [{"gear":"live_fish","best":true,"note":{"en":"Live bogue (γόππα) 12–18 cm or sabiki horse mackerel on a circle hook, drifted just off the bottom on reef edges 40–100 m off Latchi at dawn, Apr–Oct.","el":"Ζωντανή γόππα 12–18 εκ. ή σαυρίδι από τσαπαρί, σε circle αγκίστρι, ντρίφτ λίγο πάνω από τον βυθό σε άκρες ξέρας 40–100 μ. έξω από το Λατσί, χαράματα, Απρ–Οκτ."},"src":["polis_lws","polis_fhlatchi","polis_fbblog"]},{"gear":"squid_bait","note":{"en":"Live squid caught at dusk (Oct–Dec), sliding hook in the tail, fixed one in the siphon; the premium bait when squid are in. Fresh squid otherwise.","el":"Ζωντανό καλαμάρι πιασμένο το σούρουπο (Οκτ–Δεκ), συρόμενο αγκίστρι στην ουρά, σταθερό στο σιφόνι· το καλύτερο όταν έχει καλαμάρια. Αλλιώς νωπό καλαμάρι."},"src":["polis_lws"]}],
    littletunny: [{"gear":"live_fish","best":true,"note":{"en":"Live sand smelt (αθερίνα) or small horse mackerel free-lined into feeding schools in Chrysochou Bay, Aug–Nov, early morning before the westerly.","el":"Ζωντανή αθερίνα ή μικρό σαυρίδι ελεύθερο μέσα στα κοπάδια που τρώνε στον κόλπο της Χρυσοχούς, Αύγ–Νοέ, νωρίς το πρωί πριν τον δυτικό."},"src":["polis_fbak"]},{"gear":"sardine","note":{"en":"Sardine chunks as chum, with a half sardine on a 1/0 hook drifted back in the slick when a school holds near the boat. General practice.","el":"Κομμάτια σαρδέλας ως μάλαγρα, με μισή σαρδέλα σε αγκίστρι 1/0 που αφήνεται να πάει με τη μάλαγρα όταν το κοπάδι μένει κοντά στο σκάφος. Γενική πρακτική."}}],
    dolphinfish: [{"gear":"live_fish","best":true,"note":{"en":"Small live fish (horse mackerel, bogue) free-lined beside floating debris or buoys past the 100 m line, 3 km+ off Latchi, Sep–Nov.","el":"Μικρό ζωντανό ψάρι (σαυρίδι, γόππα) ελεύθερο δίπλα σε επιπλέοντα αντικείμενα ή σημαδούρες πέρα από τα 100 μ., 3+ χλμ. έξω από το Λατσί, Σεπ–Νοέ."},"src":["polis_fbblog","polis_fbak"]},{"gear":"sardine","note":{"en":"Cut sardine thrown to hold a school at the boat, with a baited 1/0 hook drifted among them while others cast lures.","el":"Κομμένη σαρδέλα που ρίχνεται για να κρατήσει το κοπάδι στο σκάφος, με δολωμένο αγκίστρι 1/0 ανάμεσά τους ενώ οι άλλοι ρίχνουν τεχνητά."}},{"gear":"squid_bait","note":{"en":"Squid strip on a free line; tougher than sardine when the school is competing.","el":"Λωρίδα καλαμαριού σε ελεύθερη πετονιά· πιο ανθεκτική από τη σαρδέλα όταν το κοπάδι ανταγωνίζεται."}}],
    octopus: [{"gear":"crab","best":true,"note":{"en":"Small crab (καρτσίνα) bound on a white octopus jig, dragged slowly along the Latchi outer breakwater toe and rock–sand edges, Oct–May. General practice.","el":"Μικρή καρτσίνα δεμένη σε άσπρη χταποδιέρα, σέρνοντας αργά στη βάση του εξωτερικού κυματοθραύστη του Λατσιού και στις άκρες βράχου–άμμου, Οκτ–Μάι."}},{"gear":"sardine","note":{"en":"Fresh sardine or bogue tied to the jig; chicken leg is the traditional alternative.","el":"Νωπή σαρδέλα ή γόππα δεμένη στη χταποδιέρα· το κοτοπόδαρο είναι η παραδοσιακή εναλλακτική."}}],
    grouper: [{"gear":"live_fish","best":true,"note":{"en":"Live bogue (γόππα) 12–18 cm lip-hooked, lowered into rocky holes at 20–60 m on the Akamas side, outside the Chalavro and Kakoskali MPAs, Jun–Oct.","el":"Ζωντανή γόππα 12–18 εκ. από τα χείλη, μέσα σε βραχώδεις τρύπες στα 20–60 μ. προς τον Ακάμα, έξω από τις ΘΠΠ Χαλαύρου και Κακοσκάλι, Ιούν–Οκτ."},"src":["polis_fbak"]},{"gear":"squid_bait","note":{"en":"Small whole octopus or cuttlefish, or a big squid, on a 2-hook rig: the classic ορφός bait.","el":"Μικρό ολόκληρο χταπόδι ή σουπιά, ή μεγάλο καλαμάρι, σε αρματωσιά με δύο αγκίστρια: το κλασικό δόλωμα για ορφό."}},{"gear":"sardine","note":{"en":"Whole dead sardine works, but morays and toadfish usually find it first.","el":"Ολόκληρη νεκρή σαρδέλα πιάνει, αλλά συνήθως τη βρίσκουν πρώτα οι σμέρνες και οι λαγοκέφαλοι."}}],
    parrotfish: [{"gear":"shrimp","best":true,"note":{"en":"Small shrimp piece on a no. 10–8 hook close to weedy rocks at the Latchi breakwater, Jun–Oct mornings. General practice, not a local report.","el":"Κομματάκι γαρίδας σε αγκίστρι Νο 10–8 κοντά σε βράχια με φύκια στον κυματοθραύστη του Λατσιού, πρωινά Ιούν–Οκτ. Γενική πρακτική, όχι τοπική αναφορά."}},{"gear":"bread","note":{"en":"Bread-and-cheese dough on a small hook, fished just off the weed line.","el":"Ζυμάρι ψωμιού με τυρί σε μικρό αγκίστρι, δίπλα στα φύκια."}},{"gear":"algae","note":{"en":"Fine green weed scraped from the breakwater, wrapped on a small hook: σκάροι graze it there.","el":"Λεπτό πράσινο φύκι από τον κυματοθραύστη, τυλιγμένο σε μικρό αγκίστρι: οι σκάροι βόσκουν εκεί."}}],
    greymullet: [{"gear":"bread","best":true,"note":{"en":"Bread flake or crust on a no. 14–12 hook under a light float off the Latchi sea wall, over bread groundbait; reported by visiting anglers at Latchi.","el":"Ψίχα ή κόρα ψωμιού σε αγκίστρι Νο 14–12 με ελαφρύ φελλό στον τοίχο του Λατσιού, πάνω από μάλαγρα ψωμιού· αναφέρεται από ψαράδες που ψάρεψαν στο Λατσί."},"src":["polis_fly","polis_barsch"]},{"gear":"sardine","note":{"en":"Soft sardine-and-rusk paste (σαρδέλα, φρυγανιά, a little oil) moulded on a no. 14 hook; keep it softer for κέφαλο than for σορκό.","el":"Μαλακό ζυμάρι από σαρδέλα, φρυγανιά και λίγο λάδι σε αγκίστρι Νο 14· πιο μαλακό για κέφαλο απ’ ό,τι για σορκό."},"src":["polis_fly","polis_pcy_apiko"]},{"gear":"groundbait","note":{"en":"Soaked bread mashed with a little sardine, fed little and often; also draws κέφαλοι at the Polis river mouth after rain.","el":"Μουσκεμένο ψωμί ανακατεμένο με λίγη σαρδέλα, λίγο και συχνά· τραβά κεφάλους και στις εκβολές του ποταμού της Πόλης μετά από βροχή."},"src":["polis_barsch","polis_pcy_fish"]}],
    cuttlefish: [{"gear":"sardine","best":true,"note":{"en":"Small dead fish (sardine, bogue) bound to a cuttlefish jig, dragged slowly over Posidonia–sand at 2–10 m off Polis and Argaka, Feb–May. General practice.","el":"Μικρό νεκρό ψάρι (σαρδέλα, γόππα) δεμένο σε σουπιέρα, σέρνοντας αργά πάνω από ποσειδωνία–άμμο στα 2–10 μ. έξω από Πόλη και Αργάκα, Φεβ–Μάι. Γενική πρακτική."}},{"gear":"live_fish","note":{"en":"Live sand smelt (αθερίνα) or small bogue on a καφτερό under a float at dusk from the Latchi breakwater, Feb–May.","el":"Ζωντανή αθερίνα ή μικρή γόππα σε καφτερό κάτω από φελλό το σούρουπο από τον κυματοθραύστη του Λατσιού, Φεβ–Μάι."}}],
  },
  akamas: {
    leerfish: [{"gear":"live_fish","best":true,"note":{"en":"Live garfish (ζαργάνα) 20–30 cm or small mullet, nose-hooked under a small float a few metres down, off deep rocky points or Lara beach; first light, Aug–Dec.","el":"Ζωντανή ζαργάνα 20–30 εκ. ή μικρός κέφαλος, από τη μύτη, με μικρό φελλό λίγα μέτρα κάτω, σε βαθιά ακρωτήρια ή στη Λάρα· με το πρώτο φως, Αύγ–Δεκ."},"src":["akamas_hellas_leer","akamas_kzteam","akamas_safari"]},{"gear":"sardine","note":{"en":"Fallback without live bait: whole fresh sardine or a garfish fillet on a float, drifted at dusk along Lara–Toxeftra sand. Takes small leerfish, rarely big ones.","el":"Αν δεν έχεις ζωντανό: ολόκληρη φρέσκια σαρδέλα ή φιλέτο ζαργάνας με φελλό, στο σούρουπο κατά μήκος της άμμου Λάρας–Τοξεύτρας. Πιάνει μικρές λίτσες, σπάνια μεγάλες."}}],
    bluefish: [{"gear":"sardine","best":true,"note":{"en":"Whole or half fresh sardine on a 2-hook rig with a short wire, cast off the rocks or Lara beach at dusk and into the night, Oct–Jan. General Cyprus practice.","el":"Ολόκληρη ή μισή φρέσκια σαρδέλα σε αρματωσιά με 2 αγκίστρια και κοντό συρματάκι, από τα βράχια ή την παραλία της Λάρας το σούρουπο και τη νύχτα, Οκτ–Ιαν. Γενική πρακτική."}},{"gear":"live_fish","note":{"en":"Live garfish or small horse mackerel on a float with a wire trace at first light off the points, where Akamas charters find bluefish on lures at dawn.","el":"Ζωντανή ζαργάνα ή μικρό σαφρίδι με φελλό και συρματάκι με το πρώτο φως στα ακρωτήρια, εκεί που τα σκάφη του Ακάμα βρίσκουν γοφάρια με τεχνητά τα χαράματα."},"src":["akamas_safari"]},{"gear":"squid_bait","note":{"en":"Squid strip on a long-shank hook: survives the teeth better than sardine, so one bait lasts several bites. General, not local.","el":"Λωρίδα καλαμαριού σε αγκίστρι με μακρύ λαιμό: αντέχει στα δόντια καλύτερα από τη σαρδέλα, οπότε ένα δόλωμα βγάζει πολλές τσιμπιές. Γενικό, όχι τοπικό."}}],
    barracuda: [{"gear":"live_fish","best":true,"note":{"en":"Live or very fresh garfish (ζαργάνα), whole or as a long fillet, on wire under a float; sunset to dark and before dawn, best Sep–Oct. Garfish run along these rocks.","el":"Ζωντανή ή ολόφρεσκη ζαργάνα, ολόκληρη ή μακρύ φιλέτο, σε σύρμα με φελλό· από τη δύση ως το σκοτάδι και πριν τα χαράματα, καλύτερα Σεπ–Οκτ. Ζαργάνες κυκλοφορούν σε αυτά τα βράχια."},"src":["akamas_drosos_lou","akamas_safari"]},{"gear":"sardine","note":{"en":"Half fresh sardine or a bogue strip on wire, drifted near the rock edges at dusk; Agios Georgios charter clients take barracuda while bottom-fishing with bait.","el":"Μισή φρέσκια σαρδέλα ή λωρίδα γόππας σε σύρμα, στις άκρες των βράχων το σούρουπο· στον Άγιο Γεώργιο οι πελάτες των σκαφών πιάνουν λούτσους σε ψάρεμα βυθού με δόλωμα."},"src":["akamas_kzteam"]},{"gear":"squid_bait","note":{"en":"Long squid strip on a wire trace at night: stays on through repeated bites when garfish is scarce. General, not local.","el":"Μακριά λωρίδα καλαμαριού σε σύρμα τη νύχτα: μένει στο αγκίστρι μετά από πολλές τσιμπιές όταν δεν βρίσκεις ζαργάνα. Γενικό, όχι τοπικό."}}],
    amberjack: [{"gear":"live_fish","best":true,"note":{"en":"Live bogue (γόππα) or horse mackerel caught on a sabiki on the spot, slow-trolled on a lead or dropped at the 40–70 m drop-off; small live fish are the summer bait.","el":"Ζωντανή γόππα ή σαφρίδι από τσαπαρί επιτόπου, σε αργή συρτή με φύλακα ή κατεβασμένο στην κατωφέρεια των 40–70 μ.· το μικρό ζωντανό ψάρι είναι το δόλωμα του καλοκαιριού."},"src":["akamas_drosos_amb","akamas_kzteam","akamas_safari"]},{"gear":"squid_bait","note":{"en":"Live squid in Oct–Nov, hooked through the tail on a 6/0–8/0 two-hook rig, trolled under 1 knot along the reef edge; a live cuttlefish works the same in spring.","el":"Ζωντανό καλαμάρι Οκτ–Νοέ, από την ουρά σε αρματωσιά 2 αγκιστριών 6/0–8/0, συρτή κάτω από 1 κόμβο στην άκρη της ξέρας· την άνοιξη το ίδιο με ζωντανή σουπιά."},"src":["akamas_drosos_amb"]}],
    sargos: [{"gear":"worm","best":true,"note":{"en":"Pharaoh worm (φαραώ), a piece that just covers the hook, in the foam from dusk into night with an onshore wind. Buy it in Paphos or Polis: no shops on Akamas.","el":"Φαραώ, κομμάτι που μόλις σκεπάζει το αγκίστρι, στον αφρό από το σούρουπο ως τη νύχτα με αέρα προς την ακτή. Πάρ' το από Πάφο ή Πόλη: στον Ακάμα δεν έχει μαγαζιά."},"src":["akamas_bf_sargos","akamas_cyblog_shore","akamas_cyblog_live"]},{"gear":"crab","note":{"en":"Small rock crabs (καρτσίνες) picked on the spot at night, whole on a size 4–2 hook, for the big σορκοί in rough water off the low rocks.","el":"Μικρές καρτσίνες που μαζεύεις επιτόπου τη νύχτα, ολόκληρες σε αγκίστρι Νο 4–2, για τους μεγάλους σορκούς στη φουρτούνα στα χαμηλά βράχια."},"src":["akamas_cyblog_shore"]},{"gear":"shrimp","note":{"en":"Live small shrimp (γαριδούλα) or a fresh shrimp tail under a float in the wash; works in daylight only when the sea is up and the water is cloudy.","el":"Ζωντανή γαριδούλα ή ουρά φρέσκιας γαρίδας με φελλό στο κύμα· τη μέρα δουλεύει μόνο όταν έχει κύμα και θολούρα."},"src":["akamas_bf_sargos","akamas_cyblog_shore"]},{"gear":"sardine","note":{"en":"Fresh sardine fillet firmed with breadcrumbs (φρυγανιά) and a little oil, over sardine groundbait thrown behind the float: the Cypriot apiko recipe.","el":"Φρέσκο φιλέτο σαρδέλας σφιγμένο με φρυγανιά και λίγο λάδι, πάνω από μαλάγρα σαρδέλας πίσω από τον φελλό: η κυπριακή συνταγή για απίκο."},"src":["akamas_cyblog_apiko"]}],
    octopus: [{"gear":"crab","best":true,"note":{"en":"A real small crab lashed onto a white octopus jig, dragged slowly over rock and Posidonia edges in calm, clear water; mornings, mid-autumn to the winter peak.","el":"Μικρό αληθινό καβουράκι δεμένο σε άσπρη χταποδιέρα, σε αργό σύρσιμο στις άκρες βράχου και ποσειδωνίας με ήρεμη, καθαρή θάλασσα· πρωί, από μέσα φθινοπώρου ως τον χειμώνα."},"src":["akamas_drosos_octo"]},{"gear":"sardine","note":{"en":"A fresh small fish (sardine or bogue) tied to the jig's wire: the white or silver flash carries far in the clear Akamas water.","el":"Φρέσκο ψαράκι (σαρδέλα ή γόππα) δεμένο στο σύρμα της χταποδιέρας: η άσπρη ή ασημένια λάμψη φαίνεται από μακριά στα καθαρά νερά του Ακάμα."},"src":["akamas_drosos_octo"]}],
    dentex: [{"gear":"live_fish","best":true,"note":{"en":"Live bogue, wrasse or red mullet caught on site, one circle hook, on the 30–60 m reef edges or from steep deep rocks in rough sea. Let it take; don't strike.","el":"Ζωντανή γόππα, γύλος ή μπαρμπούνι από επιτόπου, ένα circle αγκίστρι, στις άκρες ξέρας 30–60 μ. ή από απότομα βαθιά βράχια με κύμα. Άφησέ τη να το πάρει, μην καρφώνεις."},"src":["akamas_hellas_dentex","akamas_safari"]},{"gear":"squid_bait","note":{"en":"Live squid 30–40 cm in late autumn–winter: sliding hook in the tail, fixed one at the tentacle base, 0.5–1.5 knots. Fresh squid with a belly weight if none.","el":"Ζωντανό καλαμάρι 30–40 εκ. αργά το φθινόπωρο–χειμώνα: συρόμενο αγκίστρι στην ουρά, σταθερό στη βάση των πλοκαμιών, 0,5–1,5 κόμβοι. Αλλιώς νωπό με βαρίδι στην κοιλιά."},"src":["akamas_bf_dentex"]}],
    grouper: [{"gear":"squid_bait","best":true,"note":{"en":"Live small octopus (χταποδάκι), the top live grouper bait from a boat; a whole squid also takes big fish (7 kg for a forum angler fishing in Cyprus).","el":"Ζωντανό χταποδάκι, το καλύτερο ζωντανό δόλωμα για ορφό από σκάφος· και ολόκληρο καλαμάρι πιάνει μεγάλα (7 κιλά για ψαρά φόρουμ που ψαρεύει στην Κύπρο)."},"src":["akamas_psarema_rofos"]},{"gear":"live_fish","note":{"en":"Live bogue, picarel or small comber caught on site, lowered tight to the ledges at 15–40 m at dusk, Jun–Oct; lift it at once so the fish can't reach its hole.","el":"Ζωντανή γόππα, μαρίδα ή μικρός χάννος από επιτόπου, κολλητά στις σπηλιές στα 15–40 μ. το σούρουπο, Ιουν–Οκτ· σήκωσέ τον αμέσως να μη φτάσει στην τρύπα του."},"src":[]},{"gear":"sardine","note":{"en":"Whole fresh small fish at dusk off deep rocks: gave the same Cyprus angler three 3 kg groupers in one night, but morays and conger take most such baits.","el":"Ολόκληρο φρέσκο ψαράκι το σούρουπο από βαθιά βράχια: έδωσε στον ίδιο ψαρά στην Κύπρο τρεις ορφούς των 3 κιλών σε μια νύχτα, αλλά τα περισσότερα τα παίρνουν σμέρνες και μουγγριά."},"src":["akamas_psarema_rofos"]}],
    porgy: [{"gear":"squid_bait","best":true,"note":{"en":"Squid strip or a small whole squid on a 2-hook rig on the 50–120 m reef edges, Jan–Apr; tough and selective against small fish. General, not local.","el":"Λωρίδα ή μικρό ολόκληρο καλαμάρι σε αρματωσιά 2 αγκιστριών στις άκρες ξέρας 50–120 μ., Ιαν–Απρ· ανθεκτικό και κόβει τα μικρά. Γενικό, όχι τοπικό."}},{"gear":"shrimp","note":{"en":"Whole large shrimp on the bottom over coarse ground near the reef; small fish strip it fast, so check often. General, not local.","el":"Ολόκληρη μεγάλη γαρίδα στον βυθό σε χοντρό βυθό δίπλα στην ξέρα· τα μικρά την καθαρίζουν γρήγορα, έλεγχε συχνά. Γενικό, όχι τοπικό."}},{"gear":"sardine","note":{"en":"Fresh sardine or bogue chunk, head and tail cut so it bleeds scent; general, not local.","el":"Κομμάτι φρέσκιας σαρδέλας ή γόππας, κομμένο κεφάλι και ουρά να «ματώνει»· γενικό, όχι τοπικό."}},{"gear":"worm","note":{"en":"Μάνα worm, whole on a big hook: a Cypriot angling blog lists it for φαγκριά; best where porgy move shallower in late winter.","el":"Μάνα, ολόκληρη σε μεγάλο αγκίστρι: κυπριακό ψαράδικο blog τη δίνει για φαγκριά· καλύτερα όπου τα φαγκριά ρηχαίνουν στο τέλος του χειμώνα."},"src":["akamas_cyblog_live"]}],
    pandora: [{"gear":"shrimp","best":true,"note":{"en":"Whole shrimp, unpeeled, threaded on two hooks 2 cm apart, worked on the sand-gravel edges below the reefs, Apr–Aug; strike even at small bites.","el":"Ολόκληρη γαρίδα, ακαθάριστη, σε δύο αγκίστρια με 2 εκ. απόσταση, στις άκρες άμμου–χαλικιού κάτω από τις ξέρες, Απρ–Αύγ· κάρφωνε και στις μικρές τσιμπιές."},"src":["akamas_bf_lyth","akamas_fbblog"]},{"gear":"squid_bait","note":{"en":"Squid tentacle, neat on the hook with no loose ends; stays on and filters out small fish.","el":"Πλοκάμι καλαμαριού, καθαρά περασμένο χωρίς κρεμασμένα κομμάτια· κρατάει και φιλτράρει τα μικρά."},"src":["akamas_bf_lyth"]},{"gear":"worm","note":{"en":"Μάνα worm, whole or cut into rings: a Cypriot angling blog's pick for λυθρίνια; better in the shallower 15–40 m.","el":"Μάνα, ολόκληρη ή κομμένη σε ροδέλες: κυπριακό ψαράδικο blog τη δίνει για λυθρίνια· καλύτερα στα ρηχότερα 15–40 μ."},"src":["akamas_cyblog_live"]},{"gear":"sardine","note":{"en":"Small sardine fillet pieces when the shrimp runs out; general, not local.","el":"Μικρά κομμάτια φιλέτου σαρδέλας όταν τελειώσει η γαρίδα· γενικό, όχι τοπικό."}}],
    littletunny: [{"gear":"live_fish","best":true,"note":{"en":"Live small horse mackerel, sardine or bogue from a sabiki, free-lined into a feeding school off the points at dawn or dusk, Aug–Nov.","el":"Ζωντανό μικρό σαφρίδι, σαρδέλα ή γόππα από τσαπαρί, ελεύθερο μέσα στο κοπάδι που τρώει έξω από τα ακρωτήρια, χαράματα ή σούρουπο, Αύγ–Νοέ."},"src":["akamas_bf_tuna"]},{"gear":"sardine","note":{"en":"Fresh sardine chunks drifted back over a sardine chum line from a drifting boat when the school sits deeper; general, not local.","el":"Κομμάτια φρέσκιας σαρδέλας που κατεβαίνουν σε γραμμή μαλάγρας σαρδέλας από σκάφος σε ντρίφτα, όταν το κοπάδι είναι πιο βαθιά· γενικό, όχι τοπικό."}}],
  },
  paphos: {
    sargos: [{"gear":"worm","best":true,"note":{"en":"Worm (φαραώ or ακροβάτης) on hook 6–8 under a 3 g float, a few cm off bottom, on the rock platforms N of the harbour, Oct–Apr; best in murky water or foam.","el":"Σκουλήκι (φαραώ ή ακροβάτης) σε αγκίστρι 6–8 με φελλό 3 γρ., λίγα εκ. πάνω από τον βυθό, στις πλάκες βόρεια του λιμανιού, Οκτ–Απρ· καλύτερα με θολούρα ή αφρουδιά."},"src":["paphos_cfm_sorkoi","paphos_cfm_antena"]},{"gear":"shrimp","note":{"en":"Live γαριδούλα or a peeled shrimp tail on the same light float rig: the other standard winter σορκός bait in Cyprus, good along the Kato Paphos breakwaters.","el":"Ζωντανή γαριδούλα ή καθαρισμένη ουρά γαρίδας στην ίδια ελαφριά σύνθεση με φελλό: το άλλο κλασικό χειμωνιάτικο δόλωμα για σορκό, καλό στους κυματοθραύστες της Κάτω Πάφου."},"src":["paphos_cfm_sorkoi","paphos_cfm_antena_light"]},{"gear":"squid_bait","note":{"en":"Fresh squid strip 1–1.5 cm wide, 1.5× hook length, on a No 2 long-shank hook: survives long casts and pickers. Best Jan–Mar, when squid come inshore.","el":"Λωρίδα φρέσκου καλαμαριού 1–1,5 εκ., 1,5 φορά το μήκος του αγκιστριού, σε μακρύλαιμο Νο 2: αντέχει στη βολή και στα μικρόψαρα. Καλύτερα Ιαν–Μαρ, που τα καλαμάρια βγαίνουν ρηχά."},"src":["paphos_cfm_squidbait"]},{"gear":"groundbait","note":{"en":"Groundbait of wet sand, soaked bread and fish or cheese, thrown at the rock edge; Cypriot rock anglers say sand is a must for σαργοί, the one fish biting in rough foam.","el":"Μάλαγρα με βρεγμένη άμμο, μουσκεμένο ψωμί και ψαροδόλι ή τυρί στην άκρη του βράχου· οι Κύπριοι ψαράδες λένε ότι η άμμος είναι απαραίτητη για τον σαργό, που τσιμπά και στη φουρτούνα."},"src":["paphos_cfm_antena"]}],
    tsipoura: [{"gear":"worm","best":true,"note":{"en":"Whole μονοδόλι or American worm on a needle, long-cast on a sliding rig with a 1–2 m leader over quiet open sand (Geroskipou, Coral Bay), Nov–Mar.","el":"Ολόκληρο μονοδόλι ή αμερικάνος με βελόνα, μακρινή βολή σε συρόμενη αρματωσιά με παράμαλλο 1–2 μ. σε ήσυχες ανοιχτές αμμουδιές (Γεροσκήπου, Κοράλ Μπέι), Νοέ–Μαρ."},"src":["paphos_cfm_tsip_winter","paphos_cfm_tsip_match"]},{"gear":"crab","note":{"en":"Small live crab (κατσινάρη) or a crab claw for the big fish: gilthead feed on crabs and shells, and small fish can’t strip it. Crabs are easy to collect from March.","el":"Ζωντανή κατσινάρη ή δαγκάνα καβουριού για τις μεγάλες: η τσιπούρα τρέφεται με καβούρια και όστρακα και τα μικρόψαρα δεν το κλέβουν. Από τον Μάρτιο μαζεύονται εύκολα."},"src":["paphos_cfm_tsip_autumn","paphos_cfm_tsip_match","paphos_cfm_season"]},{"gear":"mussel","note":{"en":"Mussels taken off the harbour or breakwater walls, opened and hooked whole or tied with elastic thread; crush a few more as groundbait along your line.","el":"Μύδια από τους τοίχους του λιμανιού ή των κυματοθραυστών, ανοιγμένα και δολωμένα ολόκληρα ή δεμένα με λαστιχένια κλωστή· σπάσε μερικά ακόμα για μάλαγρα κατά μήκος της πετονιάς."},"src":["paphos_cfm_tsip_autumn","paphos_cfm_tsip_match"]}],
    seabass: [{"gear":"live_fish","best":true,"note":{"en":"Small live fish caught on the spot (young mullet or γόππα 8–12 cm) hooked behind the dorsal, at breakwaters and rock points at dawn or dusk; Nov–Apr, esp. March.","el":"Μικρό ζωντανό ψαράκι από το ίδιο σημείο (κεφαλόπουλο ή γόππα 8–12 εκ.) πίσω από το ραχιαίο, σε κυματοθραύστες και ακρωτήρια χαράματα ή σούρουπο· Νοέ–Απρ, ιδίως Μάρτιο."},"src":["paphos_cfm_season"]},{"gear":"shrimp","note":{"en":"Live shrimp, or live sea lice (φτείρα) from washed-up seaweed, under a float at night by the harbour and breakwaters; both are known bass baits in Cyprus.","el":"Ζωντανή γαρίδα ή ζωντανή φτείρα από τα ξεβρασμένα φύκια, με φελλό τη νύχτα στο λιμάνι και στους κυματοθραύστες· και τα δύο πιάνουν λαβράκι στην Κύπρο."},"src":["paphos_decathlon","paphos_cfm_fteira","paphos_cfm_season"]},{"gear":"sardine","note":{"en":"Fresh sardine fillet on a float or light ledger at night near harbour lights, in murky water after winter storms. General Cyprus practice, no local source.","el":"Φρέσκο φιλέτο σαρδέλας με φελλό ή ελαφρύ πεταχτάρι τη νύχτα κοντά στα φώτα του λιμανιού, σε θολά νερά μετά από φουρτούνα. Γενική πρακτική, όχι τοπική πηγή."}}],
    squid: [{"gear":"sardine","best":true,"note":{"en":"Whole sardine on a squid needle (καφτερό) with a chemical light under a float, dusk to midnight Nov–Mar, off the breakwaters over Posidonia. General practice.","el":"Ολόκληρη σαρδέλα σε καφτερό με χημικό φωτάκι κάτω από φελλό, σούρουπο ως μεσάνυχτα Νοέ–Μαρ, από τους κυματοθραύστες πάνω από ποσειδωνία. Γενική πρακτική."},"src":["paphos_cfm_squid_boat"]},{"gear":"live_fish","note":{"en":"Small live fish (γόππα or αθερίνα) on a squid needle under a float near harbour lights; squid hit moving bait. From boats, Paphos trips run night squid Aug–Oct.","el":"Μικρό ζωντανό ψαράκι (γόππα ή αθερίνα) σε καφτερό με φελλό κοντά στα φώτα του λιμανιού· το καλαμάρι χτυπά δόλωμα που κινείται. Από σκάφος, βραδινές εξόδους για καλαμάρι Αύγ–Οκτ."},"src":["paphos_kz"]}],
    leerfish: [{"gear":"live_fish","best":true,"note":{"en":"Live mullet (κέφαλος) or garfish (ζαργάνα) 15–25 cm, free-lined or under a big float off the rock points N of Paphos at dawn/dusk; leerfish show up from April.","el":"Ζωντανός κέφαλος ή ζαργάνα 15–25 εκ., ελεύθερα ή με μεγάλο φελλό στα ακρωτήρια βόρεια της Πάφου χαράματα/σούρουπο· οι λίτσες εμφανίζονται από τον Απρίλιο."},"src":["paphos_cfm_season","paphos_kz"]},{"gear":"squid_bait","note":{"en":"Fresh squid strip ~2 cm wide with the end slit into a tail, single hook, fixed lead: flutters in the current like a fish. Cypriot predator bait when no live bait.","el":"Λωρίδα φρέσκου καλαμαριού ~2 εκ. με σχισμένη άκρη σαν ουρά, μονάγκιστρο, σταθερό βαρίδι: κουνιέται στο ρεύμα σαν ψαράκι. Κυπριακό δόλωμα για κυνηγόψαρα όταν λείπει ζωντανό."},"src":["paphos_cfm_squidbait"]}],
    barracuda: [{"gear":"live_fish","best":true,"note":{"en":"Live αθερίνα or small γόππα 8–12 cm under a float at dusk and night near harbour lights; σφύρνες chase sand smelt from February. Wire or 0.40 fluoro leader.","el":"Ζωντανή αθερίνα ή μικρή γόππα 8–12 εκ. με φελλό σούρουπο και νύχτα κοντά στα φώτα του λιμανιού· οι σφύρνες κυνηγούν αθερίνες από τον Φεβρουάριο. Συρματάκι ή fluoro 0,40."},"src":["paphos_cfm_season","paphos_kz"]},{"gear":"squid_bait","note":{"en":"Slit-tail squid strip, cast and slowly retrieved, or slow-trolled at first light along the reef edge, as Cypriot boats do for σφύρνα before dawn.","el":"Λωρίδα καλαμαριού με σχισμένη ουρά, με βολή και αργό μάζεμα ή σε αργή συρτή με το πρώτο φως στην άκρη της ξέρας, όπως ψαρεύουν οι Κύπριοι τη σφύρνα πριν χαράξει."},"src":["paphos_cfm_squidbait","paphos_cfm_kynigoi"]},{"gear":"sardine","note":{"en":"Half a fresh sardine under a float near the lights at night. General Cyprus practice, no local source.","el":"Μισή φρέσκια σαρδέλα με φελλό κοντά στα φώτα τη νύχτα. Γενική πρακτική, όχι τοπική πηγή."}}],
    melanouri: [{"gear":"bread","best":true,"note":{"en":"Bread flake (ψίχα) or bread-and-cheese dough on a small hook under a light float in the foam, inside a bread groundbait cloud; rocks and breakwaters, Apr–Oct.","el":"Ψίχα ή ζυμάρι ψωμιού με τυρί σε μικρό αγκίστρι με ελαφρύ φελλό στην αφρουδιά, μέσα στο σύννεφο της μάλαγρας· βράχια και κυματοθραύστες, Απρ–Οκτ."},"src":["paphos_cfm_antena","paphos_cfm_season"]},{"gear":"groundbait","note":{"en":"Soaked crumbled bread with cheese, little or no sand in the shallows, thrown little and often: Cypriot rock anglers never leave out wet bread for μελάνες.","el":"Μουσκεμένο τριμμένο ψωμί με τυρί, λίγη ή καθόλου άμμο στα ρηχά, λίγο και συχνά: οι Κύπριοι ψαράδες του βράχου δεν παραλείπουν ποτέ το βρεγμένο ψωμί για τις μελάνες."},"src":["paphos_cfm_antena"]},{"gear":"shrimp","note":{"en":"Live γαριδούλα or small peeled shrimp when bread draws only small fish; lift gently on the take, as μελάνες run hard and snap a fine leader.","el":"Ζωντανή γαριδούλα ή κομματάκια καθαρισμένης γαρίδας όταν στο ψωμί έρχονται μόνο μικρά· σήκωσε απαλά στο τσίμπημα, η μελάνα τραβά δυνατά και κόβει λεπτό παράμαλλο."},"src":["paphos_cfm_antena_light","paphos_cfm_mystika"]}],
    amberjack: [{"gear":"live_fish","best":true,"note":{"en":"Live γόππα 15–20 cm, or in autumn a small barracuda (λουτσάκι) or bonito, on rocky reef edges 20–60 m off Agios Georgios and Coral Bay at dawn.","el":"Ζωντανή γόππα 15–20 εκ., ή το φθινόπωρο λουτσάκι ή παλαμιδάκι, στις άκρες των βραχωδών ξερών 20–60 μ. έξω από Άγιο Γεώργιο και Κοράλ Μπέι, χαράματα."},"src":["paphos_fbblog","paphos_cfm_autumn","paphos_kz"]},{"gear":"squid_bait","note":{"en":"Live squid in autumn–winter (jig it at dusk), slow-trolled on a downrigger lead (φύλακας) 30–40 m back near the reef: a top Cypriot autumn bait for big μινέρια.","el":"Ζωντανό καλαμάρι φθινόπωρο–χειμώνα (πιάσ’ το το σούρουπο), σε αργή συρτή με φύλακα 30–40 μ. πίσω κοντά στην ξέρα: κορυφαίο φθινοπωρινό δόλωμα στην Κύπρο για μεγάλα μινέρια."},"src":["paphos_cfm_autumn","paphos_cfm_synagrida"]}],
    pandora: [{"gear":"shrimp","best":true,"note":{"en":"Fresh whole shrimp, or live green prawn (καραβιδάκι), on a 2–3 hook drop rig over sand–rock edges 20–80 m off Paphos; spring to autumn.","el":"Φρέσκια ολόκληρη γαρίδα ή ζωντανό πράσινο καραβιδάκι, σε καθετή με 2–3 αγκίστρια στο όριο άμμου–βράχου 20–80 μ. έξω από την Πάφο· άνοιξη ως φθινόπωρο."},"src":["paphos_cfm_lythrinia","paphos_fbblog"]},{"gear":"squid_bait","note":{"en":"Fresh squid strip: switch to it after 2–3 drops on shrimp, or when bites stop with the school still on the sounder; λυθρίνια turn wary of one bait.","el":"Λωρίδα φρέσκου καλαμαριού: άλλαξε σε αυτό μετά από 2–3 κατεβάσματα με γαρίδα ή όταν κόψουν τα τσιμπήματα ενώ το κοπάδι φαίνεται στο βυθόμετρο· τα λυθρίνια πονηρεύονται."},"src":["paphos_cfm_lythrinia"]},{"gear":"worm","note":{"en":"Live red acrobat worm (ακροβάτης), only very fresh: the third bait to rotate with shrimp and squid.","el":"Ζωντανός κόκκινος ακροβάτης, μόνο ολόφρεσκος: το τρίτο δόλωμα στην εναλλαγή με γαρίδα και καλαμάρι."},"src":["paphos_cfm_lythrinia"]}],
    grouper: [{"gear":"live_fish","best":true,"note":{"en":"Live γόππα or small horse mackerel 12–18 cm, lip- or back-hooked, dropped tight to rock edges 20–60 m between Paphos and Agios Georgios; Jun–Oct, at dawn.","el":"Ζωντανή γόππα ή μικρό σαφρίδι 12–18 εκ., από τα χείλη ή την πλάτη, κολλητά στις άκρες των βράχων 20–60 μ. από Πάφο ως Άγιο Γεώργιο· Ιούν–Οκτ, χαράματα."},"src":["paphos_fbblog","paphos_kz"]},{"gear":"squid_bait","note":{"en":"Whole fresh squid, cuttlefish or small octopus on a two-hook rig; from autumn Cypriot boats switch to live squid and cuttlefish for big σφυρίδες.","el":"Ολόκληρο φρέσκο καλαμάρι, σουπιά ή μικρό χταπόδι σε αρματωσιά με δύο αγκίστρια· από το φθινόπωρο τα κυπριακά σκάφη περνούν σε ζωντανό καλαμάρι και σουπιά για μεγάλες σφυρίδες."},"src":["paphos_cfm_autumn","paphos_cfm_synagrida"]}],
    dentex: [{"gear":"squid_bait","best":true,"note":{"en":"Live squid slow-trolled on a downrigger lead 30–40 m back over reef at 25–60 m; on the hit, free-spool so the bait stays by the fish. Apr–May, Oct–Nov.","el":"Ζωντανό καλαμάρι σε αργή συρτή με φύλακα, 30–40 μ. πίσω, πάνω από ξέρα στα 25–60 μ.· στο χτύπημα άνοιξε το φρένο να μείνει το δόλωμα κοντά στο ψάρι. Απρ–Μάι, Οκτ–Νοέ."},"src":["paphos_cfm_synagrida"]},{"gear":"live_fish","note":{"en":"Live horse mackerel (σαφρίδι) or γόππα from a sabiki, or in autumn a small barracuda, on the same slow-troll; give the fish time to swallow before striking.","el":"Ζωντανό σαφρίδι ή γόππα από τσαπαρί, ή το φθινόπωρο λουτσάκι, στην ίδια αργή συρτή· δώσε χρόνο στο ψάρι να το καταπιεί πριν καρφώσεις."},"src":["paphos_cfm_synagrida","paphos_cfm_autumn"]}],
    albacore: [{"gear":"live_fish","best":true,"note":{"en":"Live mackerel or horse mackerel (κολιός, σαφρίδι) slow-trolled or drifted past the 100 m line, ~3–4 km out, Jun–Aug. Paphos charters mostly troll lures.","el":"Ζωντανός κολιός ή σαφρίδι σε αργή συρτή ή στο ρεύμα πέρα από τα 100 μ., ~3–4 χλμ. έξω, Ιούν–Αύγ. Τα σκάφη της Πάφου ψαρεύουν κυρίως συρτή με τεχνητά."},"src":["paphos_cfm_tuna","paphos_pauls","paphos_kz"]},{"gear":"sardine","note":{"en":"Sardine chunks thrown to hold a school after a strike, with a hooked chunk drifted in the slick. General practice; secondary to trolling here.","el":"Κομμάτια σαρδέλας για να μείνει το κοπάδι μετά από χτύπημα, με ένα δολωμένο κομμάτι να ταξιδεύει ανάμεσά τους. Γενική πρακτική· εδώ δευτερεύει της συρτής."}}],
    dolphinfish: [{"gear":"squid_bait","best":true,"note":{"en":"Piece of thawed squid on a small silicone squid/cuttlefish lure, light-trolled at 3–5 knots 25–30 fathoms back past buoys and reefs, late Aug–Nov.","el":"Κομματάκι ξεπαγωμένο καλαμάρι σε μικρή σιλικονένια σουπιά, ελαφριά συρτή 3–5 κόμβους, 25–30 οργιές πίσω, γύρω από σημαδούρες και ξέρες, τέλη Αύγ–Νοέ."},"src":["paphos_cfm_kynigoi","paphos_pauls"]},{"gear":"sardine","note":{"en":"Once one is on, keep it in the water and throw cut bait to hold the school by the boat; drift a sardine chunk on a light hook among them.","el":"Μόλις πιαστεί ένας, κράτα τον στο νερό και ρίχνε κομματάκια δόλωμα να μείνει το κοπάδι στο σκάφος· άφησε ένα κομμάτι σαρδέλας σε λεπτό αγκίστρι ανάμεσά τους."},"src":["paphos_cfm_kynigoi"]},{"gear":"live_fish","note":{"en":"Small live fish free-lined beside a buoy or floating object. General practice, no local source.","el":"Μικρό ζωντανό ψαράκι ελεύθερο δίπλα σε σημαδούρα ή επιπλέον αντικείμενο. Γενική πρακτική, όχι τοπική πηγή."}}],
    octopus: [{"gear":"crab","best":true,"note":{"en":"Small crab tied on a white octopus jig, dragged slowly over rock and rubble at 2–15 m, Oct–May. General Cyprus practice: no local source found.","el":"Καβουράκι δεμένο σε άσπρη χταποδιέρα, σέρνοντας αργά σε βράχια και κοτρόνες στα 2–15 μ., Οκτ–Μάι. Γενική πρακτική στην Κύπρο: δεν βρέθηκε τοπική πηγή."}},{"gear":"sardine","note":{"en":"Fresh sardine or a small bogue bound to the jig when no crab is at hand. General practice.","el":"Φρέσκια σαρδέλα ή μικρή γόππα δεμένη στη χταποδιέρα όταν δεν έχεις καβούρι. Γενική πρακτική."}}],
    parrotfish: [{"gear":"shrimp","best":true,"note":{"en":"Live sea lice (φτείρα, ≥1 cm) from washed-up seaweed, hooked through the tail on a single hook near bottom: true Cypriot σκάρος anglers use nothing else. Jun–Oct.","el":"Ζωντανή φτείρα (≥1 εκ.) από ξεβρασμένα φύκια, από την ουρά σε μονάγκιστρο κοντά στον βυθό: οι γνήσιοι σκαροψαράδες δεν βάζουν άλλο δόλωμα. Ιούν–Οκτ."},"src":["paphos_cfm_fteira"]},{"gear":"bread","note":{"en":"Dough on a small hook, or small shrimp pieces, over Posidonia and weedy rock: σκάροι take both when bogue are fished with them.","el":"Ζύμη σε μικρό αγκίστρι ή κομματάκια γαρίδας πάνω από ποσειδωνία και βράχια με φύκια: οι σκάροι τα τρώνε και όταν ψαρεύουμε γόππες."},"src":["paphos_cfm_gopa"]},{"gear":"algae","note":{"en":"Fine green weed from the same rocks, their natural food. General practice, no local source.","el":"Λεπτό πράσινο φύκι από τα ίδια βράχια, η φυσική τους τροφή. Γενική πρακτική, όχι τοπική πηγή."}}],
    greymullet: [{"gear":"bread","best":true,"note":{"en":"Bread loaf (φραντζόλα) crust or soft dough on a multi-hook rig (πολυάγκιστρο) 50–60 m out in February, when mullet crowd the shore; also off the harbour walls.","el":"Φραντζόλα (κόρα ή ψίχα) ή μαλακή ζύμη σε πολυάγκιστρο στα 50–60 μ. τον Φεβρουάριο, που οι κέφαλοι μαζεύονται στα παράλια· και από τους τοίχους του λιμανιού."},"src":["paphos_cfm_season"]},{"gear":"groundbait","note":{"en":"Soaked bread with cheese, no sand in shallow water, kept going little and often: Cypriot anglers count wet bread a must for κέφαλοι.","el":"Μουσκεμένο ψωμί με τυρί, χωρίς άμμο στα ρηχά, λίγο και συχνά: οι Κύπριοι ψαράδες θεωρούν το βρεγμένο ψωμί απαραίτητο για τους κέφαλους."},"src":["paphos_cfm_antena"]},{"gear":"sardine","note":{"en":"Sardine dough (mashed sardine, soaked bread, a little oil, firmed with rusk) for harbour mullet that ignore plain bread. General practice.","el":"Ζύμη σαρδέλας (λιωμένη σαρδέλα, μουσκεμένο ψωμί, λίγο λάδι, σφιγμένη με φρυγανιά) για κέφαλους του λιμανιού που αγνοούν το σκέτο ψωμί. Γενική πρακτική."}}],
    lionfish: [{"gear":"shrimp","best":true,"note":{"en":"Small shrimp on a size 8–10 hook dropped at the base of rock edges and reef holes at dusk; catches are incidental, spears remove most. General, not local.","el":"Μικρή γαρίδα σε αγκίστρι 8–10 στη βάση των βράχων και στις τρύπες της ξέρας το σούρουπο· πιάνεται περιστασιακά, τα περισσότερα βγαίνουν με ψαροντούφεκο. Γενική πρακτική."},"src":["paphos_relion"]},{"gear":"squid_bait","note":{"en":"Small strip of squid or fish on the same light rig; lionfish eat small fish and crustaceans. General, no local catch reports found. Mind the venomous spines.","el":"Μικρή λωρίδα καλαμαριού ή ψαριού στην ίδια ελαφριά σύνθεση· το λεοντόψαρο τρώει μικρά ψάρια και καρκινοειδή. Γενική πρακτική. Προσοχή στα δηλητηριώδη αγκάθια."},"src":["paphos_relion"]}],
  },
  pissouri: {
    tsipoura: [{"gear":"worm","best":true,"note":{"en":"Whole pharaoh (φαραώ) or American worm threaded on a needle, long leader in the wash of the Pissouri/Avdimou sand at dusk and night, Oct–Mar.","el":"Ολόκληρο φαραώ ή αμερικάνος περασμένος με βελόνα, μακρύ παράμαλλο στο κύμα, στην άμμο Πισσουρίου/Αυδήμου, σούρουπο και νύχτα, Οκτ–Μαρ."},"src":["pissouri_cyshore","pissouri_bfts"]},{"gear":"crab","note":{"en":"Small whole crab (σκαλτσίνι) or half a crab bound with elastic thread: big gilthead take it, small bream can't strip it. Best at dawn and dusk.","el":"Ολόκληρο καβουράκι (σκαλτσίνι) ή μισό καβούρι δεμένο με λαστιχένια κλωστή: το παίρνουν οι μεγάλες, δεν το καθαρίζουν τα μικρά. Καλύτερα χαράματα και σούρουπο."},"src":["pissouri_bfts","pissouri_cyshore"]},{"gear":"sardine","note":{"en":"Fresh sardine, head off, hook buried in the body and bound with elastic thread for the long casts past the break these shallow bays need.","el":"Φρέσκια σαρδέλα χωρίς κεφάλι, αγκίστρι μέσα στο σώμα, δεμένη με λαστιχένια κλωστή για τις μακρινές βολές πέρα από το κύμα που θέλουν οι ρηχοί κόλποι."},"src":["pissouri_bfts"]}],
    sargos: [{"gear":"worm","best":true,"note":{"en":"Pharaoh (φαραώ) piece or American worm in the foam by the cliff-base boulders of Cape Aspro and the Petra tou Romiou rocks, dusk into night.","el":"Κομμάτι φαραώ ή αμερικάνος στον αφρό, στις πέτρες στη βάση των γκρεμών του Κάβο Άσπρο και στα βράχια της Πέτρας του Ρωμιού, από το σούρουπο ως τη νύχτα."},"src":["pissouri_cyshore","pissouri_drsar"]},{"gear":"crab","note":{"en":"Small crab (σκαλτσίνι), cut and tied with elastic thread, cast into rough, green water after a blow: picks the big sargos and holds in the surge.","el":"Καβουράκι (σκαλτσίνι) κομμένο και δεμένο με λαστιχένια κλωστή, σε ταραγμένο, πράσινο νερό μετά από φουρτούνα: διαλέγει τους μεγάλους και κρατά στο κύμα."},"src":["pissouri_psnet","pissouri_cyshore"]},{"gear":"shrimp","note":{"en":"Live small shrimp (γαριδούλα) or whole shrimp on a float or light casting rig off the rock patches in calmer water; a top early-morning bait.","el":"Ζωντανή γαριδούλα ή ολόκληρη γαρίδα σε φελλό ή ελαφρύ πεταχτάρι δίπλα στα βραχάκια όταν ηρεμεί· κορυφαίο δόλωμα τις πρώτες πρωινές ώρες."},"src":["pissouri_cycast","pissouri_drsar"]}],
    pompano: [{"gear":"shrimp","best":true,"note":{"en":"Live or fresh whole shrimp, hook 4–2, light surf rig in the surge of Pissouri, Avdimou and Petra tou Romiou beaches at dawn and dusk, Jul–Oct. General.","el":"Ζωντανή ή φρέσκια ολόκληρη γαρίδα, αγκίστρι 4–2, ελαφριά σύνθεση surf στο κύμα σε Πισσούρι, Αυδήμου, Πέτρα του Ρωμιού, χαράματα και σούρουπο, Ιούλ–Οκτ. Γενικό."},"src":["pissouri_fbtrach"]},{"gear":"live_fish","note":{"en":"Live sand smelt (αθερίνα) or small bogue free-lined into the wash when a school is chasing bait along the beach at first light. General, not local.","el":"Ζωντανή αθερίνα ή μικρή γόππα ελεύθερη στο κύμα όταν το κοπάδι κυνηγά ψαράκια κατά μήκος της παραλίας με το πρώτο φως. Γενικό, όχι τοπικό."},"src":["pissouri_fbtrach"]},{"gear":"worm","note":{"en":"American or Korean worm on the same light surf rig; less selective, mostly a by-catch while fishing for bream. General Cyprus practice.","el":"Αμερικάνος ή κορεάτικο στην ίδια ελαφριά σύνθεση surf· λιγότερο επιλεκτικό, πιάνεται κυρίως παρεμπιπτόντως με τα σπαροειδή. Γενική πρακτική στην Κύπρο."}}],
    bluefish: [{"gear":"sardine","best":true,"note":{"en":"Half sardine or fillet on a long-shank hook or short wire, cast from the beaches or the Cape Aspro rocks at dusk and night, autumn–winter.","el":"Μισή σαρδέλα ή φιλέτο σε αγκίστρι με μακρύ λαιμό ή κοντό συρματάκι, από τις παραλίες ή τα βράχια στο Κάβο Άσπρο, σούρουπο και νύχτα, φθινόπωρο–χειμώνα."},"src":["pissouri_cyshore","pissouri_cyfish"]},{"gear":"live_fish","note":{"en":"Live garfish (ζαργάνα), sand smelt or small mullet, free-lined or slow-trolled along the bays; Cypriot anglers troll the same fish dead in summer.","el":"Ζωντανή ζαργάνα, αθερίνα ή μικρός κέφαλος, ελεύθερα ή σε αργή συρτή κατά μήκος των κόλπων· στην Κύπρο σέρνουν τα ίδια ψαράκια και νεκρά το καλοκαίρι."},"src":["pissouri_cyfish"]},{"gear":"squid_bait","note":{"en":"Squid strip or small whole squid on a surf or trolling rig: tough, so it stays on through the bluefish's slashing bites.","el":"Λωρίδα καλαμαριού ή μικρό ολόκληρο καλαμάρι σε surf ή συρτή: σκληρό, μένει στο αγκίστρι παρά τις κοφτές δαγκωνιές του γοφαριού."},"src":["pissouri_cyfish"]}],
    annular: [{"gear":"worm","best":true,"note":{"en":"Small pieces of Korean or American worm on hooks 10–8, light casting rig by day over sand near the scattered rock patches of the bays.","el":"Μικρά κομμάτια κορεάτικου ή αμερικάνου σε αγκίστρια 10–8, ελαφρύ πεταχτάρι τη μέρα, στην άμμο κοντά στα σκόρπια βραχάκια των κόλπων."},"src":["pissouri_cycast"]},{"gear":"shrimp","note":{"en":"Peeled shrimp cut to hook size: sparos take a firmer bait than mullet, so it lasts longer among the small fish.","el":"Καθαρισμένη γαρίδα κομμένη στο μέγεθος του αγκιστριού: ο σπάρος θέλει πιο σκληρό δόλωμα από τον κέφαλο, άρα κρατά περισσότερο ανάμεσα στα μικρά."},"src":["pissouri_cyapiko","pissouri_cycast"]},{"gear":"sardine","note":{"en":"Small firm strip of fresh sardine over sardine groundbait (sand and gravel mixed in) to pull sparos to the rock edges.","el":"Μικρή σφιχτή λωρίδα φρέσκιας σαρδέλας πάνω από μαλάγρα σαρδέλας (με άμμο και χαλίκι) για να μαζέψει τους σπάρους στις άκρες των βράχων."},"src":["pissouri_cyapiko","pissouri_cyshore"]}],
    redmullet: [{"gear":"worm","best":true,"note":{"en":"Thin red sand worm or τριχιά threaded on a needle, fine-wire hooks, drifting the mud-sand shelf at 30–80 m off Pissouri and Avdimou by day.","el":"Λεπτό κόκκινο σκουλήκι της άμμου ή τριχιά περασμένο με βελόνα, λεπτά αγκίστρια, ντρίφτ στη λασπο-αμμουδιά στα 30–80 μ. έξω από Πισσούρι και Αυδήμου, τη μέρα."},"src":["pissouri_drbar"]},{"gear":"shrimp","note":{"en":"Thin, long strips of shrimp when sand worms can't be found; keep them small for the red mullet's small mouth.","el":"Λεπτές, μακρόστενες λωρίδες γαρίδας όταν δεν βρίσκεις σκουλήκια της άμμου· μικρές, για το μικρό στόμα της στρίλιας."},"src":["pissouri_drbar"]}],
    surmullet: [{"gear":"worm","best":true,"note":{"en":"Thin sand worm (τριχιά, red worm) on a needle, by day on coarse sand and gravel near the rock patches at 5–40 m; from the Pissouri sand too.","el":"Λεπτό σκουλήκι της άμμου (τριχιά, κόκκινο) με βελόνα, τη μέρα σε χοντρή άμμο και χαλίκι κοντά στα βραχάκια στα 5–40 μ.· και από την άμμο του Πισσουρίου."},"src":["pissouri_drbar"]},{"gear":"shrimp","note":{"en":"Thin shrimp strips as a backup, on a small hook and short dropper fishing right on the bottom.","el":"Λεπτές λωρίδες γαρίδας ως εναλλακτικό, σε μικρό αγκίστρι και κοντό παράμαλλο που ψαρεύει πάνω στον βυθό."},"src":["pissouri_drbar"]}],
    pandora: [{"gear":"shrimp","best":true,"note":{"en":"Whole shrimp, unpeeled in winter, on the bottom along sand–rock edges and around Jubilee Shoal at 20–100 m; the big ones come in winter–spring.","el":"Ολόκληρη γαρίδα, ακαθάριστη τον χειμώνα, στον βυθό στα όρια άμμου–βράχου και γύρω από την ξέρα Jubilee στα 20–100 μ.· τα μεγάλα χειμώνα–άνοιξη."},"src":["pissouri_bflyth"]},{"gear":"squid_bait","note":{"en":"Squid tentacle or strip threaded on both hooks together: stays on and filters out the small fish that strip shrimp on the sand.","el":"Πλοκάμι ή λωρίδα καλαμαριού περασμένη και στα δύο αγκίστρια μαζί: κρατάει και «φιλτράρει» τα μικρά που καθαρίζουν τη γαρίδα στην άμμο."},"src":["pissouri_bflyth"]},{"gear":"sardine","note":{"en":"Fresh sardine fillet pieces as a cheap backup; soft, so check the hook often. General practice.","el":"Κομμάτια φρέσκου φιλέτου σαρδέλας ως φθηνό εναλλακτικό· μαλακό, έλεγχε συχνά το αγκίστρι. Γενική πρακτική."}}],
    amberjack: [{"gear":"live_fish","best":true,"note":{"en":"Live bogue (γόππα) or horse mackerel 15–20 cm from a sabiki on site, drifted by the Jubilee Shoal wall at 20–60 m at dawn; small fish best in summer.","el":"Ζωντανή γόππα ή σαυρίδι 15–20 εκ. από τσαπαρί επί τόπου, στο τοίχωμα της ξέρας Jubilee στα 20–60 μ. τα χαράματα· τα ψαράκια καλύτερα το καλοκαίρι."},"src":["pissouri_padi","pissouri_duik","pissouri_drmag"]},{"gear":"squid_bait","note":{"en":"Live squid (autumn–winter) or live cuttlefish (spring), hooked by the tail and slow-trolled on a lead over the shoal and the rock patches.","el":"Ζωντανό καλαμάρι (φθινόπωρο–χειμώνα) ή ζωντανή σουπιά (άνοιξη), από την ουρά, σε αργή συρτή με μολύβι φύλακα πάνω από την ξέρα και τα βραχάκια."},"src":["pissouri_drmag"]}],
    dentex: [{"gear":"squid_bait","best":true,"note":{"en":"Live squid 30–40 cm, hooks in tail and tentacle base, slow-trolled at 0.5–1.5 kn over Jubilee Shoal and lone rocks on sand; winter mornings to ~10:00.","el":"Ζωντανό καλαμάρι 30–40 εκ., αγκίστρια στην ουρά και στη βάση των πλοκαμιών, συρτή φύλακα 0,5–1,5 κόμβους πάνω από την Jubilee και πέτρες στην άμμο· πρωί χειμώνα."},"src":["pissouri_bfsyn","pissouri_dpp","pissouri_duik"]},{"gear":"live_fish","note":{"en":"Live bogue (γόππα) or small horse mackerel from the sabiki, slow-trolled near the bottom over the rock patches when no squid can be caught.","el":"Ζωντανή γόππα ή μικρό σαυρίδι από το τσαπαρί, σε αργή συρτή κοντά στον βυθό πάνω από τα βραχάκια, όταν δεν πιάνεται καλαμάρι."},"src":["pissouri_bfsyn","pissouri_dpp"]}],
    littletunny: [{"gear":"live_fish","best":true,"note":{"en":"Live sand smelt or small horse mackerel free-lined into a feeding school along the 50–100 m line in autumn, at dawn or dusk. General, not local.","el":"Ζωντανή αθερίνα ή μικρό σαυρίδι ελεύθερα μέσα στο κοπάδι που τρώει, στη γραμμή των 50–100 μ. το φθινόπωρο, χαράματα ή σούρουπο. Γενικό, όχι τοπικό."},"src":["pissouri_bfton"]},{"gear":"sardine","note":{"en":"Whole small sardine or anchovy drifted unweighted down a sardine chum line at dawn or dusk; most locals troll lures instead. General.","el":"Ολόκληρη μικρή σαρδέλα ή γαύρος χωρίς βαρίδι μέσα σε μαλάγρα σαρδέλας, χαράματα ή σούρουπο· οι περισσότεροι εδώ σέρνουν τεχνητά. Γενικό."},"src":["pissouri_bfton"]}],
    octopus: [{"gear":"sardine","best":true,"note":{"en":"Two small fresh sardines bound on a white octopus jig, dragged slowly over sand and scattered stones at the cliff base or off Melanda pier; autumn–winter mornings.","el":"Δύο μικρές φρέσκιες σαρδέλες δεμένες σε άσπρη χταποδιέρα, σερνάμενες αργά σε άμμο και σκόρπιες πέτρες στη βάση των γκρεμών ή από την προβλήτα της Μελάντας· πρωί, φθινόπωρο–χειμώνας."},"src":["pissouri_psocto","pissouri_drocto"]},{"gear":"crab","note":{"en":"Real crab tied on the jig (or a crab imitation), worked along the boulders at the cliff foot; big octopus also hunt the open sand here.","el":"Αληθινό καβούρι δεμένο στη χταποδιέρα (ή ομοίωμα), κατά μήκος των βράχων στη βάση των γκρεμών· τα μεγάλα χταπόδια κυνηγούν κι έξω στην άμμο."},"src":["pissouri_drocto"]}],
    cuttlefish: [{"gear":"sardine","best":true,"note":{"en":"Dead small fish (sardine, bogue) bound on a bait jig, dragged slowly over sand with scattered stones from just before dusk, spring. Old method, thin sources.","el":"Νεκρό ψαράκι (σαρδέλα, γόππα) δεμένο σε καλαμαριέρα δολώματος, σερνάμενο αργά σε άμμο με σκόρπιες πέτρες λίγο πριν το σούρουπο, άνοιξη. Παλιά μέθοδος, λίγες πηγές."},"src":["pissouri_mega"]},{"gear":"live_fish","note":{"en":"Small live fish under a float at dusk and night over the sandy bays, when cuttlefish hunt close in. General practice, weakly sourced.","el":"Μικρό ζωντανό ψαράκι με φελλό, σούρουπο και νύχτα πάνω από τους αμμώδεις κόλπους, όταν οι σουπιές κυνηγούν κοντά. Γενική πρακτική, λίγες πηγές."},"src":["pissouri_mega"]}],
    greymullet: [{"gear":"bread","best":true,"note":{"en":"Soft bread flake or bread-and-cheese dough on a float over groundbait, by Melanda pier or at the Chapotami/Diarizos mouths after winter rain.","el":"Μαλακή ψίχα ή ζυμάρι ψωμιού με τυρί σε φελλό πάνω από μαλάγρα, στην προβλήτα της Μελάντας ή στις εκβολές Χάποταμου/Διαρίζου μετά τις χειμωνιάτικες βροχές."},"src":["pissouri_cyapiko"]},{"gear":"sardine","note":{"en":"Thin strips of sardine or anchovy cut with scissors (ψαροδόλι), or soft sardine dough: mullet want the bait soft and small.","el":"Λεπτές λωρίδες σαρδέλας ή γαύρου κομμένες με ψαλίδι (ψαροδόλι), ή μαλακό ζυμάρι σαρδέλας: ο κέφαλος θέλει το δόλωμα μαλακό και μικρό."},"src":["pissouri_drkef","pissouri_cyapiko","pissouri_cyshore"]},{"gear":"groundbait","note":{"en":"Sardine groundbait mixed with sand and gravel so it sinks and holds scent; 5–6 balls to start, then 1–2 whenever bites slow.","el":"Μαλάγρα σαρδέλας με άμμο και χαλίκι για να βουλιάζει και να κρατά τη μυρωδιά· 5–6 μπάλες στην αρχή, μετά 1–2 όποτε αραιώνουν οι τσιμπιές."},"src":["pissouri_cyapiko","pissouri_drkef"]}],
  },
  akrotiri: {
    tsipoura: [{"gear":"worm","best":true,"note":{"en":"Whole pharaoh worm (φαραώ) threaded on a 1/0–2 hook, cast past the first trough at Lady's Mile on calm winter nights or sunny winter days. It stays on long casts.","el":"Ολόκληρο φαραώ περασμένο σε αγκίστρι 1/0–2, βολή πέρα από το πρώτο βάθυμα στο Lady's Mile, ήρεμες νύχτες ή ηλιόλουστες μέρες του χειμώνα. Αντέχει στις μακριές βολές."},"src":["akrotiri_pcy10","akrotiri_bfcold","akrotiri_alllim"]},{"gear":"crab","note":{"en":"Whole small crab 3–7 cm across for the big fish, at dawn and dusk in the shallow Lady's Mile surf (under 5 m). Small bream and puffers can't strip it like worm.","el":"Καβουράκι 3–7 εκ. ολόκληρο, για τις μεγάλες τσιπούρες τα χαράματα και το σούρουπο στα ρηχά (κάτω από 5 μ.) του Lady's Mile. Τα μικρά και οι λαγοκέφαλοι δεν το ξεγυμνώνουν όπως το σκουλήκι."},"src":["akrotiri_bfcrab","akrotiri_bfcold"]},{"gear":"shrimp","note":{"en":"Whole prawn, head on, on a running ledger or float off the Akrotiri shelter breakwater at dusk. If puffers keep stripping it, switch to crab.","el":"Ολόκληρη γαρίδα με το κεφάλι, σε συρόμενο μολύβι ή φελλό από τον μόλο του καταφυγίου Ακρωτηρίου το σούρουπο. Αν οι λαγοκέφαλοι την ξεγυμνώνουν, άλλαξε σε καβουράκι."},"src":["akrotiri_agrino","akrotiri_ytpuffer","akrotiri_dom"]},{"gear":"mussel","note":{"en":"2–3 shelled mussels bound with elastic thread. Gilthead graze shellfish on this sand and Posidonia bottom. Cast shorter and smoother, as mussel flies off hard casts.","el":"2–3 ξεκέλυφα μύδια δεμένα με λαστιχένια κλωστή· η τσιπούρα βόσκει οστρακοειδή σε αυτή την άμμο με ποσειδωνία. Πιο κοντές, ομαλές βολές, γιατί στις δυνατές το μύδι φεύγει."},"src":["akrotiri_gcledger","akrotiri_agrino"]}],
    seabass: [{"gear":"shrimp","best":true,"note":{"en":"Live shrimp hooked through the tail (size 10–12) under a float off the Akrotiri shelter at dusk and night in winter. Lady's Mile bass also take small shrimp-fly rigs.","el":"Ζωντανή γαρίδα από την ουρά (αγκίστρι 10–12) σε φελλό στο καταφύγιο Ακρωτηρίου, σούρουπο και νύχτα τον χειμώνα. Τα λαβράκια του Lady's Mile τσιμπούν και σε σαμπίκι-γαριδάκια."},"src":["akrotiri_psbass","akrotiri_ytsabiki","akrotiri_alllim","akrotiri_dom"]},{"gear":"live_fish","note":{"en":"A small live mullet or sand smelt caught on the spot, hooked lightly behind the dorsal fin, free-lined or under a light float in the Lady's Mile surf at dusk.","el":"Μικρός ζωντανός κέφαλος ή αθερίνα που πιάνεις επί τόπου, επιδερμικά πίσω από το ραχιαίο, ελεύθερο ή με ελαφρύ φελλό στο κύμα του Lady's Mile το σούρουπο."},"src":["akrotiri_pcy16","akrotiri_agrino"]},{"gear":"sardine","note":{"en":"A fresh sardine fillet bound onto a 1/0–2/0 hook on the surf rig on winter nights. Bass work the Lady's Mile shoreline, and the oily scent carries over the flat sand.","el":"Φρέσκο φιλέτο σαρδέλας δεμένο σε αγκίστρι 1/0–2/0 στην αρματωσιά surf, χειμωνιάτικες νύχτες· τα λαβράκια ψάχνουν την ακτή του Lady's Mile και η μυρωδιά απλώνει στην επίπεδη άμμο."},"src":["akrotiri_pcy10","akrotiri_alllim"]},{"gear":"worm","note":{"en":"A big pharaoh or American worm on the bream rig: bass come as by-catch on winter nights, more often in murky water after a blow.","el":"Μεγάλο φαραώ ή αμερικάνος στην αρματωσιά της τσιπούρας: το λαβράκι έρχεται παρεμπιπτόντως τις χειμωνιάτικες νύχτες, συχνότερα με θολό νερό μετά από φουρτούνα."},"src":["akrotiri_agrino"]}],
    sargos: [{"gear":"worm","best":true,"note":{"en":"Pharaoh worm cut to hook size (6–2) at dusk and night along the Akrotiri shelter breakwater rocks or over Posidonia patches. Cypriot anglers rate it the top sargos bait.","el":"Φαραώ κομμένο στο μέγεθος του αγκιστριού (6–2) το σούρουπο και τη νύχτα στα βράχια του μόλου του καταφυγίου Ακρωτηρίου ή πάνω από ποσειδωνία· το κορυφαίο δόλωμα για σαργό."},"src":["akrotiri_pcy10","akrotiri_dom"]},{"gear":"shrimp","note":{"en":"Small live shrimp (γαριδούλα) netted among the breakwater rocks, under a float along the shelter walls by day. Prawn pieces will do if you can't net any.","el":"Ζωντανή γαριδούλα που πιάνεις με απόχη στα βράχια του μόλου, σε φελλό κατά μήκος του καταφυγίου τη μέρα· αλλιώς κομμάτια γαρίδας."},"src":["akrotiri_pcy10","akrotiri_agrino"]},{"gear":"bread","note":{"en":"Bread-and-cheese dough, firmer than for mullet, over groundbait (apiko) inside the Akrotiri shelter on calm days: a cheap way to find sargos before switching to worm.","el":"Ζυμάρι ψωμιού με τυρί, πιο σφιχτό απ’ ό,τι για κέφαλο, πάνω από μαλάγρα (απίκο) μέσα στο καταφύγιο Ακρωτηρίου τις ήρεμες μέρες· φτηνός τρόπος να βρεις τους σαργούς πριν το σκουλήκι."},"src":["akrotiri_agrino","akrotiri_pcy11"]}],
    pompano: [{"gear":"shrimp","best":true,"note":{"en":"A piece of peeled prawn or a small whole shrimp on a size 6–2 hook, on a light surf rig in the first trough at Lady's Mile at dawn, Jun–Oct, before swimmers arrive.","el":"Κομμάτι ξεφλουδισμένης γαρίδας ή μικρή ολόκληρη γαρίδα σε αγκίστρι 6–2, ελαφριά αρματωσιά surf στο πρώτο βάθυμα του Lady's Mile την αυγή, Ιούν–Οκτ, πριν έρθουν οι λουόμενοι."},"src":["akrotiri_fbtov"]},{"gear":"live_fish","note":{"en":"A live sand smelt (αθερίνα) free-lined into the surf when pompano are seen chasing fry at dawn or dusk. Adults eat small fish as well as crustaceans.","el":"Ζωντανή αθερίνα ελεύθερη μέσα στο κύμα όταν τα λιτσούια κυνηγούν γόνο την αυγή ή το σούρουπο· τα μεγάλα τρώνε και ψαράκια, όχι μόνο καρκινοειδή."},"src":["akrotiri_fbtov"]},{"gear":"worm","note":{"en":"An American or Korean worm on a light two-hook surf rig. This is general advice: it picks up pompano alongside striped bream on sandy Cyprus beaches.","el":"Αμερικάνος ή κορεάτικο σκουλήκι σε ελαφριά δίαγκιστρη αρματωσιά surf· γενική πρακτική, πιάνει λιτσούι μαζί με μουρμούρες στις αμμουδιές της Κύπρου."}}],
    bluefish: [{"gear":"sardine","best":true,"note":{"en":"Half a fresh sardine or a fillet on a long-shank 1/0–2/0 hook with a short wire or thick trace, on the Lady's Mile surf rig at dusk and night, Oct–Feb.","el":"Μισή φρέσκια σαρδέλα ή φιλέτο σε αγκίστρι μακρύλαιμο 1/0–2/0 με κοντό συρμάτινο ή χοντρό παράμαλλο, στην αρματωσιά surf του Lady's Mile σούρουπο και νύχτα, Οκτ–Φεβ."},"src":["akrotiri_pcy10","akrotiri_agrino"]},{"gear":"live_fish","note":{"en":"Live sand smelt, bogue or small horse mackerel under a float from the shelter breakwater, or from a boat near the fish farm (outside 100 m) when bluefish are breaking.","el":"Ζωντανή αθερίνα, γόπα ή μικρό σαφρίδι με φελλό από τον μόλο του καταφυγίου, ή από βάρκα κοντά στην ιχθυοκαλλιέργεια (έξω από τα 100 μ.) όταν τα γοφάρια χτυπούν στην επιφάνεια."},"src":["akrotiri_agrino"]}],
    cuttlefish: [{"gear":"sardine","best":true,"note":{"en":"A small dead fish (sardine or bogue) bound to a bait jig and dragged slowly over sand and Posidonia edges near the Akrotiri shelter on spring evenings (Mar–May).","el":"Μικρό νεκρό ψαράκι (σαρδέλα ή γόπα) δεμένο σε καλαμαριέρα δολώματος, σέρνεται αργά σε άμμο και άκρες ποσειδωνίας κοντά στο καταφύγιο Ακρωτηρίου, ανοιξιάτικα απογεύματα (Μαρ–Μάι)."},"src":["akrotiri_garmin"]},{"gear":"live_fish","note":{"en":"A small live fish (sand smelt, bogue fry) under a float at dusk over the shallow Posidonia patches. Cuttlefish hunt small fish and shrimp there in spring.","el":"Μικρό ζωντανό ψαράκι (αθερίνα, γοπάκι) σε φελλό το σούρουπο πάνω από τα ρηχά κομμάτια ποσειδωνίας· εκεί κυνηγά η σουπιά ψαράκια και γαρίδες την άνοιξη."},"src":["akrotiri_garmin"]}],
    pandora: [{"gear":"shrimp","best":true,"note":{"en":"A whole unpeeled prawn across two hooks, drifting the sandy shelf at 20–60 m. Pufferfish strip prawn in Akrotiri Bay, so check the bait often.","el":"Ολόκληρη ακαθάριστη γαρίδα περασμένη σε δύο αγκίστρια, ντρίφτ στην αμμώδη υφαλοκρηπίδα στα 20–60 μ. Στον κόλπο του Ακρωτηρίου οι λαγοκέφαλοι την ξεγυμνώνουν: έλεγχε συχνά."},"src":["akrotiri_bfpandora","akrotiri_ytpuffer"]},{"gear":"squid_bait","note":{"en":"A squid tentacle or strip on a 2–1/0 hook. It lasts against the puffers and small fish that empty prawn baits in Akrotiri Bay, and it picks out the bigger pandora.","el":"Πλοκάμι ή λωρίδα καλαμαριού σε αγκίστρι 2–1/0: αντέχει στους λαγοκέφαλους και τα μικρά που αδειάζουν τη γαρίδα στον κόλπο του Ακρωτηρίου και διαλέγει μεγαλύτερα λυθρίνια."},"src":["akrotiri_bfpandora","akrotiri_ytpuffer","akrotiri_fblim"]},{"gear":"sardine","note":{"en":"Strips of sardine fillet on the evening drift, a cheap third choice. This is general practice; no local report was found.","el":"Λωρίδες φιλέτου σαρδέλας στο απογευματινό ντρίφτ, φτηνή τρίτη επιλογή. Γενική πρακτική, δεν βρέθηκε τοπική αναφορά."}}],
    redmullet: [{"gear":"worm","best":true,"note":{"en":"Thin worms (red sand worm or τριχιά) threaded on size 10–12 hooks, worked slowly over sand and mud at 25–60 m off Lady's Mile. Tap the sinker to raise a puff of silt.","el":"Λεπτά σκουλήκια (κόκκινο της άμμου, τριχιά) περασμένα σε αγκίστρια 10–12, αργά σε άμμο-λάσπη στα 25–60 μ. έξω από το Lady's Mile· χτύπα το βαρίδι να σηκώσει θολούρα."},"src":["akrotiri_drsurm_v"]},{"gear":"shrimp","note":{"en":"Thin strips of peeled prawn when you run out of worms. Keep the bait small, so puffers and picarels in the bay take less of it.","el":"Λεπτές λωρίδες ξεφλουδισμένης γαρίδας όταν τελειώσουν τα σκουλήκια· κράτα το δόλωμα μικρό ώστε λαγοκέφαλοι και μαρίδες στον κόλπο να παίρνουν λιγότερο."},"src":["akrotiri_ytpuffer"]}],
    squid: [{"gear":"sardine","best":true,"note":{"en":"Sardine or another oily or shiny small fish on a squid needle (καφτερό) under a lit float, from the Akrotiri shelter breakwater at dusk and dawn, Nov–Mar.","el":"Σαρδέλα ή άλλο λιπαρό ή γυαλιστερό ψαράκι σε καφτερό κάτω από φελλό με χημικό φωτάκι, από τον μόλο του καταφυγίου Ακρωτηρίου σούρουπο και χαράματα, Νοέ–Μαρ."},"src":["akrotiri_bfsquid","akrotiri_dom"]},{"gear":"live_fish","note":{"en":"A live sand smelt or small bogue on a squid needle, drifted at dusk over 15–40 m off Lady's Mile. This is general practice; no local report was found.","el":"Ζωντανή αθερίνα ή μικρή γόπα σε καφτερό, σε ντρίφτ το σούρουπο στα 15–40 μ. έξω από το Lady's Mile. Γενική πρακτική, δεν βρέθηκε τοπική αναφορά."},"src":[]}],
    littletunny: [{"gear":"live_fish","best":true,"note":{"en":"A live sand smelt or small horse mackerel free-lined into a feeding school off Cape Gata, Sep–Nov. Stay out of the base's restricted waters.","el":"Ζωντανή αθερίνα ή μικρό σαφρίδι ελεύθερο μέσα στο κοπάδι που τρώει έξω από το Κάβο Γάτα, Σεπ–Νοέ. Μείνε έξω από τα απαγορευμένα νερά της βάσης."},"src":["akrotiri_adri"]},{"gear":"sardine","note":{"en":"Sardine chunks thrown as chum from a drifting boat, with a hooked chunk drifting in the slick. This is a general Mediterranean method; no local report was found.","el":"Κομμάτια σαρδέλας για μαλάγρα από βάρκα σε ντρίφτ, με αγκιστρωμένο κομμάτι να ακολουθεί το ίχνος. Γενική μεσογειακή μέθοδος, δεν βρέθηκε τοπική αναφορά."}}],
    amberjack: [{"gear":"live_fish","best":true,"note":{"en":"Live bogue or horse mackerel caught near the fish farm, slow-trolled or drifted near the bottom outside the 100 m zone or on the Cape Gata bank. Best Aug–Oct.","el":"Ζωντανή γόπα ή σαφρίδι από κοντά στην ιχθυοκαλλιέργεια, σε αργή συρτή ή ντρίφτ κοντά στον βυθό έξω από τα 100 μ. ή στην ξέρα του Κάβο Γάτα· καλύτερα Αύγ–Οκτ."},"src":["akrotiri_agrino","akrotiri_farms","akrotiri_fblim"]},{"gear":"squid_bait","note":{"en":"A live squid in autumn and winter (caught on the same dusk drift), or a live cuttlefish in spring, slow-trolled on a lead for the big amberjack.","el":"Ζωντανό καλαμάρι φθινόπωρο–χειμώνα (από το ίδιο απογευματινό ντρίφτ) ή ζωντανή σουπιά την άνοιξη, σε αργή συρτή με μολύβι φύλακα για τα μεγάλα μαγιάτικα."},"src":["akrotiri_dramber"]}],
    octopus: [{"gear":"crab","best":true,"note":{"en":"A crab, real or imitation, on a white octopus jig (χταποδιέρα), dragged slowly over sand and Posidonia and along the shelter breakwater rocks in 2–10 m.","el":"Καβούρι, αληθινό ή ομοίωμα, σε άσπρη χταποδιέρα, σέρνεται αργά σε άμμο και ποσειδωνία και στα βράχια του μόλου του καταφυγίου στα 2–10 μ."},"src":["akrotiri_droct"]},{"gear":"sardine","note":{"en":"A fresh small fish tied to the jig's wire. Chicken feet are the traditional alternative and last longer against small fish.","el":"Νωπό ψαράκι δεμένο στο σύρμα της χταποδιέρας· τα κοτοπόδαρα είναι η παραδοσιακή εναλλακτική και κρατούν περισσότερο στα μικρά ψάρια."},"src":["akrotiri_droct"]}],
    greymullet: [{"gear":"bread","best":true,"note":{"en":"Bread flake or soft bread-and-cheese dough (ψωμοτύρι) on a size 14–18 hook under a light float inside the Akrotiri shelter by day. Mullet suck baits in: keep it soft.","el":"Ψίχα ή μαλακό ψωμοτύρι σε αγκίστρι 14–18 με ελαφρύ φελλό μέσα στο καταφύγιο Ακρωτηρίου τη μέρα· ο κέφαλος ρουφά, κράτα το μαλακό."},"src":["akrotiri_agrino","akrotiri_bfapiko","akrotiri_dom"]},{"gear":"groundbait","note":{"en":"Bread-based groundbait flavoured like the hook bait, thrown one loose ball at a time, to hold mullet in the shelter or off the calm southern end of Lady's Mile.","el":"Μαλάγρα με βάση το ψωμί και ίδια γεύση με το δόλωμα, μία χαλαρή μπάλα τη φορά, για να κρατήσεις τους κεφάλους στο καταφύγιο ή στο ήρεμο νότιο άκρο του Lady's Mile."},"src":["akrotiri_drmullet","akrotiri_vc"]},{"gear":"sardine","note":{"en":"Sardine-based dough, or thin sardine strips covering the hook, for the bigger mullet once they are feeding on the groundbait.","el":"Ζυμάρι με βάση τη σαρδέλα ή λεπτές λωρίδες σαρδέλας που καλύπτουν το αγκίστρι, για τους μεγαλύτερους κεφάλους όταν τρώνε στη μαλάγρα."},"src":["akrotiri_bfapiko","akrotiri_drmullet"]}],
    surmullet: [{"gear":"worm","best":true,"note":{"en":"Thin worms (red sand worm, τριχιά, small American) on size 10–12 hooks, light casting rig over sand by Posidonia patches, dawn or dusk, outside the bathing season.","el":"Μικρά λεπτά σκουλήκια (κόκκινο της άμμου, τριχιά, μικρός αμερικάνος) σε αγκίστρια 10–12, ελαφριά αρματωσιά casting σε άμμο δίπλα σε ποσειδωνία, χαράματα ή σούρουπο, εκτός σεζόν λουομένων."},"src":["akrotiri_drsurm_c","akrotiri_drsurm_v"]},{"gear":"shrimp","note":{"en":"Thin strips of peeled prawn as a backup. This is general practice: in this area surmullet are mostly speared in 4–10 m.","el":"Λεπτές λωρίδες ξεφλουδισμένης γαρίδας ως εναλλακτική· γενική πρακτική, εδώ το μπαρμπούνι πιάνεται κυρίως με ψαροντούφεκο στα 4–10 μ."}}],
  },
  limassol: {
    sargos: [{"gear":"worm","best":true,"note":{"en":"Piece of pharaoh worm (φαραώ), rated Cyprus's top sargos bait (general), no. 4–6 hook tight to the groyne and Molos boulders at dusk and night, Oct–Apr.","el":"Κομμάτι φαραώ, το κορυφαίο δόλωμα για σαργό στην Κύπρο (γενικά), αγκίστρι Νο 4–6 κολλητά στις πέτρες των μόλων και του Μόλου, σούρουπο και νύχτα, Οκτ–Απρ."},"src":["limassol_s8","limassol_s14","limassol_s3"]},{"gear":"shrimp","note":{"en":"Live small shrimp (γαριδούλα) or a fresh shrimp tail on a float in the wash at the groyne tips by day, over a little groundbait. General practice.","el":"Ζωντανή γαριδούλα ή φρέσκια ουρά γαρίδας στον φελλό, στον αφρό στις μύτες των μόλων τη μέρα, με λίγη μάλαγρα. Γενική πρακτική."},"src":["limassol_s12","limassol_s14"]},{"gear":"crab","note":{"en":"Small crab (σκαλτσίνι) picked off the breakwater rocks, whole on a no. 2–4 hook at night for bigger sargos; small fish can't strip it. General.","el":"Σκαλτσίνι από τις πέτρες του μόλου, ολόκληρο σε αγκίστρι Νο 2–4 τη νύχτα για τους μεγάλους σαργούς· τα μικρά δεν το κλέβουν. Γενικό."},"src":["limassol_s12","limassol_s8"]},{"gear":"bread","note":{"en":"Firm bread or cheese dough on a float over bread groundbait along the Molos walls by day; sargos want it firmer than mullet do (Cypriot blog).","el":"Σφιχτό ζυμάρι ψωμιού ή τυριού στον φελλό πάνω από μάλαγρα ψωμιού στους τοίχους του Μόλου τη μέρα· ο σαργός το θέλει πιο σκληρό από τον κέφαλο."},"src":["limassol_s9","limassol_s14"]}],
    seabass: [{"gear":"shrimp","best":true,"note":{"en":"Live shrimp hooked through the tail under a float at the Marina and Old Port entrances at dusk and night, Nov–Mar; no fishing inside the port.","el":"Ζωντανή γαρίδα από την ουρά στον φελλό στις εισόδους της Μαρίνας και του Παλιού Λιμανιού, σούρουπο και νύχτα, Νοέ–Μαρ· όχι ψάρεμα μέσα στο λιμάνι."},"src":["limassol_s1","limassol_s2","limassol_s4","limassol_s22","limassol_s25"]},{"gear":"live_fish","note":{"en":"Small live mullet (κεφαλάκι) caught on bread at the groynes, hooked lightly behind the dorsal fin, at dawn by harbour mouths and stream outflows in winter.","el":"Ζωντανό κεφαλάκι πιασμένο με ψωμί στους μόλους, αγκιστρωμένο επιδερμικά πίσω από το ραχιαίο, χαράματα σε στόμια λιμανιών και εκβολές ρεμάτων τον χειμώνα."},"src":["limassol_s1","limassol_s10"]},{"gear":"sardine","note":{"en":"Fresh sardine pinned behind the eyes, skin nicked to bleed, on a running ledger off the sand beaches west of the Marina on winter nights.","el":"Φρέσκια σαρδέλα περασμένη πίσω από τα μάτια, χαραγμένη να ματώνει, σε συρταρωτή αρματωσιά στις αμμουδιές δυτικά της Μαρίνας τις νύχτες του χειμώνα."},"src":["limassol_s8","limassol_s2"]},{"gear":"worm","note":{"en":"Big worm (pharaoh, American) when winter rain muddies the water near stream mouths and shrimp is hard to see. General practice.","el":"Μεγάλο σκουλήκι (φαραώ, αμερικάνος) όταν η χειμωνιάτικη βροχή θολώνει τα νερά κοντά στις εκβολές και η γαρίδα δεν φαίνεται. Γενική πρακτική."},"src":["limassol_s8"]}],
    tsipoura: [{"gear":"worm","best":true,"note":{"en":"Whole pharaoh or American worm threaded on a needle, cast onto sand-and-Posidonia patches off the beaches west of the Marina, winter dawn, dusk and night.","el":"Ολόκληρο φαραώ ή αμερικάνος περασμένος με βελόνα, βολή σε άμμο με ποσειδωνία στις παραλίες δυτικά της Μαρίνας, χειμώνα χαράματα, σούρουπο και νύχτα."},"src":["limassol_s8","limassol_s15","limassol_s1","limassol_s2"]},{"gear":"crab","note":{"en":"Whole small crab or a claw for the big winter fish; small bream can't steal it. General, not local.","el":"Ολόκληρο καβουράκι ή δαγκάνα για τις μεγάλες χειμωνιάτικες· τα μικρά δεν το κλέβουν. Γενικό, όχι τοπικό."},"src":["limassol_s15"]},{"gear":"sardine","note":{"en":"Fresh sardine, head off, bound with elastic thread for long casts from the sand when the sun is high and the fish sit farther out.","el":"Φρέσκια σαρδέλα χωρίς κεφάλι, δεμένη με λαστιχένια κλωστή για μακρινές βολές από την άμμο όταν ο ήλιος είναι ψηλά και τα ψάρια είναι πιο έξω."},"src":["limassol_s15"]}],
    melanouri: [{"gear":"bread","best":true,"note":{"en":"Bread flake (ψίχα) on a light float 1–2 m down in a bread-and-sardine groundbait cloud at the Molos and groyne heads, by day, Apr–Oct.","el":"Ψίχα ψωμιού σε ελαφρύ φελλό στο 1–2 μ., μέσα σε σύννεφο μάλαγρας ψωμί-σαρδέλα, στον Μόλο και στις μύτες των μόλων, μέρα, Απρ–Οκτ."},"src":["limassol_s3","limassol_s9"]},{"gear":"shrimp","note":{"en":"Small peeled shrimp pieces on a no. 10–12 hook for the bigger fish holding under the bread cloud. General.","el":"Μικρά καθαρισμένα κομματάκια γαρίδας σε αγκίστρι Νο 10–12 για τα μεγαλύτερα που κάθονται κάτω από τη θολούρα του ψωμιού. Γενικό."}},{"gear":"sardine","note":{"en":"Thin sardine fillet strip drifted down the groundbait trail. General.","el":"Λεπτή λωρίδα φιλέτου σαρδέλας που κατεβαίνει μέσα στη μάλαγρα. Γενικό."}}],
    greymullet: [{"gear":"bread","best":true,"note":{"en":"Soft bread flake or crust on a small float, hook 8–10, over bread groundbait at the groynes and harbour mouths by day, May–Oct; keep it soft.","el":"Μαλακή ψίχα ή κόρα σε μικρό φελλό, αγκίστρι 8–10, πάνω από μάλαγρα ψωμιού στους μόλους και στα στόμια των λιμανιών τη μέρα, Μάι–Οκτ· να μένει μαλακό."},"src":["limassol_s9","limassol_s21","limassol_s3"]},{"gear":"sardine","note":{"en":"Soft sardine-and-bread dough (apiko) on a small hook at the wall base, dawn and dusk; mullet nibble, so don't knead it hard.","el":"Μαλακό ζυμάρι σαρδέλας με ψωμί (απίκο) σε μικρό αγκίστρι στη βάση του τοίχου, χάραμα και σούρουπο· ο κέφαλος τσιμπολογά, μην το σφίγγεις."},"src":["limassol_s21","limassol_s9"]},{"gear":"groundbait","note":{"en":"Bread-sardine mash thrown just behind the float, allowing for current, so the cloud sits on the hook bait in clear harbour water.","el":"Μάλαγρα ψωμί-σαρδέλα λίγο πίσω από τον φελλό, υπολογίζοντας το ρεύμα, ώστε η θολούρα να μένει πάνω στο δόλωμα στα καθαρά νερά."},"src":["limassol_s9","limassol_s21"]}],
    squid: [{"gear":"sardine","best":true,"note":{"en":"Fresh oily sardine on a kafteró under a float with a chemical light, two baits at different depths off the outer groynes, dusk to 2 h after, Nov–Mar.","el":"Φρέσκια λιπαρή σαρδέλα σε καφτερό κάτω από φελλό με χημικό φωτάκι, δύο δολώματα σε διαφορετικά βάθη στους εξωτερικούς μόλους, σούρουπο ως 2 ώρες μετά, Νοέ–Μαρ."},"src":["limassol_s16","limassol_s13"]},{"gear":"live_fish","note":{"en":"A small live fish (bogue, sand smelt) on a kafteró, drifted from a boat over 15–40 m at dusk. General practice, no local source.","el":"Μικρό ζωντανό ψαράκι (γόππα, αθερίνα) σε καφτερό, ντρίφτ από βάρκα σε 15–40 μ. το σούρουπο. Γενική πρακτική, χωρίς τοπική πηγή."}}],
    cuttlefish: [{"gear":"sardine","best":true,"note":{"en":"Small dead fish (sardine, bogue) bound to a bait jig, dragged slowly over sand and Posidonia by the groynes at dusk, Feb–May. General; sources thin.","el":"Μικρό νεκρό ψάρι (σαρδέλα, γόππα) δεμένο σε καλαμαριέρα, σέρνεται αργά σε άμμο και ποσειδωνία δίπλα στους μόλους το σούρουπο, Φεβ–Μάι. Γενικό· λίγες πηγές."},"src":["limassol_s24"]},{"gear":"live_fish","note":{"en":"Small live fish on a float set just off the bottom over sand-weed at dusk and night; cuttlefish hunt small fish and shrimp. General.","el":"Μικρό ζωντανό ψαράκι σε φελλό, λίγο πάνω από τον βυθό σε άμμο με φύκια, σούρουπο και νύχτα· η σουπιά κυνηγά ψαράκια και γαριδούλες. Γενικό."},"src":["limassol_s23"]}],
    amberjack: [{"gear":"live_fish","best":true,"note":{"en":"Live bogue (γόππα) or horse mackerel 10–20 cm from a sabiki, dropped or slow-trolled under 1 knot over rough ground at 20–70 m, Jun–Nov, dawn.","el":"Ζωντανή γόππα ή σαυρίδι 10–20 εκ. από τσαπαρί, κάθετα ή σε αργή συρτή κάτω από 1 κόμβο σε πέτρα στα 20–70 μ., Ιούν–Νοέ, χαράματα."},"src":["limassol_s5","limassol_s17","limassol_s10"]},{"gear":"squid_bait","note":{"en":"Live squid (Nov–Mar) or live cuttlefish in spring, towed tail-first on a lead; picks out the bigger fish.","el":"Ζωντανό καλαμάρι (Νοέ–Μαρ) ή ζωντανή σουπιά την άνοιξη, σε συρτή φύλακα από την ουρά· διαλέγει τα μεγάλα."},"src":["limassol_s17"]}],
    bluefish: [{"gear":"sardine","best":true,"note":{"en":"Whole or half fresh sardine on a long-shank hook or short wire, cast from the outer groynes at dusk and night, Oct–Jan; their teeth cut mono.","el":"Ολόκληρη ή μισή φρέσκια σαρδέλα σε μακρύλαιμο αγκίστρι ή κοντό συρματάκι, από τους εξωτερικούς μόλους σούρουπο και νύχτα, Οκτ–Ιαν· κόβει την πετονιά."},"src":["limassol_s10"]},{"gear":"live_fish","note":{"en":"Live garfish (ζαργάνα), sand smelt or small bogue, free-lined or slow-trolled where bluefish chase bait at first light. Cyprus-wide, not local.","el":"Ζωντανή ζαργάνα, αθερίνα ή μικρή γόππα, ελεύθερη ή σε αργή συρτή όπου κυνηγούν τα γοφάρια με το πρώτο φως. Για όλη την Κύπρο, όχι τοπικό."},"src":["limassol_s10"]},{"gear":"squid_bait","note":{"en":"Squid strip or a whole small squid: tough enough to survive their teeth; also a Cypriot trolling bait for bluefish.","el":"Λωρίδα καλαμαριού ή ολόκληρο μικρό καλαμάρι: αντέχει στα δόντια· χρησιμοποιείται και στη συρτή για γοφάρι στην Κύπρο."},"src":["limassol_s10"]}],
    pandora: [{"gear":"shrimp","best":true,"note":{"en":"Whole unpeeled shrimp threaded over two hooks on a bottom rig, on sand-Posidonia edges and coarse ground at 20–60 m, Apr–Aug, mornings.","el":"Ολόκληρη ακαθάριστη γαρίδα περασμένη σε δύο αγκίστρια, καθετή σε άκρες άμμου-ποσειδωνίας και χοντρό βυθό στα 20–60 μ., Απρ–Αύγ, πρωί."},"src":["limassol_s18"]},{"gear":"squid_bait","note":{"en":"Squid tentacle or strip: stays on when small fish or puffers strip shrimp (Limassol charter reviews mention puffers).","el":"Πλοκάμι ή λωρίδα καλαμαριού: μένει στο αγκίστρι όταν τα μικρά ή οι λαγοκέφαλοι καθαρίζουν τη γαρίδα (κριτικές σκαφών της Λεμεσού αναφέρουν λαγοκέφαλους)."},"src":["limassol_s18","limassol_s5"]},{"gear":"worm","note":{"en":"Thick worm (μάνα, American) on the shallower 15–30 m ground in spring. General.","el":"Χοντρό σκουλήκι (μάνα, αμερικάνος) στα ρηχότερα 15–30 μ. την άνοιξη. Γενικό."},"src":["limassol_s11"]}],
    littletunny: [{"gear":"live_fish","best":true,"note":{"en":"Live sand smelt (αθερίνα) or small horse mackerel free-lined into a feeding school or slow-trolled on the 50–100 m line, Aug–Nov. Local charters carry live bait.","el":"Ζωντανή αθερίνα ή μικρό σαυρίδι ελεύθερο μέσα στο κοπάδι ή σε αργή συρτή στη γραμμή 50–100 μ., Αύγ–Νοέ. Τα σκάφη της Λεμεσού έχουν ζωντανό δόλωμα."},"src":["limassol_s5","limassol_s7"]},{"gear":"sardine","note":{"en":"Sardine chunks drifted down a trail of chopped sardine from a drifting boat. General Mediterranean method, no local source.","el":"Κομμάτια σαρδέλας που κατεβαίνουν μέσα σε μάλαγρα από ψιλοκομμένη σαρδέλα, από βάρκα σε ντρίφτ. Γενική μέθοδος, χωρίς τοπική πηγή."}}],
    redmullet: [{"gear":"worm","best":true,"note":{"en":"Thin worm (τριχιά, red sand worm, or black) threaded on a needle, small fine-wire hook, drifted over sand-mud at 20–60 m by day, Sep–Mar.","el":"Λεπτό σκουλήκι (τριχιά, κόκκινο της άμμου ή μαύρο) περασμένο με βελόνα, μικρό λεπτό αγκίστρι, ντρίφτ σε άμμο-λάσπη στα 20–60 μ. τη μέρα, Σεπ–Μαρ."},"src":["limassol_s19"]},{"gear":"shrimp","note":{"en":"Thin shrimp strips threaded like a worm when no worms are to hand. General.","el":"Λεπτές λωρίδες γαρίδας περασμένες σαν σκουλήκι όταν δεν υπάρχουν σκουλήκια. Γενικό."},"src":["limassol_s19"]}],
    octopus: [{"gear":"crab","best":true,"note":{"en":"Small crab tied on a white octopus jig, dragged slowly along breakwater bases and rock-sand edges at 2–15 m, dawn or dusk, Oct–May. General.","el":"Καβουράκι δεμένο σε άσπρη χταποδιέρα, σέρνεται αργά στις βάσεις των μόλων και στις άκρες πέτρας-άμμου στα 2–15 μ., χάραμα ή σούρουπο, Οκτ–Μάι. Γενικό."}},{"gear":"sardine","note":{"en":"Sardine doubled on two hooks with 2–3 white cloth strips tied over it: scent plus white draws octopus out. General Greek method.","el":"Σαρδέλα διπλαρωμένη σε δύο αγκίστρια με 2–3 λωρίδες άσπρο πανί από πάνω: η μυρωδιά και το άσπρο βγάζουν το χταπόδι. Γενική ελληνική μέθοδος."},"src":["limassol_s20"]}],
  },
  zygi: {
    sargos: [{"gear":"worm","best":true,"note":{"en":"Pharaoh worm (φαραώ), whole or a 4–5 cm piece, cast into the gullies of the rock platforms or off the Zygi breakwater from dusk into the night.","el":"Φαραώ, ολόκληρο ή κομμάτι 4–5 εκ., στα κανάλια των βραχωδών πλακών ή από τον μόλο του Ζυγίου, από το σούρουπο και μέσα στη νύχτα."},"src":["zygi_pcy_akti","zygi_bf_sargos","zygi_zygi_gr"]},{"gear":"mussel","note":{"en":"Mussel bound with elastic thread on a No 4–6 hook in the white water over the platforms; Cypriot anglers rate it especially for σαργοί.","el":"Μύδι δεμένο με λαστιχένια κλωστή σε αγκίστρι Νο 4–6, στον αφρό πάνω από τις πλάκες· στην Κύπρο το θεωρούν εκλεκτό δόλωμα ειδικά για σαργούς."},"src":["zygi_pcy_akti"]},{"gear":"shrimp","note":{"en":"Small live shrimp (γαριδούλα) on a light float, hook 8–10, over the shallow platforms at dawn and dusk when the water is a bit rough.","el":"Ζωντανή γαριδούλα σε ελαφρύ φελλό, αγκίστρι 8–10, πάνω από τις ρηχές πλάκες χαράματα και σούρουπο, όταν η θάλασσα είναι λίγο ταραγμένη."},"src":["zygi_bf_sargos"]},{"gear":"sardine","note":{"en":"Fresh sardine fillet at night in the foam; sardine-scented groundbait thrown the evening before helps hold them on the spot.","el":"Φρέσκο φιλέτο σαρδέλας τη νύχτα στον αφρό· μαλάγρα με μυρωδιά σαρδέλας από το προηγούμενο βράδυ τους κρατά στο σημείο."},"src":["zygi_bf_sargos","zygi_pcy_apiko"]}],
    parrotfish: [{"gear":"shrimp","best":true,"note":{"en":"Not a shrimp: live sea louse (φτείρα), a small rock crustacean ≥1 cm, hooked through the tail near the bottom. Cypriot σκάρος anglers use little else.","el":"Ζωντανή φτείρα (ψείρα της θάλασσας) τουλάχιστον 1 εκ., περασμένη από την ουρά, κοντά στον βυθό. Οι Κύπριοι σκαροψαράδες σχεδόν δεν βάζουν άλλο δόλωμα."},"src":["zygi_cfm_fteira","zygi_psarema_skaros"]},{"gear":"mussel","note":{"en":"Limpet (πεταλίδα) taken off the platforms, on a No 8–10 hook in the afternoon: tough enough to beat nibblers; a Cypriot report took σκάροι on it.","el":"Πεταλίδα από τις πλάκες, σε αγκίστρι Νο 8–10, το απόγευμα: σκληρή, δεν την ξεκοκαλίζουν τα μικρά· κυπριακό ρεπορτάζ έπιασε σκάρους μ' αυτήν."},"src":["zygi_cfm_petalida"]},{"gear":"bread","note":{"en":"Dough kneaded with purslane (γλιστρίδα) on a No 8–10 hook close to the rocks, May–Sep, early morning or dusk; small shrimp is the fallback.","el":"Ζυμάρι με γλιστρίδα σε αγκίστρι Νο 8–10 δίπλα στα βράχια, Μάιο–Σεπτέμβριο, νωρίς το πρωί ή σούρουπο· αλλιώς μικρή γαρίδα."},"src":["zygi_psarema_skaros"]}],
    rabbitfish: [{"gear":"bread","best":true,"note":{"en":"Bread-and-cheese dough on a No 14–16 hook, 0.14–0.18 leader, light float over the platforms or in the Zygi shelter; first hours after sunrise.","el":"Ζυμάρι ψωμιού-τυριού σε σαλαγκιά Νο 14–16, παράμαλλο 0,14–0,18, ελαφρύς φελλός πάνω από τις πλάκες ή στο καταφύγιο του Ζυγίου· τις πρώτες ώρες μετά την ανατολή."},"src":["zygi_fishingcy_kourk","zygi_cfm_kourk","zygi_zygi_gr"]},{"gear":"groundbait","note":{"en":"Bread groundbait (μπασμός) on the same spot for a few days, thrown at least 30 min before first light; it brings and holds the shoal.","el":"Μπασμός με ψωμί στο ίδιο σημείο για μερικές μέρες, τουλάχιστον μισή ώρα πριν χαράξει· φέρνει και κρατά το κοπάδι."},"src":["zygi_cfm_mpasm"]},{"gear":"algae","note":{"en":"Soft green weed (sea lettuce) wrapped on a small hook in summer: its natural food. General practice; Cypriot sources mostly fish dough.","el":"Μαλακό πράσινο φύκι (θαλάσσιο μαρούλι) τυλιγμένο σε μικρό αγκίστρι το καλοκαίρι: η φυσική της τροφή. Γενική πρακτική· οι Κύπριοι ψαρεύουν κυρίως με ζύμες."},"src":["zygi_fb_siganus"]}],
    squid: [{"gear":"sardine","best":true,"note":{"en":"Fresh sardine (or a small red mullet) on a squid needle (καφτερό) with a chemical light, off the Zygi shelter mouth, Nov–Mar from dusk; set 2 baits at 2 depths.","el":"Φρέσκια σαρδέλα (ή μικρή κουτσομούρα) σε καφτερό με χημικό φωτάκι, στο στόμιο του καταφυγίου του Ζυγίου, Νοέ–Μάρ από το σούρουπο· 2 δολώματα σε 2 βάθη."},"src":["zygi_zygi_en","zygi_cfm_kalam","zygi_bf_kalam"]},{"gear":"live_fish","note":{"en":"A live small fish (bogue, picarel) on a squid gaff under a float at dusk. General practice; no local source found.","el":"Ζωντανό μικρό ψαράκι (γόππα, μαρίδα) σε καμάκι για καλαμάρια κάτω από φελλό το σούρουπο. Γενική πρακτική· δεν βρέθηκε τοπική πηγή."}}],
    tsipoura: [{"gear":"worm","best":true,"note":{"en":"Whole pharaoh worm (φαραώ) on a needle, cast long from Governor's Beach or Mazotos (the shelf is gentle), at dawn and dusk, Oct–Mar.","el":"Ολόκληρο φαραώ περασμένο με βελόνα, μακρινή ρίψη από Governor's Beach ή Μαζωτό (η κλίση είναι ήπια), χαράματα και σούρουπο, Οκτ–Μάρ."},"src":["zygi_pcy_akti","zygi_alllim","zygi_dom"]},{"gear":"crab","note":{"en":"Whole small crab or a claw on the sand–Posidonia edge: the big ones take it and small fish can't strip it. Calm, sunny winter days.","el":"Ολόκληρο καβουράκι ή δαγκάνα στην άκρη άμμου–ποσειδωνίας: το παίρνουν οι μεγάλες και τα μικρά δεν το κλέβουν. Ήρεμες, ηλιόλουστες μέρες του χειμώνα."},"src":["zygi_bf_tsip","zygi_alllim"]},{"gear":"squid_bait","note":{"en":"Squid strip or a small whole squid, cast far over flat sand in winter–early spring, when Zygi's squid are in; stays on the hook.","el":"Λωρίδα ή μικρό ολόκληρο καλαμάρι, μακριά πάνω από επίπεδη άμμο χειμώνα–αρχές άνοιξης, που έχει καλαμάρια στο Ζύγι· κρατά στο αγκίστρι."},"src":["zygi_cfm_dolw","zygi_zygi_en"]}],
    melanouri: [{"gear":"bread","best":true,"note":{"en":"Bread flake or soft dough, hook 12–14, under a light float in the groundbait cloud off the Zygi breakwater, at dawn and dusk.","el":"Ψίχα ή μαλακό ζυμάρι, αγκίστρι 12–14, σε ελαφρύ φελλό μέσα στο σύννεφο της μαλάγρας στον μόλο του Ζυγίου, χαράματα και σούρουπο."},"src":["zygi_pcy_akti","zygi_pcy_apiko"]},{"gear":"groundbait","note":{"en":"Sardine groundbait (mashed sardine with bread and sand) thrown little and often; μελανούρια rise into the cloud near the surface.","el":"Μαλάγρα σαρδέλας (λιωμένη σαρδέλα με ψωμί και άμμο), λίγη και συχνά· τα μελανούρια ανεβαίνουν στο σύννεφο κοντά στην επιφάνεια."},"src":["zygi_pcy_apiko"]},{"gear":"shrimp","note":{"en":"Small peeled shrimp pieces when the bread is being stripped by small fry. General practice; no local source.","el":"Μικρά κομματάκια καθαρισμένης γαρίδας όταν τα μικρά ξεκοκαλίζουν το ψωμί. Γενική πρακτική· χωρίς τοπική πηγή."}}],
    amberjack: [{"gear":"live_fish","best":true,"note":{"en":"Live bogue (γόππα) or small mullet 15–20 cm, hooked through the head, slow-drifted near the offshore fish farms (outside 100 m), Jun–Nov, dawn.","el":"Ζωντανή γόππα ή μικρός κέφαλος 15–20 εκ., από το κεφάλι, σε αργό ντρίφτ κοντά στις ιχθυοκαλλιέργειες (έξω από τα 100 μ.), Ιούν–Νοέ, χαράματα."},"src":["zygi_pcy_fish","zygi_dr_mag"]},{"gear":"squid_bait","note":{"en":"Live squid caught at dusk off Zygi in winter, hooked at the tail, slow-trolled under 1 knot on a weighted line at 30–60 m (Nov–Mar).","el":"Ζωντανό καλαμάρι που πιάστηκε το σούρουπο στο Ζύγι τον χειμώνα, από την ουρά, σε συρτή φύλακα κάτω από 1 κόμβο στα 30–60 μ. (Νοέ–Μάρ)."},"src":["zygi_zygi_en","zygi_dr_mag"]}],
    bluefish: [{"gear":"sardine","best":true,"note":{"en":"Whole or half fresh sardine (or picarel, μαρίδα) on a long-shank hook, slow-trolled or drifted at dusk; Cypriot boat anglers' standard bait.","el":"Ολόκληρη ή μισή φρέσκια σαρδέλα (ή μαρίδα) σε αγκίστρι με μακρύ λαιμό, σε αργή συρτή ή ντρίφτ το σούρουπο· το συνηθισμένο δόλωμα των Κυπρίων από σκάφος."},"src":["zygi_pcy_fish"]},{"gear":"live_fish","note":{"en":"Garfish (ζαργάνα) or sand smelt (θερινά), live or fresh, slow-trolled along the 10–30 m line or off the rocky points at dawn.","el":"Ζαργάνα ή θερινά, ζωντανά ή φρέσκα, σε αργή συρτή στη γραμμή των 10–30 μ. ή έξω από τα βραχώδη ακρωτήρια τα χαράματα."},"src":["zygi_pcy_fish"]}],
    redmullet: [{"gear":"worm","best":true,"note":{"en":"Thin worms (red sand worm, τριχιά; else black or acrobat) threaded on a needle, drifting sand and Posidonia edges at 15–40 m off Zygi, Sep–Mar.","el":"Λεπτά σκουλήκια (κόκκινο της άμμου, τριχιά· αλλιώς μαύρο ή ακροβάτης) με βελόνα, σε ντρίφτ στις άκρες άμμου–ποσειδωνίας στα 15–40 μ. έξω από το Ζύγι, Σεπ–Μάρ."},"src":["zygi_dr_barb","zygi_zygi_gr"]},{"gear":"shrimp","note":{"en":"Thin, long shrimp strips when worms run out; drag a toothed sinker lightly to raise silt and draw the shoal.","el":"Λεπτές, μακριές λωρίδες γαρίδας όταν τελειώσουν τα σκουλήκια· σέρνε ελαφρά οδοντωτό μολύβι για να σηκώνει λάσπη και να τραβά το κοπάδι."},"src":["zygi_dr_barb"]}],
    pandora: [{"gear":"shrimp","best":true,"note":{"en":"Whole shrimp, threaded neatly with no loose ends, hook 2–6, over coarse sand and Posidonia edges at 20–60 m off Zygi.","el":"Ολόκληρη γαρίδα, περασμένη καθαρά χωρίς ακρίτσες, αγκίστρι 2–6, σε χοντρή άμμο και άκρες ποσειδωνίας στα 20–60 μ. έξω από το Ζύγι."},"src":["zygi_bf_lyth","zygi_zygi_gr"]},{"gear":"squid_bait","note":{"en":"Squid tentacle: stays on and filters out small fish; easy to get fresh in winter, when Zygi's squid are in, and that is when the big pandora bite.","el":"Πλοκάμι καλαμαριού: κρατά και «φιλτράρει» τα μικρά· εύκολα φρέσκο τον χειμώνα που έχει καλαμάρια στο Ζύγι, τότε που τσιμπούν και τα μεγάλα λυθρίνια."},"src":["zygi_bf_lyth","zygi_zygi_en"]}],
    porgy: [{"gear":"squid_bait","best":true,"note":{"en":"Squid strip or a small whole squid (Zygi's own winter squid) on a big hook over rough ground at 30–80 m; tough, so small fish can't strip it.","el":"Λωρίδα ή μικρό ολόκληρο καλαμάρι (τα χειμωνιάτικα του Ζυγίου) σε μεγάλο αγκίστρι σε τραγανό στα 30–80 μ.· σκληρό, δεν το κλέβουν τα μικρά."},"src":["zygi_bf_fagk","zygi_zygi_en"]},{"gear":"sardine","note":{"en":"Fresh sardine or bogue, head and tail cut so it bleeds, or salted mackerel chunks 2.5–3 cm; best just before sunset and before sunrise.","el":"Φρέσκια σαρδέλα ή γόππα, κομμένο κεφάλι και ουρά για να ματώνει, ή αλατισμένο σκουμπρί σε μπουκιές 2,5–3 εκ.· καλύτερα πριν τη δύση και πριν την ανατολή."},"src":["zygi_bf_fagk"]}],
    octopus: [{"gear":"sardine","best":true,"note":{"en":"Fresh small fish (sardine, bogue) or a chicken foot tied on a weighted octopus jig, dragged slowly over rock and Posidonia at 2–15 m, Oct–Apr, mornings.","el":"Νωπό ψαράκι (σαρδέλα, γόππα) ή κοτοπόδαρο δεμένο σε χταποδιέρα με βάρος, σέρνοντας αργά σε βράχο και ποσειδωνία στα 2–15 μ., Οκτ–Απρ, πρωινές ώρες."},"src":["zygi_dr_xtap","zygi_zygi_gr"]},{"gear":"crab","note":{"en":"A small real crab bound on a white octopus jig, dragged along rock edges. General practice; no local source names the bait.","el":"Μικρό αληθινό καβούρι δεμένο σε άσπρη χταποδιέρα, σέρνοντας στις άκρες των βράχων. Γενική πρακτική· καμία τοπική πηγή δεν αναφέρει το δόλωμα."}}],
    cuttlefish: [{"gear":"sardine","best":true,"note":{"en":"Dead small fish (sardine, bogue) bound to a cuttlefish jig, dragged slowly over sand and Posidonia at 3–15 m, Feb–May. General; no local source.","el":"Νεκρό ψαράκι (σαρδέλα, γόππα) δεμένο σε σουπιέρα, σέρνοντας αργά σε άμμο και ποσειδωνία στα 3–15 μ., Φεβ–Μάι. Γενική πρακτική· χωρίς τοπική πηγή."}},{"gear":"live_fish","note":{"en":"A live small fish under a float drifted over the Posidonia at dusk; cuttlefish ambush it. General practice, unsourced.","el":"Ζωντανό ψαράκι κάτω από φελλό πάνω από την ποσειδωνία το σούρουπο· η σουπιά το παραφυλάει. Γενική πρακτική, χωρίς πηγή."}}],
    greymullet: [{"gear":"bread","best":true,"note":{"en":"Soft bread-and-cheese dough or bread flake, hook No 7–8, inside the Zygi shelter; mullet suck the bait, so keep it soft. Dawn and dusk, summer–autumn.","el":"Μαλακό ζυμάρι ψωμιού-τυριού ή ψίχα, αγκίστρι Νο 7–8, μέσα στο καταφύγιο του Ζυγίου· ο κέφαλος ρουφά, θέλει μαλακό δόλωμα. Χαράματα και σούρουπο, καλοκαίρι–φθινόπωρο."},"src":["zygi_bf_kef","zygi_pcy_apiko"]},{"gear":"sardine","note":{"en":"Sardine dough: ~500 g boned sardine, a quarter loaf of soaked bread, a little oil, firmed with rusk; add water if bites don't hook.","el":"Ζυμάρι σαρδέλας: ~500 γρ. σαρδέλα χωρίς κόκαλο, ένα τέταρτο καρβέλι μουσκεμένο ψωμί, λίγο λάδι, σφιγμένο με φρυγανιά· λίγο νερό αν δεν καρφώνουν."},"src":["zygi_bf_kef"]},{"gear":"groundbait","note":{"en":"Sand and gravel soaked in sardine and used frying oil, thrown the evening before and fished in the morning; same scent as the hook bait.","el":"Άμμος και χαλίκι ποτισμένα με σαρδέλα και τηγανόλαδα, ρίχνεις το βράδυ και ψαρεύεις το πρωί· ίδια μυρωδιά με το δόλωμα."},"src":["zygi_pcy_apiko"]}],
  },
  larnaca: {
    tsipoura: [{"gear":"worm","best":true,"note":{"en":"Pharaoh (φαραώ) or whole American worm on a needle; long casts at night Oct–Mar to the sand–Posidonia edge off the Dhekelia-road beaches. General Cyprus pick.","el":"Φαραώ ή ολόκληρο αμερικάνικο σκουλήκι με βελόνα· μακριές βολές τη νύχτα Οκτ–Μαρ στο όριο άμμου–ποσειδωνίας στις παραλίες του δρόμου Δεκέλειας. Γενική οδηγία."},"src":["larnaca_s6","larnaca_s11","larnaca_s18"]},{"gear":"crab","note":{"en":"Whole small shore crab (σκαλτσίνι) by the groyne tips: it survives small fish and the toadfish (λαγοκέφαλος) common in this bay. General bait pick.","el":"Ολόκληρο μικρό καβουράκι (σκαλτσίνι) δίπλα στις άκρες των μόλων: αντέχει τα μικρά ψάρια και τον λαγοκέφαλο, που είναι πολύ κοινός στον κόλπο. Γενική οδηγία."},"src":["larnaca_s9","larnaca_s18","larnaca_s5"]},{"gear":"shrimp","note":{"en":"Live shrimp (καραβιδάκι) on a light rig along the marina and fishing-shelter walls at dawn or dusk, where locals take bream on simple bait.","el":"Ζωντανό καραβιδάκι με ελαφριά αρματωσιά στους τοίχους της μαρίνας και του καταφυγίου, χαράματα ή σούρουπο, εκεί που οι ντόπιοι πιάνουν σπαροειδή με απλό δόλωμα."},"src":["larnaca_s9","larnaca_s6","larnaca_s2","larnaca_s1"]}],
    sargos: [{"gear":"worm","best":true,"note":{"en":"Pharaoh (φαραώ), a piece pinched off by hand, on a float or light ledger by groyne and marina boulders at dusk and night. Cyprus's top sargos bait; general.","el":"Κομμάτι φαραώ κομμένο με το χέρι, με φελλό ή ελαφρύ μολύβι στις πέτρες των μόλων και της μαρίνας, σούρουπο και νύχτα. Κορυφαίο δόλωμα για σαργό στην Κύπρο· γενικό."},"src":["larnaca_s6","larnaca_s11","larnaca_s12"]},{"gear":"shrimp","note":{"en":"Small live shrimp (γαριδούλα) netted among the boulders, under a float along the groyne and marina rocks in the early morning. General Cyprus pick.","el":"Ζωντανή γαριδούλα, πιασμένη με απόχη ανάμεσα στις πέτρες, με φελλό στα βράχια των μόλων και της μαρίνας νωρίς το πρωί. Γενική οδηγία."},"src":["larnaca_s6","larnaca_s9"]},{"gear":"bread","note":{"en":"Firm bread–cheese–sardine dough under a float over sardine groundbait (απίκο) at the marina and shelter; sargos want it firmer than mullet do.","el":"Σφιχτή ζύμη από ψωμί, τυρί και σαρδέλα, με φελλό πάνω από μάλαγρα σαρδέλας (απίκο) στη μαρίνα και στο καταφύγιο· ο σαργός τη θέλει πιο σφιχτή από τον κέφαλο."},"src":["larnaca_s7","larnaca_s6","larnaca_s2"]},{"gear":"crab","note":{"en":"Small crab (σκαλτσίνι) picked off the groyne rocks after dark, for the bigger sargos at night. General Cyprus pick.","el":"Μικρό καβουράκι (σκαλτσίνι) μαζεμένο από τις πέτρες των μόλων μετά το σούρουπο, για τους μεγάλους σαργούς τη νύχτα. Γενική οδηγία."},"src":["larnaca_s6","larnaca_s9"]}],
    seabass: [{"gear":"live_fish","best":true,"note":{"en":"Live small σπάρος or mullet, hooked lightly under the skin behind the dorsal, at the fishing-shelter and marina mouths at night, Dec–Mar. General advice.","el":"Ζωντανός μικρός σπάρος ή κεφαλόπουλο, αγκιστρωμένο ελαφριά κάτω από το δέρμα πίσω από το ραχιαίο, στα στόμια καταφυγίου και μαρίνας τη νύχτα, Δεκ–Μαρ. Γενικό."},"src":["larnaca_s19","larnaca_s8"]},{"gear":"shrimp","note":{"en":"Live shrimp (καραβιδάκι) through the tail on a long light leader along the groyne tips at dawn, best in the murky water after a southerly. General.","el":"Ζωντανό καραβιδάκι από την ουρά με μακρύ λεπτό παράμαλλο στις άκρες των μόλων τα χαράματα, καλύτερα στα θολά νερά μετά από νοτιά. Γενική οδηγία."},"src":["larnaca_s6"]},{"gear":"sardine","note":{"en":"Fresh sardine fillet on a bottom rig at night off the beaches when the bay is murky after a blow; Cypriot anglers rate sardine for bass. General.","el":"Φρέσκο φιλέτο σαρδέλας στον βυθό τη νύχτα από τις παραλίες όταν ο κόλπος θολώνει μετά από καιρό· οι Κύπριοι ψαράδες το θεωρούν καλό για λαβράκι. Γενικό."},"src":["larnaca_s6"]}],
    cuttlefish: [{"gear":"sardine","best":true,"note":{"en":"Small sardine or bogue (γόππα) tied along a cuttlefish jig, dragged slowly over shallow sand–Posidonia off the groynes at dusk, Feb–May. Old method; general.","el":"Μικρή σαρδέλα ή γόππα δεμένη πάνω σε σουπιέρα, σέρνεται αργά σε ρηχή άμμο–ποσειδωνία έξω από τους μόλους το σούρουπο, Φεβ–Μάι. Παλιά μέθοδος· γενική."}},{"gear":"live_fish","note":{"en":"Live small fish (sand smelt, small bogue) under a float with a cuttlefish gaff over shallow sand and weed at dusk. Traditional; general, unsourced.","el":"Ζωντανό ψαράκι (αθερίνα, μικρή γόππα) με φελλό και σουπιέρα σε ρηχή άμμο με φύκια το σούρουπο. Παραδοσιακό· γενική οδηγία χωρίς πηγή."}}],
    squid: [{"gear":"sardine","best":true,"note":{"en":"Fresh sardine on a squid needle (καφτερό) under a lit float, off groyne tips over Posidonia at dusk and 1–2 h before dawn, Nov–Feb. General method.","el":"Φρέσκια σαρδέλα σε καφτερό με φελλό και χημικό φωτάκι, από τις άκρες των μόλων πάνω από ποσειδωνία, σούρουπο και 1–2 ώρες πριν ξημερώσει, Νοέ–Φεβ. Γενικό."},"src":["larnaca_s16","larnaca_s10"]},{"gear":"live_fish","note":{"en":"Live small fish (γόππα, sand smelt) on a squid needle at two depths from a drifting boat at dusk over 15–40 m. General, unsourced for Cyprus.","el":"Ζωντανό ψαράκι (γόππα, αθερίνα) σε καφτερό σε δύο βάθη από βάρκα σε ντρίφτ το σούρουπο, σε 15–40 μ. Γενική οδηγία χωρίς κυπριακή πηγή."}}],
    bluefish: [{"gear":"sardine","best":true,"note":{"en":"Half or filleted fresh sardine on a long-shank hook with a short wire trace, cast from groyne tips at dawn and dusk, Nov–Feb. General Cyprus advice.","el":"Μισή ή φιλεταρισμένη φρέσκια σαρδέλα σε αγκίστρι με μακρύ λαιμό και κοντό συρματάκι, από τις άκρες των μόλων χαράματα και σούρουπο, Νοέ–Φεβ. Γενικό."},"src":["larnaca_s6","larnaca_s8"]},{"gear":"live_fish","note":{"en":"Live garfish (ζαργάνα) or small bogue free-lined from a boat; Cypriots bait garfish for bluefish, and Larnaca boats target garfish in the bay.","el":"Ζωντανή ζαργάνα ή μικρή γόππα ελεύθερη από βάρκα· στην Κύπρο η ζαργάνα είναι δόλωμα για γοφάρι, και οι βάρκες της Λάρνακας ψαρεύουν ζαργάνες στον κόλπο."},"src":["larnaca_s8","larnaca_s4"]},{"gear":"squid_bait","note":{"en":"Squid strip on a wire trace: it stays on through toadfish and small bream, and is a Cypriot trolling bait for bluefish. General.","el":"Λωρίδα καλαμαριού με συρματάκι: μένει στο αγκίστρι παρά τους λαγοκέφαλους και τα μικρά ψάρια, και είναι κυπριακό δόλωμα συρτής για γοφάρι. Γενικό."},"src":["larnaca_s8","larnaca_s5"]}],
    greymullet: [{"gear":"bread","best":true,"note":{"en":"Soft bread or bread–cheese dough on size 14–18 hooks under a light float at the marina, fishing shelter and Finikoudes walls, where locals fish mullet.","el":"Μαλακό ψωμί ή ζύμη ψωμιού–τυριού σε αγκίστρια Νο 14–18 με ελαφρύ φελλό στη μαρίνα, στο καταφύγιο και στις Φοινικούδες, εκεί που ψαρεύουν κέφαλο οι ντόπιοι."},"src":["larnaca_s7","larnaca_s20","larnaca_s1","larnaca_s2"]},{"gear":"groundbait","note":{"en":"Soaked bread with sardine and oil, same flavour as the hook bait, in small balls; harbours need little, add 1–2 balls when bites slow.","el":"Μουσκεμένο ψωμί με σαρδέλα και λάδι, ίδια γεύση με το δόλωμα, σε μικρές μπάλες· στα λιμάνια θέλει λίγη, ρίξε 1–2 μπάλες όταν αραιώνουν οι τσιμπιές."},"src":["larnaca_s7","larnaca_s20"]},{"gear":"sardine","note":{"en":"Thin, long sardine strips on size 14–16 hooks when the harbour mullet ignore bread. General advice.","el":"Λεπτές μακρόστενες λωρίδες σαρδέλας σε αγκίστρια Νο 14–16, όταν οι κέφαλοι του λιμανιού αγνοούν το ψωμί. Γενική οδηγία."},"src":["larnaca_s20"]}],
    redmullet: [{"gear":"worm","best":true,"note":{"en":"Thin red sand worm or τριχιά on a needle, drifting sand–mud at 20–60 m. A Larnaca netsman reports no red mullet in 2+ years. General bait advice.","el":"Λεπτό κόκκινο σκουλήκι της άμμου ή τριχιά με βελόνα, σε ντρίφτ σε άμμο–λάσπη στα 20–60 μ. Ψαράς της Λάρνακας λέει ότι δεν έπιασε στρίλια 2+ χρόνια. Γενικό."},"src":["larnaca_s13","larnaca_s5"]},{"gear":"shrimp","note":{"en":"Shrimp cut into thin, long strips on a needle when worms run out; same drift over the bay's sand and mud. General advice.","el":"Γαρίδα κομμένη σε λεπτές μακρόστενες λωρίδες με βελόνα, όταν τελειώσουν τα σκουλήκια· ίδιο ντρίφτ στην άμμο και τη λάσπη του κόλπου. Γενική οδηγία."},"src":["larnaca_s13"]}],
    pandora: [{"gear":"shrimp","best":true,"note":{"en":"Whole unpeeled shrimp over two hooks, drifting sand–mud and rough patches at 20–60 m; Larnaca charters fish pandora here with dead bait.","el":"Ολόκληρη ακαθάριστη γαρίδα σε δύο αγκίστρια, σε ντρίφτ σε άμμο–λάσπη και τραχιά σημεία στα 20–60 μ.· τα ναυλωμένα σκάφη της Λάρνακας ψαρεύουν λυθρίνι με νεκρό δόλωμα."},"src":["larnaca_s14","larnaca_s3","larnaca_s4"]},{"gear":"squid_bait","note":{"en":"Squid tentacle or neat strip with no loose ends; stays on against toadfish and small fish, best for big pandora in winter–spring.","el":"Πλοκάμι ή καθαρή λωρίδα καλαμαριού χωρίς ακρίτσες· αντέχει λαγοκέφαλους και μικρά ψάρια, καλύτερο για μεγάλα λυθρίνια χειμώνα–άνοιξη."},"src":["larnaca_s14","larnaca_s5"]},{"gear":"worm","note":{"en":"Μάνα or American worm on the shallower 20–30 m sand; Cypriot anglers list μάνα for pandora. General advice.","el":"Μάνα ή αμερικάνικο σκουλήκι στην πιο ρηχή άμμο στα 20–30 μ.· οι Κύπριοι ψαράδες αναφέρουν τη μάνα για λυθρίνια. Γενική οδηγία."},"src":["larnaca_s11"]}],
    littletunny: [{"gear":"live_fish","best":true,"note":{"en":"Live bogue or small horse mackerel from the live well, free-lined into feeding schools in the bay, Aug–Nov; Larnaca port charters carry live bait.","el":"Ζωντανή γόππα ή μικρό σαυρίδι από το ιχθυοδοχείο, ελεύθερο μέσα στα κοπάδια που τρώνε στον κόλπο, Αύγ–Νοέ· τα σκάφη από το λιμάνι Λάρνακας έχουν ζωντανό δόλωμα."},"src":["larnaca_s4"]},{"gear":"sardine","note":{"en":"Sardine chunks as chum with a whole sardine drifting in the slick from a drifting boat. General method, unsourced for Cyprus.","el":"Κομμάτια σαρδέλας για μάλαγρα και ολόκληρη σαρδέλα να κατεβαίνει μαζί τους από βάρκα σε ντρίφτ. Γενική μέθοδος χωρίς κυπριακή πηγή."}}],
    porgy: [{"gear":"squid_bait","best":true,"note":{"en":"Whole small squid or thick strips on rough ground at the shelf edge past 100 m, 4–8 km out; tough and ignored by small fish. General advice.","el":"Ολόκληρο μικρό καλαμάρι ή χοντρές λωρίδες στα τραχιά της άκρης της υφαλοκρηπίδας πέρα από τα 100 μ., 4–8 χλμ. έξω· αντέχει και δεν το τρώνε τα μικρά. Γενικό."},"src":["larnaca_s17"]},{"gear":"sardine","note":{"en":"Fresh sardine or bogue with head and tail cut so it bleeds, or salted mackerel pieces 2.5–3 cm; set before sunset and before dawn. General.","el":"Φρέσκια σαρδέλα ή γόππα με κομμένο κεφάλι και ουρά για να ματώνει, ή αλατισμένο σκουμπρί σε κομμάτια 2,5–3 εκ.· πριν τη δύση και πριν την αυγή. Γενικό."},"src":["larnaca_s17"]},{"gear":"live_fish","note":{"en":"Live bogue or horse mackerel on the deep rough patches for the biggest porgy, Jan–Apr. General advice; no Larnaca reports found.","el":"Ζωντανή γόππα ή σαυρίδι στα βαθιά τραχιά σημεία για τα μεγαλύτερα φαγκριά, Ιαν–Απρ. Γενική οδηγία· δεν βρέθηκαν αναφορές από τη Λάρνακα."}}],
    octopus: [{"gear":"crab","best":true,"note":{"en":"Shore crab bound to a white octopus jig, dragged slowly over sand–Posidonia and along the groyne boulders. Classic method; general, unsourced.","el":"Καβούρι δεμένο σε άσπρη χταποδιέρα, σέρνεται αργά σε άμμο–ποσειδωνία και δίπλα στις πέτρες των μόλων. Κλασική μέθοδος· γενική οδηγία χωρίς πηγή."}},{"gear":"sardine","note":{"en":"Small sardine on two #1 hooks tied to one ring, white cloth strips above, worked by the groyne boulders or from a drifting boat. General.","el":"Μικρή σαρδέλα σε δύο αγκίστρια Νο 1 δεμένα στον ίδιο κρίκο, με άσπρες λωρίδες πανιού από πάνω, στις πέτρες των μόλων ή από βάρκα. Γενική οδηγία."},"src":["larnaca_s15"]}],
  },
  ayianapa: {
    leerfish: [{"gear":"live_fish","best":true,"note":{"en":"Live grey mullet (κέφαλος) or bogue 15–20 cm, back-hooked a few metres under a small float off the points west of town, dawn/dusk, Sep–Dec. General.","el":"Ζωντανός κέφαλος ή γόππα 15–20 εκ., από την πλάτη, λίγα μέτρα κάτω από μικρό φελλό στους κάβους δυτικά της πόλης, χαράματα/σούρουπο, Σεπ–Δεκ. Γενικό."},"src":["ayianapa_hf_litsa","ayianapa_cyf"]},{"gear":"sardine","note":{"en":"From a boat with no live bait: a very fresh whole bogue or garfish (βελονίδα) slow-trolled along the rocky points at first light. General, not local.","el":"Από βάρκα χωρίς ζωντανό: ολόφρεσκη γόππα ή βελονίδα σε αργή συρτή κατά μήκος των βραχωδών κάβων με το πρώτο φως. Γενικό, όχι τοπικό."},"src":["ayianapa_hf_litsa"]}],
    bluefish: [{"gear":"sardine","best":true,"note":{"en":"Whole or half fresh sardine on a wire trace, cast from the rocks west of town at dusk and into the night, Oct–Jan; rebait often. Cyprus-wide, not local.","el":"Ολόκληρη ή μισή φρέσκια σαρδέλα σε συρματάκι, πεταχτή από τα βράχια δυτικά της πόλης σούρουπο και νύχτα, Οκτ–Ιαν· αλλάζε συχνά. Γενικό για Κύπρο."},"src":["ayianapa_pcy_fish","ayianapa_cyf"]},{"gear":"live_fish","note":{"en":"Live bogue (γόππα) or horse mackerel (σαυρίδι) 10–15 cm, free-lined on wire where bait shoals are pushed to the surface at first light. General.","el":"Ζωντανή γόππα ή σαυρίδι 10–15 εκ., ελεύθερο σε συρματάκι εκεί που τα μικρόψαρα πετάγονται στην επιφάνεια με το πρώτο φως. Γενικό."},"src":["ayianapa_pcy_fish","ayianapa_cyf"]},{"gear":"squid_bait","note":{"en":"Strip of fresh squid on a long-shank hook: survives several bites from those teeth when sardine is stripped fast. Listed as a γοφάρι bait in Cyprus.","el":"Λωρίδα φρέσκου καλαμαριού σε αγκίστρι με μακρύ λαιμό: αντέχει πολλές δαγκωνιές όταν η σαρδέλα φεύγει γρήγορα. Αναφέρεται ως δόλωμα για γοφάρι στην Κύπρο."},"src":["ayianapa_pcy_fish"]}],
    littletunny: [{"gear":"live_fish","best":true,"note":{"en":"Live horse mackerel or bogue 8–12 cm from a sabiki, free-lined on light fluoro into a feeding school; Aug–Nov, early morning and dusk. General.","el":"Ζωντανό σαυρίδι ή γόππα 8–12 εκ. από τσαπαρί, ελεύθερο με λεπτό fluoro μέσα στο κοπάδι που τρώει· Αύγ–Νοέ, πρωί και σούρουπο. Γενικό."},"src":["ayianapa_socr","ayianapa_cyf","ayianapa_bf_tuna"]},{"gear":"sardine","note":{"en":"From a drifting boat: chum sardine pieces to hold the school, then drift a whole sardine unweighted in the slick. General Med practice, not reported here.","el":"Από βάρκα σε ντρίφτο: ρίχνε κομμάτια σαρδέλας να κρατήσεις το κοπάδι και άφηνε ολόκληρη σαρδέλα χωρίς βαρίδι μέσα. Γενική πρακτική, όχι τοπική."}}],
    barracuda: [{"gear":"live_fish","best":true,"note":{"en":"Live bogue or garfish (βελονίδα) 12–20 cm on wire under a float, sunset to full dark, off the harbour wall and points west of town; Sep–Oct peak.","el":"Ζωντανή γόππα ή βελονίδα 12–20 εκ. σε σύρμα με φελλό, από τη δύση ως να σκοτεινιάσει, στον μόλο του λιμανιού και στους κάβους δυτικά· κορύφωση Σεπ–Οκτ."},"src":["ayianapa_dr_loutsos","ayianapa_tui","ayianapa_cyf"]},{"gear":"sardine","note":{"en":"Very fresh garfish or sardine as a long fillet strip, slow-trolled or twitched at dusk; Greek anglers rate fresh garfish the top barracuda bait.","el":"Ολόφρεσκη βελονίδα ή σαρδέλα σε μακριά λωρίδα φιλέτου, σε αργή συρτή ή με τινάγματα το σούρουπο· η φρέσκια βελονίδα θεωρείται το νούμερο ένα."},"src":["ayianapa_dr_loutsos"]}],
    sargos: [{"gear":"worm","best":true,"note":{"en":"Pharaoh worm (φαραώ) on a cast bottom rig at night, onto sand gaps between the rocks west of town; Cypriot blogs' top σορκός bait. Oct–Apr.","el":"Φαραώ σε πεταχτάρι τη νύχτα, στα αμμουδερά κενά ανάμεσα στα βράχια δυτικά της πόλης· το κορυφαίο δόλωμα για σορκό κατά τα κυπριακά blogs. Οκτ–Απρ."},"src":["ayianapa_pcy_shore","ayianapa_pcy_baits","ayianapa_fcy_cast"]},{"gear":"crab","note":{"en":"Live small crab or hermit crab (καρτσίνα, σκαλτσίνι) tight to the rocks after dark for the big fish; small bait robbers can't strip it.","el":"Ζωντανή καρτσίνα ή σκαλτσίνι κοντά στα βράχια μετά το σκοτάδι για τους μεγάλους σορκούς· τα μικρά ψάρια δεν μπορούν να το φάνε."},"src":["ayianapa_pcy_shore","ayianapa_fcy_baits"]},{"gear":"shrimp","note":{"en":"Live small shrimp (καραβιδάκι) under a float in the foam along the rocks or harbour wall at dawn; red shrimp stays on the hook best.","el":"Ζωντανό καραβιδάκι σε φελλό μέσα στον αφρό στα βράχια ή στον μόλο τα χαράματα· το κόκκινο κρατά καλύτερα στο αγκίστρι."},"src":["ayianapa_pcy_shore","ayianapa_pcy_baits"]},{"gear":"sardine","note":{"en":"Sardine-fillet dough firmed with breadcrumbs, over sardine groundbait on deeper rocky spots: the Cypriot apiko method. Groundbait the evening before.","el":"Ζύμη από φιλέτο σαρδέλας με φρυγανιά, πάνω σε μαλάγρα σαρδέλας σε βαθιά βραχώδη σημεία: το κυπριακό άπικο. Μαλάγρωσε από το βράδυ."},"src":["ayianapa_pcy_apiko"]}],
    squid: [{"gear":"sardine","best":true,"note":{"en":"Fresh sardine, bogue or small mackerel on a squid needle (καφτερό) under a lit float, harbour wall and rocky coves at dusk, Nov–Mar. General.","el":"Φρέσκια σαρδέλα, γόππα ή μικρός κολιός σε καφτερό κάτω από φελλό με φωτάκι, στον μόλο και σε βραχώδεις κολπίσκους το σούρουπο, Νοέ–Μαρ. Γενικό."},"src":["ayianapa_bf_squid","ayianapa_pcy_squid","ayianapa_mate"]},{"gear":"live_fish","note":{"en":"A live sand smelt (αθερίνα) or small horse mackerel on the needle moves naturally, which helps in this very clear water. General practice.","el":"Ζωντανή αθερίνα ή μικρό σαυρίδι στο καφτερό κινείται φυσικά, κάτι που βοηθά σε αυτά τα πολύ καθαρά νερά. Γενική πρακτική."}}],
    melanouri: [{"gear":"sardine","best":true,"note":{"en":"Soft sardine-fillet dough with breadcrumbs, pea-sized on a #8–10 hook and 50 cm leader, in a sardine groundbait trail off deeper rocks; Apr–Oct mornings.","el":"Μαλακή ζύμη από φιλέτο σαρδέλας με φρυγανιά, σαν ρεβίθι σε αγκίστρι 8–10 με παράμαλλο 50 εκ., μέσα σε μαλάγρα σαρδέλας στα βαθιά βράχια· Απρ–Οκτ πρωί."},"src":["ayianapa_pcy_apiko"]},{"gear":"bread","note":{"en":"Bread flake on a light float in the white water where waves hit the rocks west of town or the harbour wall; best on a choppy morning. General.","el":"Ψίχα ψωμιού σε ελαφρύ φελλό στον αφρό όπου σπάζει το κύμα στα βράχια δυτικά της πόλης ή στον μόλο· καλύτερα πρωί με κυματάκι. Γενικό."}},{"gear":"shrimp","note":{"en":"Small live shrimp (καραβιδάκι) or a peeled piece on a bolognese rig in the harbour: Cypriot harbour bait for μελάνα and σορκός.","el":"Ζωντανό καραβιδάκι ή καθαρισμένο κομματάκι γαρίδας σε μπολονέζ μέσα στο λιμάνι: κυπριακό δόλωμα λιμανιού για μελάνα και σορκό."},"src":["ayianapa_pcy_shore"]}],
    albacore: [{"gear":"sardine","best":true,"note":{"en":"After a trolling strike, chum sardine chunks and drift a whole sardine on 0.40–0.50 fluoro to hold the school; Jun–Jul. General: lures stay the main method.","el":"Μετά από χτύπημα στη συρτή, ρίχνε κομμάτια σαρδέλας και άφηνε ολόκληρη σαρδέλα σε fluoro 0,40–0,50 να κρατήσεις το κοπάδι· Ιούν–Ιούλ. Κύρια μέθοδος η συρτή."},"src":["ayianapa_socr","ayianapa_mate"]},{"gear":"live_fish","note":{"en":"Live mackerel or horse mackerel from a sabiki, slow-trolled or drifted where birds and breaking fish show. General practice, not reported locally.","el":"Ζωντανός κολιός ή σαυρίδι από τσαπαρί, σε αργή συρτή ή ντρίφτο εκεί που δείχνουν πουλιά και ψάρια στην επιφάνεια. Γενικό, όχι τοπικό."}}],
    dolphinfish: [{"gear":"live_fish","best":true,"note":{"en":"Live horse mackerel or bogue 10–15 cm free-lined beside floating debris or weed lines a few miles out, late Aug–Nov; local charters carry live bait.","el":"Ζωντανό σαυρίδι ή γόππα 10–15 εκ. ελεύθερο δίπλα σε επιπλέοντα αντικείμενα ή γραμμές φυκιών λίγα μίλια έξω, τέλη Αύγ–Νοέ· τα τοπικά σκάφη έχουν ζωντανό."},"src":["ayianapa_letsgo","ayianapa_mate","ayianapa_bf_kyn","ayianapa_fwg"]},{"gear":"sardine","note":{"en":"Once a school is at the boat, throw fresh sardine pieces to hold it and drift a hooked half sardine among them while others cast.","el":"Μόλις το κοπάδι έρθει στη βάρκα, ρίχνε κομμάτια φρέσκιας σαρδέλας να το κρατήσεις και άφηνε μισή σαρδέλα με αγκίστρι ανάμεσά τους."},"src":["ayianapa_bf_kyn"]},{"gear":"squid_bait","note":{"en":"Small fresh squid, whole or in strips, used the same way; stays on the hook through more bites than sardine.","el":"Μικρό φρέσκο καλαμαράκι, ολόκληρο ή σε λωρίδες, με τον ίδιο τρόπο· αντέχει περισσότερα τσιμπήματα από τη σαρδέλα."},"src":["ayianapa_bf_kyn"]}],
    dentex: [{"gear":"squid_bait","best":true,"note":{"en":"Live medium squid slow-trolled at 0.5–1.5 knots just off the bottom along drop-offs outside the MPA, early morning; local boats jig squid on winter nights.","el":"Ζωντανό μεσαίο καλαμάρι σε αργή συρτή 0,5–1,5 κόμβων κοντά στον βυθό στις κατωφέρειες έξω από τη ΘΠΠ, νωρίς το πρωί· εδώ τα πιάνουν τις χειμωνιάτικες νύχτες."},"src":["ayianapa_bf_dentex","ayianapa_mate"]},{"gear":"live_fish","note":{"en":"Live bogue, horse mackerel or mackerel from a sabiki on the same slow troll or drift when no squid; Pernera/Paralimni boats carry live-bait wells.","el":"Ζωντανή γόππα, σαυρίδι ή κολιός από τσαπαρί στην ίδια αργή συρτή ή στο ντρίφτο όταν δεν έχει καλαμάρι· τα σκάφη Περνέρας/Παραλιμνίου έχουν δεξαμενή ζωντανών."},"src":["ayianapa_mate","ayianapa_letsgo","ayianapa_cyf"]}],
    grouper: [{"gear":"live_fish","best":true,"note":{"en":"Live bogue or horse mackerel 12–18 cm on a strong leader, held just above rocky ledges at 20–50 m outside the MPA, at dusk. ορφός minimum 45 cm.","el":"Ζωντανή γόππα ή σαυρίδι 12–18 εκ. σε γερό παράμαλλο, λίγο πάνω από βραχώδεις πεζούλες στα 20–50 μ. έξω από τη ΘΠΠ, το σούρουπο. Ελάχιστο μέγεθος ορφού 45 εκ."},"src":["ayianapa_letsgo","ayianapa_pcy_fish"]},{"gear":"squid_bait","note":{"en":"Small whole octopus, cuttlefish or squid on a two-hook rig: fits its diet of fish and cephalopods and lasts longer against morays on this rock.","el":"Μικρό ολόκληρο χταπόδι, σουπιά ή καλαμάρι σε αρματωσιά με δύο αγκίστρια: ταιριάζει στη διατροφή του και αντέχει τις σμέρνες σε αυτόν τον βράχο."},"src":["ayianapa_pcy_fish"]},{"gear":"sardine","note":{"en":"Whole fresh sardine works, but pufferfish (λαγοκέφαλοι) are a common catch on local bottom trips and often take it first; backup only.","el":"Ολόκληρη φρέσκια σαρδέλα πιάνει, αλλά οι λαγοκέφαλοι πιάνονται συχνά στα τοπικά ψαρέματα βυθού και συνήθως την παίρνουν πρώτοι· μόνο εφεδρεία."},"src":["ayianapa_socr","ayianapa_mate"]}],
    porgy: [{"gear":"squid_bait","best":true,"note":{"en":"Squid strip or small whole squid on a bottom rig over rock and coarse ground at 30–80 m, dawn and dusk, Jan–Apr; tough enough to outlast pufferfish.","el":"Λωρίδα ή μικρό ολόκληρο καλαμάρι σε αρματωσιά βυθού σε βράχο και χοντρό βυθό στα 30–80 μ., χαράματα και σούρουπο, Ιαν–Απρ· αντέχει τους λαγοκέφαλους."},"src":["ayianapa_bf_fagk","ayianapa_socr"]},{"gear":"worm","note":{"en":"Pharaoh worm (φαραώ) or μάνα: Cypriot bait guides list both for φαγκρί; best on lighter rigs when porgy come shallower in winter.","el":"Φαραώ ή μάνα: οι κυπριακοί οδηγοί δολωμάτων τα αναφέρουν και τα δύο για φαγκρί· καλύτερα σε πιο ελαφριές αρματωσιές όταν ανεβαίνει τον χειμώνα."},"src":["ayianapa_pcy_baits","ayianapa_fcy_baits"]},{"gear":"shrimp","note":{"en":"Red shrimp (κόκκινο καραβιδάκι): Cypriot guides list it for φαγκρί; works in all seasons and stays on the hook on the drop.","el":"Κόκκινο καραβιδάκι: οι κυπριακοί οδηγοί το αναφέρουν για φαγκρί· δουλεύει όλες τις εποχές και κρατά καλά στο αγκίστρι."},"src":["ayianapa_pcy_baits"]},{"gear":"sardine","note":{"en":"Fresh sardine or bogue with head and tail cut so it bleeds, or 2.5–3 cm cubes of salted mackerel; pufferfish strip soft fish fast.","el":"Φρέσκια σαρδέλα ή γόππα κομμένη κεφάλι και ουρά για να ματώνει, ή κύβοι 2,5–3 εκ. αλατισμένου κολιού· οι λαγοκέφαλοι τρώνε γρήγορα τα μαλακά."},"src":["ayianapa_bf_fagk","ayianapa_socr"]}],
    octopus: [{"gear":"crab","best":true,"note":{"en":"Small crab (καρτσίνα) tied on a white octopus jig, dragged slowly over rock–sand edges from the harbour wall or a drifting boat; Oct–May, mornings.","el":"Μικρή καρτσίνα δεμένη σε άσπρη χταποδιέρα, σερνόμενη αργά σε όρια βράχου–άμμου από τον μόλο ή από βάρκα σε ντρίφτο· Οκτ–Μάι, πρωινές ώρες."},"src":["ayianapa_dr_xtap"]},{"gear":"sardine","note":{"en":"Fresh small fish (sardine, bogue) bound to the jig with elastic thread; chicken feet are the traditional alternative.","el":"Νωπά ψαράκια (σαρδέλα, γόππα) δεμένα στη χταποδιέρα με λαστιχένια κλωστή· παραδοσιακή εναλλακτική τα κοτοπόδαρα."},"src":["ayianapa_dr_xtap"]}],
    parrotfish: [{"gear":"shrimp","best":true,"note":{"en":"Small shrimp on a #10–12 hook, float-fished over shallow weedy rock on calm sunny days, Jun–Sep when σκάροι come inshore to spawn.","el":"Γαριδάκι σε αγκίστρι 10–12 με φελλό, πάνω από ρηχά βράχια με φύκια, σε ήρεμες ηλιόλουστες μέρες, Ιούν–Σεπ όταν οι σκάροι πλησιάζουν για αναπαραγωγή."},"src":["ayianapa_pg_skaros","ayianapa_pcy_fish"]},{"gear":"bread","note":{"en":"Bread or cheese dough, also mixed with purslane (γλιστρίδα), on a small hook: the same dough Cypriots float-fish for κουρκούνα on these rocks.","el":"Ζύμη ψωμιού ή τυριού, και με γλιστρίδα, σε μικρό αγκίστρι: η ίδια ζύμη που βάζουν οι Κύπριοι στον φελλό για κουρκούνα σε αυτά τα βράχια."},"src":["ayianapa_pg_skaros","ayianapa_fcy_kourk"]},{"gear":"worm","note":{"en":"Acrobat worm (ακροβάτης), a short piece on the same light float rig.","el":"Ακροβάτης, κοντό κομμάτι στην ίδια ελαφριά αρματωσιά με φελλό."},"src":["ayianapa_pg_skaros"]}],
    lionfish: [{"gear":"shrimp","best":true,"note":{"en":"Small whole shrimp on a #8–10 hook beside ledges and holes at dusk; an occasional catch only, and the densest lionfish reefs are inside the MPA.","el":"Μικρή ολόκληρη γαρίδα σε αγκίστρι 8–10 δίπλα σε πεζούλες και τρύπες το σούρουπο· πιάνεται μόνο περιστασιακά, και οι πυκνότεροι ύφαλοι είναι μέσα στη ΘΠΠ."},"src":["ayianapa_relion"]},{"gear":"sardine","note":{"en":"A small strip of fresh bogue or sardine worked tight to structure. General, little evidence; handle with gloves, the spines are venomous.","el":"Μικρή λωρίδα φρέσκιας γόππας ή σαρδέλας κοντά στα βράχια. Γενικό, λίγα στοιχεία· πιάσ' το με γάντια, τα αγκάθια είναι δηλητηριώδη."}}],
  },
  protaras: {
    littletunny: [{"gear":"live_fish","best":true,"note":{"en":"Live sardine, μαρίδα or small horse mackerel (8–12 cm) free-lined into feeding schools off the points, Aug–Nov at first light. General Cyprus practice.","el":"Ζωντανή σαρδέλα, μαρίδα ή μικρό σαυρίδι (8–12 εκ.) ελεύθερο μέσα στα κοπάδια που τρώνε έξω από τα ακρωτήρια, Αύγ–Νοέ με το πρώτο φως. Γενική πρακτική στην Κύπρο."},"src":["protaras_cfm_karv"]},{"gear":"sardine","note":{"en":"Whole fresh sardine on a light fluorocarbon leader, drifted in a chum line of sardine chunks or on a handline (καθετή) once a school holds near the boat.","el":"Ολόκληρη φρέσκια σαρδέλα σε λεπτό fluorocarbon, μέσα σε μαλάγρα από κομμάτια σαρδέλας ή με καθετή, όταν το κοπάδι μείνει κοντά στο σκάφος."},"src":["protaras_cfm_karv"]}],
    bluefish: [{"gear":"sardine","best":true,"note":{"en":"Whole fresh sardine (or two, hooked behind the eyes and looped) cast off the rocky points from dusk into night, Oct–Jan; long-shank hook or short wire.","el":"Ολόκληρη φρέσκια σαρδέλα (ή δύο, περασμένες πίσω από τα μάτια και δεμένες θηλιά) στα βραχώδη ακρωτήρια από το σούρουπο ως τη νύχτα, Οκτ–Ιαν· μακρύλαιμο αγκίστρι ή κοντό συρματάκι."},"src":["protaras_pcy_shore","protaras_pcy_fish"]},{"gear":"live_fish","note":{"en":"Live μαρίδα, small horse mackerel or garfish, free-lined or under a float off the points at first light, when bluefish drive bait into the bays.","el":"Ζωντανή μαρίδα, μικρό σαυρίδι ή ζαργάνα, ελεύθερα ή με φελλό μπροστά στα ακρωτήρια με το πρώτο φως, όταν τα γοφάρια σπρώχνουν το μικρόψαρο στους κόλπους."},"src":["protaras_pcy_fish"]},{"gear":"squid_bait","note":{"en":"Squid strip 2 cm wide, 1.5× hook length, slit into a fluttering tail; tough for long casts, best Dec–Mar when squid are inshore.","el":"Λωρίδα καλαμαριού 2 εκ., μιάμιση φορά το αγκίστρι, σχισμένη σε ουρά που κουνιέται· αντέχει στις μακρινές βολές, καλύτερα Δεκ–Μαρ που τα καλαμάρια είναι κοντά."},"src":["protaras_cfm_sqbait","protaras_pcy_fish"]}],
    barracuda: [{"gear":"live_fish","best":true,"note":{"en":"Live garfish (ζαργάνα) or small mullet, slow-trolled or under a float along the rocky points at dusk and dawn, Aug–Dec; wire or 0.50 mm fluoro trace.","el":"Ζωντανή ζαργάνα ή μικρός κέφαλος, σε αργή συρτή ή με φελλό κατά μήκος των βραχωδών ακρωτηρίων σούρουπο και χαράματα, Αύγ–Δεκ· συρματάκι ή fluorocarbon 0,50."},"src":["protaras_pcy_fish","protaras_tui"]},{"gear":"squid_bait","note":{"en":"Squid strip cut with a fluttering tail on a one-hook clipped rig, cast off the points at dusk; best Nov–Mar when squid are inshore.","el":"Λωρίδα καλαμαριού κομμένη με ουρά, σε παράμαλλο ενός αγκιστριού (clipped), βολή στα ακρωτήρια το σούρουπο· καλύτερα Νοέ–Μαρ που τα καλαμάρια είναι κοντά."},"src":["protaras_cfm_sqbait"]},{"gear":"sardine","note":{"en":"Half fresh sardine under a lighted float near the jetty lights at night, Sep–Dec. General practice, not a local report.","el":"Μισή φρέσκια σαρδέλα με φελλό με φωτάκι κοντά στα φώτα των προβλήτων τη νύχτα, Σεπ–Δεκ. Γενική πρακτική, όχι τοπική αναφορά."}}],
    squid: [{"gear":"sardine","best":true,"note":{"en":"Fresh sardine on a squid needle (καφτερό) under a lighted float, dusk to 2 h after, Nov–Mar, off jetties and rocks where Posidonia lies close in.","el":"Φρέσκια σαρδέλα σε καφτερό κάτω από φελλό με φωτάκι, από το σούρουπο ως 2 ώρες μετά, Νοέ–Μαρ, σε προβλήτες και βράχια με ποσειδωνία κοντά στην ακτή."},"src":["protaras_cfm_sqboat","protaras_fb_goangler"]},{"gear":"live_fish","note":{"en":"Small live fish (γόππα or μαρίδα, 8–10 cm) on a needle rig drifted from the boat: under 20 m over Posidonia at night, 50 m+ by day.","el":"Μικρό ζωντανό ψαράκι (γόππα ή μαρίδα, 8–10 εκ.) σε καφτερό, σε ντρίφτ από το σκάφος: κάτω από 20 μ. πάνω από ποσειδωνία τη νύχτα, 50 μ.+ τη μέρα."},"src":["protaras_cfm_sqboat","protaras_fb_goangler"]}],
    sargos: [{"gear":"worm","best":true,"note":{"en":"Pharaoh worm (φαραώ), a big piece, in the foam off the rocky points at dusk and after dark, Oct–Feb; whole American worm for casting. Rated best sargos bait in Cyprus.","el":"Φαραώ, μεγάλο κομμάτι, στον αφρό των βραχωδών ακρωτηρίων σούρουπο και νύχτα, Οκτ–Φεβ· αμερικάνος ολόκληρος για πεταχτάρι. Το καλύτερο δόλωμα για σορκό."},"src":["protaras_pcy_shore"]},{"gear":"squid_bait","note":{"en":"Fresh squid strip 1–1.5 cm wide wound 4 times on a No 2 Aberdeen, cast from the rocks Jan–Mar when squid come inshore; tough, stays on.","el":"Λωρίδα φρέσκου καλαμαριού 1–1,5 εκ. τυλιγμένη 4 φορές σε Aberdeen Νο 2, βολή από τα βράχια Ιαν–Μαρ που τα καλαμάρια βγαίνουν κοντά· σκληρό, μένει στο αγκίστρι."},"src":["protaras_cfm_sqbait"]},{"gear":"sardine","note":{"en":"Sardine fillet kneaded with breadcrumbs into a firm paste (firmer than for mullet), over sardine groundbait thrown at dusk; fish it at dawn.","el":"Φιλέτο σαρδέλας ζυμωμένο με φρυγανιά σε σφιχτό ζυμάρι (ο σορκός το θέλει πιο σφιχτό από τον κέφαλο), πάνω σε μαλάγρα σαρδέλας από το βράδυ· ψάρεμα το πρωί."},"src":["protaras_pcy_apiko"]},{"gear":"crab","note":{"en":"Small live rock crab (καρτσίνα) taken off the same rocks, hooked through the side, at night for the big fish; small bream leave it alone.","el":"Μικρή ζωντανή καρτσίνα από τα ίδια βράχια, περασμένη από το πλάι, τη νύχτα για τους μεγάλους σορκούς· τα μικρά σπαροειδή δεν την πειράζουν."},"src":["protaras_pcy_shore"]}],
    melanouri: [{"gear":"bread","best":true,"note":{"en":"Soft bread flake on a No 10–12 under a light float, in a cloud of wet bread groundbait off the rocky points at first light; best Apr–Jun and Oct–Nov.","el":"Μαλακή ψίχα ψωμιού σε αγκίστρι Νο 10–12 με ελαφρύ φελλό, μέσα σε σύννεφο από βρεγμένο ψωμί στα βραχώδη ακρωτήρια με το πρώτο φως· καλύτερα Απρ–Ιούν και Οκτ–Νοέ."}},{"gear":"sardine","note":{"en":"Thin fresh sardine strips or sardine-breadcrumb paste over sardine groundbait in the foam; better than bread when the sea is rough.","el":"Λεπτές λωρίδες φρέσκιας σαρδέλας ή ζυμάρι σαρδέλας με φρυγανιά πάνω σε μαλάγρα σαρδέλας στον αφρό· καλύτερα από το ψωμί όταν έχει κύμα."},"src":["protaras_pcy_apiko"]},{"gear":"shrimp","note":{"en":"Small peeled shrimp pieces, or a live γαριδούλα netted among the rocks, on a No 10 when the fish refuse bread in calm, clear water.","el":"Μικρά κομματάκια καθαρισμένης γαρίδας ή ζωντανή γαριδούλα από τα βραχάκια σε αγκίστρι Νο 10, όταν με ήρεμα καθαρά νερά δεν τρώνε ψωμί."},"src":["protaras_pcy_shore"]}],
    amberjack: [{"gear":"live_fish","best":true,"note":{"en":"Live bogue (γόππα) or horse mackerel 15–20 cm from a sabiki over the Posidonia, sent down to the 30–60 m drop-off at dawn, Sep–Nov; circle hook.","el":"Ζωντανή γόππα ή σαυρίδι 15–20 εκ. από τσαπαρί πάνω από την ποσειδωνία, κάτω στην κατωφέρεια των 30–60 μ. τα χαράματα, Σεπ–Νοέ· αγκίστρι circle."},"src":["protaras_pcy_fish","protaras_fb_seaze"]},{"gear":"squid_bait","note":{"en":"Live squid jigged the night before (Nov–Mar) or live cuttlefish (spring–summer), slow-trolled on a lead along the edges: the big-fish bait in Cyprus.","el":"Ζωντανό καλαμάρι από το βραδινό ψάρεμα (Νοέ–Μαρ) ή ζωντανή σουπιά (άνοιξη–καλοκαίρι), σε αργή συρτή με μολύβι στις άκρες: το δόλωμα για μεγάλα μινέρια στην Κύπρο."},"src":["protaras_cfm_livesquid","protaras_cfm_cuttle","protaras_fb_goangler"]}],
    grouper: [{"gear":"live_fish","best":true,"note":{"en":"Live bogue (γόππα) or horse mackerel 15–20 cm on a big hook, held just off the rock on the 25–60 m drop-off, Jun–Oct; big bait keeps baby groupers off.","el":"Ζωντανή γόππα ή σαυρίδι 15–20 εκ. σε μεγάλο αγκίστρι, λίγο πάνω από τον βράχο στην κατωφέρεια των 25–60 μ., Ιούν–Οκτ· το μεγάλο δόλωμα κρατά μακριά τους μικρούς ορφούς."},"src":["protaras_fb_seaze","protaras_cfm_forum"]},{"gear":"squid_bait","note":{"en":"Whole small octopus, cuttlefish or squid on a two-hook rig, tight to holes and ledges. General: Greek practice rates octopus first; no local report.","el":"Ολόκληρο μικρό χταπόδι, σουπιά ή καλαμάρι σε αρματωσιά με δύο αγκίστρια, κολλητά σε τρύπες και σπηλιές. Γενικό: στην Ελλάδα πρώτο το χταπόδι· όχι τοπική αναφορά."}},{"gear":"sardine","note":{"en":"Whole fresh sardine as a back-up only: on this reef morays and pufferfish usually reach dead bait first.","el":"Ολόκληρη φρέσκια σαρδέλα μόνο ως εφεδρεία: σε αυτή την ξέρα τα νεκρά δολώματα τα βρίσκουν συνήθως πρώτα οι σμέρνες και οι λαγοκέφαλοι."},"src":["protaras_fb_goangler"]}],
    dentex: [{"gear":"squid_bait","best":true,"note":{"en":"Live squid (medium, jigged at night Nov–Mar) or live cuttlefish in spring, on a 2-hook rig over 25–60 m rocky edges at dawn; fresh squid if none alive.","el":"Ζωντανό καλαμάρι (μεσαίο, από το βραδινό ψάρεμα Νοέ–Μαρ) ή ζωντανή σουπιά την άνοιξη, με 2 αγκίστρια στις βραχώδεις άκρες 25–60 μ. τα χαράματα· αλλιώς φρέσκο."},"src":["protaras_cfm_livesquid","protaras_cfm_cuttle","protaras_fb_goangler"]},{"gear":"live_fish","note":{"en":"Live bogue, small horse mackerel or garfish (ζαργάνα), slow-trolled on a lead along the drop-off at dawn, peak Apr–May; let it run before striking.","el":"Ζωντανή γόππα, μικρό σαυρίδι ή ζαργάνα, σε αργή συρτή με μολύβι κατά μήκος της κατωφέρειας τα χαράματα, κορύφωση Απρ–Μάι· άφησε να τραβήξει πριν καρφώσεις."},"src":["protaras_pcy_fish","protaras_fb_seaze"]}],
    dolphinfish: [{"gear":"live_fish","best":true,"note":{"en":"Live μαρίδα, γόππα or small horse mackerel (10–12 cm) free-lined beside floating debris or weed lines a few km out, Sep–Nov, late morning.","el":"Ζωντανή μαρίδα, γόππα ή μικρό σαυρίδι (10–12 εκ.) ελεύθερο δίπλα σε ό,τι επιπλέει ή σε γραμμές με φύκια λίγα χλμ. έξω, Σεπ–Νοέ, προς το μεσημέρι."},"src":["protaras_cfm_kyn","protaras_fbblog","protaras_fb_goangler"]},{"gear":"sardine","note":{"en":"Fresh sardine chunks thrown to hold the school at the boat, with a hooked half sardine drifted among them while others cast lures.","el":"Κομμάτια φρέσκιας σαρδέλας για να κρατήσεις το κοπάδι στο σκάφος, με μισή σαρδέλα στο αγκίστρι ανάμεσά τους ενώ οι άλλοι ρίχνουν τεχνητά."},"src":["protaras_cfm_kyn"]},{"gear":"squid_bait","note":{"en":"Squid strip free-lined among the school when fish turn shy of lures; squid is part of their autumn diet.","el":"Λωρίδα καλαμαριού ελεύθερη μέσα στο κοπάδι όταν τα ψάρια αποφεύγουν τα τεχνητά· το καλαμάρι είναι μέρος της φθινοπωρινής τους τροφής."},"src":["protaras_cfm_kyn"]}],
    albacore: [{"gear":"sardine","best":true,"note":{"en":"Whole fresh sardines and chunks drifted down a sardine chum line once a trolling strike finds a school, Jun–Aug; trolled lures stay the main method here.","el":"Ολόκληρες φρέσκιες σαρδέλες και κομμάτια σε μαλάγρα σαρδέλας μόλις η συρτή βρει κοπάδι, Ιούν–Αύγ· εδώ η κύρια μέθοδος μένει η συρτή με τεχνητά."},"src":["protaras_fb_goangler","protaras_tui"]},{"gear":"live_fish","note":{"en":"Live small mackerel or horse mackerel from a sabiki, drifted on a long fluorocarbon leader where albacore broke surface. General, not local.","el":"Ζωντανός μικρός κολιός ή σαυρίδι από τσαπαρί, ελεύθερος σε μακρύ fluorocarbon εκεί που βγήκαν τα τονάκια. Γενική πρακτική, όχι τοπική."}}],
    octopus: [{"gear":"crab","best":true,"note":{"en":"Small crab tied on a white octopus lure (σαγλαγκιά), dragged slowly with pauses over the rock–sand edges of the bays in 3–20 m, Oct–Apr; jetties too.","el":"Μικρό καβουράκι δεμένο σε άσπρη σαγλαγκιά, σέρνεται αργά με παύσεις στις άκρες βράχου–άμμου των κόλπων σε 3–20 μ., Οκτ–Απρ· και από τις προβλήτες."},"src":["protaras_cfm_sqboat"]},{"gear":"sardine","note":{"en":"Whole fresh sardine or fish head tied on the lure; a chicken leg is the cheap traditional option. General Cyprus practice.","el":"Ολόκληρη φρέσκια σαρδέλα ή κεφάλι ψαριού δεμένο στη σαγλαγκιά· το κοτοπόδαρο είναι η φθηνή παραδοσιακή λύση. Γενική πρακτική στην Κύπρο."}}],
    lionfish: [{"gear":"shrimp","best":true,"note":{"en":"Small whole shrimp on a No 6–8 hook dropped tight to rock overhangs at dusk. Hook catches are rare: in Cyprus most lionfish are speared or netted.","el":"Μικρή ολόκληρη γαρίδα σε αγκίστρι Νο 6–8 κολλητά σε βραχοσπηλιές το σούρουπο. Σπάνια πιάνεται με αγκίστρι: στην Κύπρο πιάνεται κυρίως με ψαροντούφεκο ή δίχτυ."},"src":["protaras_cmail_lion","protaras_savva2020","protaras_cfm_lion","protaras_ciesm_lion"]},{"gear":"sardine","note":{"en":"Small strip of fresh sardine or bogue worked slowly beside rocky ledges; it eats small fish and shrimp. Incidental only; mind the spines.","el":"Μικρή λωρίδα φρέσκιας σαρδέλας ή γόππας, κουνημένη αργά δίπλα σε βραχώδεις σπηλιές· τρώει μικρόψαρα και γαρίδες. Μόνο περιστασιακά· προσοχή στα αγκάθια."},"src":["protaras_cmail_lion","protaras_savva2020"]}],
  },
};
